window.__D("text/ner-mitzva/c004",{"p":[[2800530245,"כל מה שעתיד לחפוץ ברצון של חסד פרטי כו' כאשר בא ונמשך בדרך פרט לדבר א' ויוצא מבחי' העצמיות להיות לו רצון עצמי הנעלם שהוא בחי' רצון קדום הנ\"ל אבל עדיין בלתי מלובש באותו הדבר כלל רק שהרצון הוא לעצמו עדיין כנ\"ל אך כאשר מלובש ופועל רצון לרצון בדבר הפרטי הזה כמו שמתלבש ופועל רצון לרצון בשכל ומחשבה בדבר פרט הזה הרי התהוות זה הרצון שבשכל ומח' לדבר זה הוא כמו התהוות בריאה חדשה ממקורו והוא מפני שבחי' רצון קדום הנ\"ל הוא המקור להתהוות הרצון לרצון הזה שבשכל כו' ונק' רצון לרצון זה בריאה שהרי אנו רואים שלא בכל העתים יהיה לאדם רצון לרצון פרטי כמו הרצון במסחור או בלימוד שבהכרח יש מקור המהווה לרצון זה הפרטי ונק' רצון לרצון זה וממילא מובן מאחר שלא בכל העתים נמשך הרצון לרצון זה וגם לפעמים יאיר אור רב ותקיף ולפעמים יאיר במיעוט וחלישות כו' נמצא מוכרח שגם המקור העושה ומהוה לרצון זה הנק' רצון לרצון הוא ג\"כ בא בבחי' התהוות יש מאין כמו השוחד שיעש' רצון לרצון ושכל לזכות תמיד מפני שהשוחד מגיע בעצמו' נפשו שמחמתו יומשך תמיד התהוות רצון לרצון של חסד וזכות ולהיפך לשונאו יתהווה תמיד רצון לרצון של דין כו' וכה\"ג וד\"ל. וידוע דכל רצון גלוי כלול מי' א\"כ גם הרצון לרצון זה כלול מי' ויש י' כחות ממילא יש י' מיני רצון לרצון שמתהווים כולם בבחי' יש מאין כו' וכ\"ז דוגמא להבין בבחי' ע\"ס דא\"ק שכללותם ענין רצון לרצון לבד שהרי הן בחי' ההעלם דע\"ס דאצי' שבגלוי כידוע וכמו כתר דחכמ' דאצי' שהוא הרצון שבשכל כו' שרשו בכתר שבחכמה דא\"ק שנק' רצון לרצון זה וכן כתר שבחסד דאצי' מכתר שבחסד דא\"ק כו' ואמנם התהוות ע\"ס דא\"ק עצמו הכל נמשך מבחי' הקו שנק' מקור התהוות כל רצונות לרצונות כו' להיותו עצם הרצון הפשוט שקדם בעצמו שיהיה כך כנ\"ל ע\"כ הוא פועל ועושה רצון לרצון בדרך פרט והוא מבחי' כתר דא\"ק עד בחי' מל' שבו שהוא בחי' רצון לרצון דמלוכה כו' ואמנם רק מבחי' אחרונה שברצון הקדום ההיולי הנ\"ל נעשה בחי' כתר דא\"ק שהוא רצון לרצון הנעלם שלמעל' מחכמה שברצון לרצון הנעלם כו' ועד\"ז כל עשר ספי' דא\"ק הכל בבחי' ההעלם ורצון לרצון לכל ע\"ס דאצי' שבא בבחי' גלוי כמו שיתבאר וד\"ל:\n<b>וזהו</b> שבחי' א\"ק נק' אדם דבריאה כו' כמו בחי' התהוות יש מאין כנראה בחוש שהתהוות הרצון לרצון לעתים מיוחדי' הוא בא כשאר התהוות איזה מציא' כו' והוא כמו התהוות המח' שהיא התהוות יש מאין לגבי עצמיו' הרצון שבנפשו כנראה בחוש שהרצון לרצון הבא בבחי' התהוות כנ\"ל תחלת התהוותו במח' דוקא כי המחשבה בחי' כלי לרצון שהרצון מתלבש במח' כמו וחשב לעשות<sup data-n=\"2795\">1</sup> כו' וכן תחלת התהוות רצון לרצון במח' הוא שנק' רצון שבמחשבה כו' וזהו כללות ענין כח\"ב דא\"ק שהוא בחי' התהוות פעולת אור רצון לרצון דרך פרט שבא במח\"ס<sup data-n=\"2796\">2</sup> כו' משא\"כ בבחי' הקו עצמו שלמעלה מבחי' פעולת התהוות רצון לרצון לדבר פרט במח' סתימאה ג\"כ כו' רק לעצמו עדיין חושב כל מה שיהיה כו' שכולל במחשבת עצמו עדיין ולא בהתהוות רצון במח' שחוץ ממנו כלל וד\"ל (ובל' הרמב\"ם היינו בידיעת עצמו ולא בידיעה שחוץ ממנו וכו' וכמ\"ש במ\"א<sup data-n=\"2797\">3</sup> ):\n(יט) <b>ומעתה</b> יש להבין בשרש ע\"ס הנאצלי' ששרשם מבחי' מל' דא\"ק כמ\"ש בע\"ח בשער הכללים<sup data-n=\"2798\">4</sup> דמבחי' מל' דא\"ק נעשה כתר",[["2795","1","<b>וחשב לעשות</b>: ירמי' כו, ג. לו, ג [ושם: אשר אנכי חשב לעשות]."],["2796","2","<b>במח\"ס</b>: אג: במחשבה סתימאה."],["2797","3","<b>ובל' הרמב\"ם. . במ\"א</b>: ראה הל' יסוה\"ת פ\"ב, ה\"ט-י. וראה גם מאמרי אדה\"א קונטרסים ע' רא."],["2798","4","<b>כמ\"ש בע\"ח בשער הכללים</b>: נסמן לעיל קיד, ב."]]],[2800530246,"דע\"י כו' והנה תחלה יש להקדי' בענין ע\"ס הגנוזו' בהעלם איך שיוצאי' לידי גלוי שזהו מ\"ש קורא הדורות מראש מראש דא\"ק<sup data-n=\"2799\">5</sup> כו' וא' בס\"י שזהו כשלהבת הקשורה בגחלת<sup data-n=\"2800\">6</sup> וכה\"ג יש דמיונות רבים ויובן יותר מי' כחות הנפש דהנה ידוע ענין העלם וגלוי אינו כהתפשטות כח מן העצם<sup data-n=\"2801\">7</sup> כמו כח הפועל שמתפשט בפעולה שזהו מהות<sup data-n=\"2802\">8</sup> כח העצם שנק' עו\"ע אלא כמו בחי' זיו ואור של העצם כהארת זיו אור השמש וכחיות אור הנפש בכלי הגוף וכהתחכמות מכח השכל וכה\"ג והיותר דמיון אמיתי לגלוי ההעלם הוא כמו גלוי התנוע' מן החי וכאותיות המח' ואותיות הדיבור וכה\"ג וכ\"ז יותר אמיתי מדמיון שלהבת הקשורה בהעלם בגחלת שאעפ\"י שבגחלת היה השלהבת בהעלם אבל הרי עכ\"פ ממהות חום שבגחלת יצא השלהב' ואין זה אמיתית ענין הגלוי שאינו רק כמו בחי' מראה וגוון לבד כגוון התפוח שאינו ממהות התפוח<sup data-n=\"2803\">9</sup> וכידוע וכך הוא בגלוי העל' עצם כחות הנפש כמו כח מדת החסד בעצם שגלוי שלו היינו כאשר מצד עצמיו' מדה זו בעצם הנפש הרי מתהוו' רצון ושכל של חסד וטוב תמיד ולהיפך במי שמדתו העצמית באכזריות מתהווה רצון ושכל לדין ועונש והנה התהוות מקור לרצון זה לחסד או לדין נחשב עדיין מעצם המדה שאינו נבדל הימנה כלל אבל מה שנולד רצון בגלוי לדין או להיפוכו זהו רק כמו בחי' התגלות מראה לעצם כהתגלות התנועה בעצם החי וכגלוי החיות בדבר נבדל שהוא הגוף שמפני שהוא חי בעצם מגלה חיותו בתנועה וכן מפני שהוא דבר חי בעצם מחיה גם לגוף הדומם שנק' חיי בשר כו' כי גלוי רצון זה בא בדבר נבדל שהוא ענין זה של חסד או דין אבל מקור המוליד רצון זה הוא בא מכח עצם המדה לבד ומובן ממילא בהיות שיש כמה אופני דברי' שיוליד רצון מיוחד לכ\"א ממקור א' שהוא תלוי בעצם המדה תמיד כו' וגם שכל המטה תמיד כלפי רצון וחסד היינו רק מצד עצם מדת החסד שמוליד תמיד רצון ושכל לחסד דוקא ויש כמה ענינים נבדלים ולכ\"א מוליד רצון ושכל בפ\"ע כו' וד\"ל:\n<b>ונמצא</b> שהרצון לרצון של חסד בכלל יוכל להוליד כמה רצונות של חסד בפרט בכמה ענינים שונים באופנים שונים מאד והכל ממקור אחד שהוא רצון הנעלם הנק' עצם הרצון של חסד מצד עצמיות המדה ההיולית רק שבא בדרך פרט להיות רצון לרצון זה בדבר פרט זה כו' וד\"ל. ומובן עכ\"פ שיש הפרש גדול בין גלוי הרצון לחסד שאינו רק בחי' גלוי ההעלם של עצם הרצון המוליד רצון זה שהוא בא מכח עצם המדה שהוא אינו בחי' נבדל כו' וד\"ל. ועד\"מ זה יובן ענין קורא הדורו' מראש דא\"ק כו' כמשל הקורא דבר שיצא מהעלמו לגלוי לחוץ כך כל עיקר בחי' ע\"ס דאצי' הוא שיצאו מהעלמם לגלוי בלבד וע\"כ נקראו בשם אורות או ספי' כמו זיו ואור וכמו כל בחי' גלוי ההעלם שאינו רק בבחי' אור וכבחי' מראה וגוון וכמו תנועת החי כו' והיינו כמו ויאצל מן הרוח<sup data-n=\"2804\">10</sup> שאין זה רוחו של משה רק בחי' גלוי אורו וזיוו לבד הוא שנאצל והופרש כגלוי שלהבת מן הגחלת וכה\"ג כו' וכ\"ז יובן ע\"פ משל הנ\"ל מענין גלוי הרצון בדבר נבדל שיוצא מהעלם עצם הרצון שמצד עצמיות כנ\"ל כך בחי' כתרים דע\"ס דאצי' הן רק בחי' גלוי רצון לגבי העלם עצם הרצון שנק' רצון לרצון שהוא בבחי' א\"ק כנ\"ל וכמו מבחי' העלם הרצון דחסד דא\"ק נמשך גלוי רצון לחסד דאצי' שנק' כתר דחסד כו' וכן מבחי' העלם רצון דחכמ' כו' אך כמו שמובן ממשל הנ\"ל שזהו הנק' התהוות",[["2799","5","<b>קורא הדורות. . דא\"ק</b>: ישעי' מא, ד. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתיא. שם ע' תתפח. קונטרסים ע' תלב."],["2800","6","<b>כשלהבת הקשורה בגחלת</b>: ס\"י פ\"א מ\"ז."],["2801","7","<b>העלם וגלוי. . כח מן העצם</b>: ראה מאמרי אדה\"א נ\"ך ע' קנח ואילך. וש\"נ."],["2802","8","<b>מהות</b>: אג: ממהות."],["2803","9","<b>כגוון התפוח. . התפוח</b>: ראה גם מאמרי אדה\"ז נביאים ע' ו [אתהלך לאזניא ע' קטז]. לקמן קכט, סע\"א ובהנסמן שם."],["2804","10","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה. ראה סה\"מ תקס\"ט ע' ריט."]]],[2800530247,"רצון לרצון הרי הוא בא בבחי' הכלל להוליד כמה מיני רצון וכמה<sup data-n=\"2805\">1</sup> ענינים אופנים<sup data-n=\"2806\">2</sup> שונים כו' כך מבחי' רצון לרצון לחסד בא\"ק נולד כמה מיני גלוי רצון של חסד באצי' והענין הוא דמבחי' המל' של מדה דא\"ק נעשה בחי' כתר דמדה דאצי' ובכללות הע\"ס הרי רק מבחי' מל' דא\"ק נעשה כתר דאצי' והוא רק מבחי' אותיות וגלוי עצם העלם הרצון נעשה אור העצם של גלוי רצון כו' (שהוא כמו שמבואר באות הי\"ח דרק מבחי' סוף מעשה דעצם הרצון נעשה רצון לרצון שהוא ע\"ס דא\"ק) (ע\"ד דוגמא מגלוי רצון שבדבור המשפיע נעש' עצם הרצון למקבל כמו שמאותיות גלוי השכל שבדבור שבמשפיע נעשה עצם אור השכל במקבל וכך רק מאותיות וגלוי חסד שבדבור דמשפיע נעשה אור הרצון לחסד למקבל כידוע בכל עו\"ע שמבחי' האחרונ' שבעילה<sup data-n=\"2807\">3</sup> נעשה ראש ושרש לעלול וכך מבחי' מל' דא\"ק בכלל נעשה בחי' כתר דע\"י כו' דהיינו מבחי' גלוי רצון לרצון שבדבור בלבד נעשה בחי' מקור כל גלוי רצון שמצד התענוג שנק' כתר דע\"י כו' וכמשי\"ת) והיינו כללות ענין הע\"ס דאצי' שיצאו מהעלם ע\"ס דא\"ק כמ\"ש קורא הדורות מראש כו':\n(כ) <b>והנה</b> קודם שיבואר ענין פרטי הע\"ס דאצי' יש להקדים ענין נקודה ספי' פרצוף<sup data-n=\"2808\">4</sup> כו' להיות ידוע ההפרש שבין בחי' התהו לבחי' התיקון בכלל די\"ס דתהו הן בבחי' נקודות<sup data-n=\"2809\">5</sup> לבד שהן בבחי' הכתרים ובעולם התיקון הוא בבחי' התחלקו' כל ספי' לי' ע\"כ ממילא נעשה בחי' התיקון שהוא בחי' ההתכללות ע\"י שם מ\"ה כו' וביאור הדברים ידוע שבחי' הנקודו' הוא בחי' העצמיות טרם שמתפשט כנקודה שהיא בלתי מתפשטת כו' כמו אור מדת החסד הנה בחי' עצמיו' דמדת החסד הוא בחי' הכתר שלו ואמנם אין הכונה על בחי' העצמיו' דמדת החסד כמו שהוא נטוע ומושרש בעצם הנפש שנק' יחידה כנ\"ל שהוא בחי' היולי לגמרי (כנ\"ל באות יו\"ד וי\"א) אלא הכונה הוא על בחי' גלוי הרצון לדבר חסד פרטי מן העלם חסד העצמיו' ההיולי שגם זה הרצון הוא בלתי התפשטו' עדיין רק כמו שהוא בלא טעם כלל לרצון זה למה רוצה בגלוי לחסד זה כו' ומכ\"ש שאין בו בחי' התחלקות אופני' שוני' או גם אם שכלו מטה כלפי חסד דוקא אין בו התחלקות אופני' שוני' אעפ\"י ששכל הנוטה בעצם לחסד ולזכות הוא בחי' חכמ' שבחסד העצמי אבל גם הוא רק בבחי' נקודה וכן נצח שבחסד זה הוא בא בבחי' נקודה ונמצא דגם שבחי' החסד העצמי הבא בגלוי כלול מי' רצון ושכל ומדות אבל אין בהם התחלקות ניכרת אלא כולן בבחי' נקודה א' והוא בחי' העקודים שעקודי' היו בכלי א'<sup data-n=\"2810\">6</sup> כו' ולזה בחי' ע\"ס דתהו הן בלתי מתיחדי' ומתכללי' זע\"ז אלא הן זת\"ז<sup data-n=\"2811\">7</sup> כמ\"ש וימלוך וימת<sup data-n=\"2812\">8</sup> כו' כמו רצון העצמי שבא בגלוי חסד הגם שכלול בו שכל כו' לא יתחבר עם רצון עצמי היפוכו הבא בבחי' הדין גם שהוא כלול משכל הנוטה בעצם כלפי דין כו' כי אין להם כלי שיוכלו להתכלל בו ב' הפכי' כאלה וכמו שנראה בחוש מי<sup data-n=\"2813\">9</sup> ששכלו מטה כלפי חסד בעצם לא יוכל לסבול בשום אופן למנגדו שהוא מי ששכלו מטה כלפי דין בעצם (כמחלוקת ב\"ש וב\"ה<sup data-n=\"2814\">10</sup> וכה\"ג דגם שמנגדו יקשה עליו ולא יוכל למצוא טעם ישתוק אבל לא יוכל להודות ולחזור בו להתכלל<sup data-n=\"2815\">11</sup> בדעה שמנגדו כלל כו') אבל בחי' התיקון היינו כאשר המדה בא מבחי' נקודה שלה להתפשטו' חוץ מן העצמיו' רצון ושכל שבה דהיינו כמו מדת החסד כאשר יולד",[["2805","1","<b>וכמה</b>: אג: בכמה."],["2806","2","<b>אופנים</b>: אוצ\"ל: ואופנים."],["2807","3","<b>שמבחי' האחרונ' שבעילה</b>: ראה לקו\"ת שלח מא, ד. סה\"מ תקס\"ח ח\"א ע' תלז. ע' תפב. ח\"ב ע' תריד."],["2808","4","<b>נקודה ספי' פרצוף</b>: ראה ע\"ח (שער הפרצופים) ש\"ל פ\"ז. מאמרי אדה\"א במדבר ח\"א ע' רסז. וש\"נ. תו\"ח נח סה, ד ובהערה 52. לעיל סד, ב."],["2809","5","<b>די\"ס דתהו. . נקודות</b>: ראה שע\"ת ח\"א יב, ד. מאמרי אדה\"א דברים ח\"ד ע' א'תעו ואילך. וש\"נ. תו\"ח בראשית ט, א ובהערה 5."],["2810","6","<b>שעקודי'. . בכלי א'</b>: ראה ע\"ח (שער העקודים) ש\"ו פ\"א. (שער מול\"ט) ש\"ז פ\"א. מבו\"ש ש\"ב ח\"ג פ\"ז. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' סד ואילך."],["2811","7","<b>ע\"ס דתהו. . זת\"ז </b>[ג: זה תחת זה]: ראה ע\"ח (שער התיקון) ש\"י פ\"ה. מאמרי אדה\"א קונטרסים ע' תז. וש\"נ."],["2812","8","<b>וימלוך וימת</b>: וישלח לו, לב ואילך."],["2813","9","<b>מי</b>: אג: שמי."],["2814","10","<b>ששכלו. . חסד. . דין. . ב\"ש וב\"ה</b>: ראה זהר (רע\"מ) פינחס רמה, א. תו\"ח בראשית י, א ובהערה 3."],["2815","11","<b>להתכלל</b>: אג: ולהתכלל."]]],[2800530248,"הרצון ושכל להטות כלפי חסד לזולתו מצד שעשה לו טובה ולא מצד בחי' עצם הטוב וחסד הבא בגלוי בהכרח מטבע הטוב שבעצמיות נפשו אדרבא יוכל להיות אכזרי בטבע ולמי שחננו והצילו ממות וכה\"ג ירצה להטיב ויטה שכלו עליו תמיד לחסד וזכות וכו' וכה\"ג שזה נק' חסד וטוב המורכב ולא חסד פשוט ועצמי שמצד הטבע כלל וכה\"ג יובן בהיפוכו במה\"ד המורכב להטות רצונו ושכלו כלפי חוב לשונאו שעשה לו רעה הרבה גם שבעצם טבעו הוא איש חסדן ורחמן כו' ועד\"ז יובן שיוכל להיות במורכב כמה מיני אופני' שונים מאד לפי אופן דבר שמורכב בו המדות כמו אהבה ושנאה התלויים בדבר כנ\"ל הרי יוכל למצוא דבר שמצדו א' יאהבנו ויהיה רצונו ושכלו הכל לטוב וחסד ומצדו הב' באותו הדבר עצמו ישנאנו ויטה רצונו ושכלו לרע ועונש עד שיוכל להיות בחי' ממוצע כלול מחו\"ג יחד כמ\"ש באשר משפטו שם<sup data-n=\"2816\">12</sup> כו' על שאול שהמית את הגבעוני' ועל שלא נספד כהלכה דבר והיפוכו כא' וכן כשנשא שלמה בת<sup data-n=\"2817\">14</sup> פרעה ע\"ז אמ' כי על אפי<sup data-n=\"2818\">13</sup> כו' ושה\"ש נאמר על שמחת בנין בהמ\"ק<sup data-n=\"2819\">15</sup> וכמ\"ש ביום שמחת לבו<sup data-n=\"2820\">16</sup> כו' שמחה וחרון אף דבר והיפוכו כא' וכן כי יצר לב האדם רע<sup data-n=\"2821\">17</sup> וכו' ומתחלה אמר וירא ה' כי רבה רעת האדם כו' וינחם<sup data-n=\"2822\">18</sup> כו' כמ\"ש במ\"א שזהו מבחי' המדות דתיקון שהם בבחי' מורכבי' דהיינו בהתפשטו' דבר שלא מצד העצמיו' לבד ע\"כ יוכל להיות התכללות דבר והיפוכו כו' והיינו בחי' נקודה דתהו דגם כשנעשה בהתחלקות לי' אין זה רק ספי' ולא פרצוף אדם שהוא בחי' ההתכללות מכל ההפכים כו' אלא בבחי' התיקון דוקא שכל נקודה בא בהתפשטות חוץ מעצמיותה שאז מתכללי' ע\"י ריבוי הכלי' מכלים שונים שמורכבי' בהם כו' וד\"ל וזמ\"ש בס\"י טרף אש ומים<sup data-n=\"2823\">19</sup> ובללן זב\"ז דהיינו בחי'<sup data-n=\"2824\">20</sup> המורכב דאש ומים<sup data-n=\"2825\">21</sup> דוקא ולא בעצם מהותן כו' וכמ\"ש במ\"א באריכות:\n(כא) <b>ובזה</b> יובן כללות ענין התכללות דג' קוין דנאצלי' חח\"ן מימין ובג\"ה משמאל ודת\"י<sup data-n=\"2826\">22</sup> באמצע כו' כמ\"ש בפרד\"ס דפנימית הכתר<sup data-n=\"2827\">23</sup> הנק' כתר שבכתר לא נחלק לג' קוין בחי' חיצוניו' שבו ממנו מתחלק לג' קוין והוא מבחי' חכמ' שבכתר כו' וכידוע בכונות דהגדול הגבור והנורא<sup data-n=\"2828\">24</sup> כו'. וביאור הדברים הנה בחי' התכללות הקוין ימין ושמאל הוא ע\"י קו האמצעי דוקא והענין הוא דקו הימין חח\"ן הרי החסד ענף החכמה<sup data-n=\"2829\">25</sup> ומובדל הימנה והוא מה שנסתעף החסד מצד השכל והטעם שמטה כלפי חסד בדבר מורכב כנ\"ל וכן הנצח ענף החסד<sup data-n=\"2830\">26</sup> מובדל הימנו דהיינו מצד החסד יחויב בחי' הניצוח להביא החסד למעשה בפו\"מ כו' וקו השמאל היפוכו כמו שכל המטה כלפי דין שנסתעף הימנו מדה\"ד כו' כך בינה גבורה כו' כמ\"ש אני בינה לי גבורה<sup data-n=\"2831\">27</sup> כו' דהחכמ' נוטה לחסדי' ובינה מינה דינין<sup data-n=\"2832\">28</sup> כו' (וכמ\"ש בע\"ח דאבא מקור החסדי'<sup data-n=\"2833\">29</sup> ואימא מקור כל הגבורו' כו' וכידוע) ובחי' ההתכללו' דב' קוין הללו שיבואו להתחבר במקום א' הוא ע\"י קו האמצעי דת\"י כו' כמו הדעת שהוא בחי' ממוצע להטות משכל של חסד לשכל של דין ונק' דעת נוטה<sup data-n=\"2834\">30</sup> (וכמו כי יצר לב כו' שנעשה שכל וטעם לזכות אשר תחלה היה זה השכל עצמו נוטה כלפי חוב<sup data-n=\"2835\">31</sup> כמ\"ש וירא כי רבה רעת כו' וכה\"ג וכמ\"ש במ\"א) ונמצא בדעת יחובר ב' שכליי' הפכיי' דחו\"ג להיות נוטה לחסד באופן זה ולדין באופן זה וכה\"ג גם במקום א' וכך מדת הת\"ת מכריע בין חו\"ג<sup data-n=\"2836\">32</sup> שהוא כמו הרחמי' שאינו אלא אחר מדה\"ד שעכ\"ז",[["2816","12","<b>באשר משפטו שם</b>: צפני' ב, ג [ושם: אשר ? אבל כ\"ה גם בחלק מהמובא בסמוך]. ראה יבמות עח, ב. ד\"ה לרוקע בסה\"מ תקס\"ב ח\"א ע' קצו. ח\"ב ע' תלז. ד\"מ ע' 322. תו\"ח נח עא, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ט. סה\"מ תרס\"ו ע' שסח. תרס\"ח ע' עו. המשך תער\"ב ח\"א ע' תקכח. ח\"ב ע' א'יג."],["2817","14","<b>בת</b>: אג: את בת."],["2818","13","<b>כשנשא שלמה. . כי על אפי</b>: ראה נדה ע, ב. ירמי' לב, לא. תו\"ח שם ובהערה 6."],["2819","15","<b>ושה\"ש. . בנין ביהמ\"ק</b>: ראה זהר תרומה קמג, א."],["2820","16","<b>ביום שמחת לבו</b>: שה\"ש ג, יא [ושם: וביום ? ראה מאמרי אדה\"א דברים ח\"ג ע' א'קכה. תו\"ח שם]. תענית כו, ב [במשנה]."],["2821","17","<b>כי יצר לב האדם רע</b>: נח ח, כא. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קיג. תו\"ח בראשית יד, א ובהערה 3."],["2822","18","<b>וירא ה' כי רבה. . וינחם</b>: בראשית ו, ה. ו."],["2823","19","<b>בס\"י טרף אש ומים</b>: כ\"ה בכ\"מ. ראה לעיל נד, א. סא, א. עג, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'כג. תו\"ח בראשית יג, א הערה 6."],["2824","20","<b>בחי'</b>: אג: בבחי'."],["2825","21","<b>בחי' המורכב דאש ומים</b>: ראה תו\"ח שם. קונט' בד קודש פ\"ד. נדפס גם באג\"ק אדמו\"ר האמצעי ח\"א ע' רצד."],["2826","22","<b>דג' קווין. . חח\"ן. . ובג\"ה. . ודת\"י</b>: ראה זהר (רע\"מ) בהעלותך קנג, ב. פרדס (שער סדר עמידתן) ש\"ו פ\"א. מאמרי אדה\"א בראשית ע' ריז. וש\"נ."],["2827","23","<b>בפרד\"ס </b>[ג: בפרדס]<b> דפנימיות הכתר</b>: ראה גם תו\"ח לך פ, ד ושם מציין לשער הצנורות ובהנסמן בהערה 48 שם."],["2828","24","<b>דהגדול הגבור והנורא</b>: ראה גם שע\"ת ח\"א מד, א ובהנסמן לשם."],["2829","25","<b>החסד ענף החכמה</b>: ראה זהר ואתחנן רסב, סע\"א. לך צד, א. תרומה קעה, ב. במדבר קיח, ב."],["2830","26","<b>הנצח ענף החסד</b>: ראה זהר (רע\"מ) פינחס רמג, סע\"א. הנסמן במאמרי אדה\"א קונטרסים ע' רכח."],["2831","27","<b>אני בינה לי גבורה</b>: משלי ח, יד."],["2832","28","<b>ובינה מינה דינין</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. לעיל עז, ב. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["2833","29","<b>דאבא מקור החסדי'</b>: מובא גם בשם הע\"ח במאמרי אדה\"ז תקס\"ז ע' שסא? תקס\"ח ח\"ב ע' תרסב. ראה גם ביאוה\"ז במדבר קמה, ב. מאמרי אדה\"א דברים ח\"א ס\"ע רלז. וש\"נ."],["2834","30","<b>דעת נוטה</b>: ראה גם לעיל פב, ב. תו\"ח וירא קי, ג ואילך."],["2835","31","<b>השכל. . כלפי חוב</b>: ראה בהנסמן לעיל בהערה כי יצר לב האדם."],["2836","32","<b>הת\"ת מכריע בין חו\"ג</b>: ראה פרדס (שער המכריעין) ש\"ט פ\"ג. הנסמן במאמרי אדה\"א נ\"ך ע' תקנב. תו\"ח שם קיא, ד בהערה 11."]]],[2800530249,"רחמנו' פוטרו והיא מדת יעקב<sup data-n=\"2837\">1</sup> כידוע וכן בחי' יסוד ממוצע לכלול ב' הפכים דנו\"ה<sup data-n=\"2838\">2</sup> שהוא ענין כליות יועצות<sup data-n=\"2839\">3</sup> הן ולאו קודם השפעת המשפיע כשצריך להשפיע עצם המדות חו\"ג כו' וכמו כל שיקול הדעת בא בהכרעה ואחר הכרעה ישקול במאזני צדק שהן נצח והוד<sup data-n=\"2840\">4</sup> איך להביא השפע למקבל כו' והיינו כללות ענין קו האמצעי דת\"י שמחבר לב' קוין דימין ושמאל ופרטי התכללותן נק' י\"ב גבולי אלכסון<sup data-n=\"2841\">5</sup> כידוע וקו האמצעי נק' בריח התיכון<sup data-n=\"2842\">6</sup> שמבריח מן הקצה כו' דהיינו שעולה עד בחי' פנימי' הכתר<sup data-n=\"2843\">7</sup> שלמעלה מהתחלקות הקוין ע\"כ יש בכחו לחבר ולכלול ב' הקוין כו'. וביאור ענין פנימית הכתר דנאצלי' שנק' כתר שבכתר (והוא בחי' כתר דע\"י וא\"א כו') היינו בחי' הרצון והתענוג הבא בגלוי שנק' אור הכתר שגם הוא כלול מי\"ס ובחי' חכמה שבכתר זהו הטעם לרצון ונק' טעם כמוס לרצון וכן יש בו חסד ונצח והכל בבחי' הרצון שהוא בלתי מוגבל גם שבא בגלוי מעצם העלם הרצון כנ\"ל וע\"כ המדות שברצון ותענוג נק' ימי קדם<sup data-n=\"2844\">8</sup> לגבי מדות שבחו\"ב שבאים בהגבלה כפי הגבלת השכל הגלוי בלבד כמשי\"ת עד בחי' מל' שבכתר ומבחי' חיצוניות דכתר נחלק לג' קוין מפני שבטעם הכמוס לרצון נק'<sup data-n=\"2845\">9</sup> התחלקות הרצון לחו\"ג וממוצע כו' אבל בכתר שבכתר שלמעלה מטעם כמוס לרצון עדיין רק רצון פשוט ועצמי בלא טעם כלל כי אין טעם לרצון כלל<sup data-n=\"2846\">10</sup> גם לא טעם כמוס כענין שתוק כך עלה במח'<sup data-n=\"2847\">11</sup> כו' וכמ\"ש במ\"א ע\"כ הוא למעלה מהתחלקות ימין ושמאל כו' הגם שבא בגלוי מבחי' האחרונה שבהעלם הרצון דבחי' א\"ק (כנ\"ל בסוף אות י\"ט) ועז\"א והבדילה הפרוכת בין הקדש<sup data-n=\"2848\">12</sup> כו' בחי' פרסא שבין כתר דכתר לחכמה כו' והוא בחי' קרומא דאוירא<sup data-n=\"2849\">13</sup> כמ\"ש במ\"א באריכות וע\"כ או' יהי רצון מלפניך<sup data-n=\"2850\">14</sup> מלפני הפרסא כו' לשנות מרצון של דין לרצון של חסד וכה\"ג כו' וד\"ל:\n(כב) <b>ומעתה</b> יש להבין בפרטי התכללות<sup data-n=\"2851\">15</sup> דע\"ס דאצי' ותחלה יש לבאר ענין פרטי התחלקות הספי' לי' וי' לי' כו' כמו חסד שבחכמה שנחלק גם הוא לי' וכה\"ג גבור' שבחכמה נחלק לי' כו'. כי הנה החכמ' כלולה מי' היינו כמו חו\"ג שבחכמה להטו' כלפי זכו' או כלפי חוב וחסד שבחכמה להטות כלפי זכות גם הוא כלול מי' דהיינו כמו חו\"ג שבו לזכות באופן כך וכך ולחוב יחייב גם הוא באופן כך וכך (הגם שהזכות יהפך לחוב בדין שבחכמה והחוב יהפך לזכות בחסד שבחכמה זהו כאשר הוא בעצם בלתי התחלקות אבל בהתחלקות יוכל להיות גם בחסד שבחכמ' בחי' דין ובדין שבחכמה בחי' חסד כידוע) וכן במדות דחו\"ג עצמן החסד נחלק לי' כח\"ב ומדו' כו' דגם שאין מרחמין בדין<sup data-n=\"2852\">16</sup> היינו בדין העצמי וכן אין דין בחסד העצמי אבל בהתפשטותן מן העצם יש חסד בדין ודין בחסד כנ\"ל:\n<b>והנה</b> יש התכללות שנק' ביטול דבר בהיפוכו המנגדו והיה כמוהו ממש וכמו מיתוק הגבורות בחסדים כמו שהמקטרג יהפך לסניגור וכן להיפך שהסניגור יהפך למקטרג וכמיתוק מים המרים במתוקים או להיפך וכן ביטול שכל לזכות בשכל לחוב וכה\"ג ה\"ז התכללו' אמיתי והיינו רק לפי שיש כח זה במנגד עצמו וא\"ל<sup data-n=\"2853\">17</sup> לא היה בטל בו כמו במתיקות יש מרירות בהעלם ובמרירות יש מתיקות בהעלם כמשל ודמיון מבישול המרקחת<sup data-n=\"2854\">18</sup> מדבש וצנון שנעשה טעם עריבות כולל מחריפות ומתיקות יחד כידוע וכן יש מטבע האש במים וממים באש ע\"כ יתכלל",[["2837","1","<b>רחמנו'. . מדת יעקב</b>: ראה זהר לך פז, ב. הנסמן במאמרי אדה\"א בראשית ע' קנו."],["2838","2","<b>יסוד ממוצע. . דנו\"ה</b>: ראה פרדס שם, פ\"ד. מאמרי אדה\"א קונטרסים ע' רכח ואילך."],["2839","3","<b>דנו\"ה. . כליות יועצות</b>: נסמן לקמן קלד, א."],["2840","4","<b>במאזני צדק שהן נצח והוד</b>: קדושים יט, לו. יחזקאל מה, י. ראה ת\"ז בהקדמה (יז, ב ובניצוצי זהר שם). כס\"מ לתכ\"א (פז, ב אות ל). לקמן קכז, סע\"ב. ש\"א שער החנוכה כו, א."],["2841","5","<b>י\"ב גבולי אלכסון</b>: ס\"י פ\"ה מ\"א. ס' הבהיר סמ\"ב. ונמנו בפרדס (שער פרטי השמות) שכ\"א פ\"ו-ח. הנסמן במ\"מ לשע\"ת צב, ג."],["2842","6","<b>וקו האמצעי נק' בריח התיכון</b>: ראה לקמן קלג, ב. מאמרי אדה\"א במדבר ח\"ג ע' א'קצה. נ\"ך ע' תקמט."],["2843","7","<b>וקו האמצעי. . הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (ע' סג). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמה בשם הע\"ח."],["2844","8","<b>המדות שברצון. . ימי קדם</b>: ראה גם סה\"מ תקס\"ב ח\"ב ע' תקט וע' תקיג. מאמרי אדה\"א דברים ח\"א ע' נה. וש\"נ. תו\"ח בראשית יג, ג ובהערה 16."],["2845","9","<b>נק'</b>: אזיג: ניכר."],["2846","10","<b>אין טעם לרצון כלל</b>: נסמן לעיל קכב, א."],["2847","11","<b>שתוק כך עלה במח'</b>: מנחות כט, ב. ראה גם סה\"מ תקס\"ט ע' קלד. אמ\"ב שער הק\"ש פצ\"ט. מאמרי אדה\"א ויקרא ח\"ב ע' תתטז. נ\"ך ע' תפג. וש\"נ."],["2848","12","<b>והבדילה הפרוכת בין הקדש</b>: תרומה כו, לג [בדילוג]. ראה גם שע\"ת ח\"א טז, ג ובהנסמן לשם."],["2849","13","<b>פרסא. . קרומא דאוירא</b>: ראה זהר (אד\"ר) נשא קכח, ב. מאמרי אדה\"א בראשית ע' לט. וש\"נ. לעיל קא, א."],["2850","14","<b>או' יהי רצון מלפניך</b>: בברכות השחר. ועוד."],["2851","15","<b>בפרטי התכללות</b>: להבא להלן ראה סה\"מ תרמ\"ד ע' רסא ואילך."],["2852","16","<b>שאין מרחמין בדין</b>: ראה כתובות פד, א (במשנה)."],["2853","17","<b>וא\"ל</b>: אג: ואם לאו."],["2854","18","<b>כמשל. . המרחקת</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ע. תו\"ח בראשית יג, א ובהערה 3. סה\"מ תרמ\"ד ע' רסב בשולי הגליון."]]],[2800530250,"אש במים או מים באש כמ\"ש הוציא מים מאש<sup data-n=\"2855\">19</sup> ואש ממים כו' וכך במדות חו\"ג מפני שיש דין בחסד וחסד בדין כנ\"ל ע\"כ יבוטל הדין בחסד או להיפוך החסד בדין וא\"ל לא היה מתכלל דבר בהיפוכו לעולם אמנם הנה יש התכללות מדין בחסד מפני שהוא כמוהו בעצם ולא שהוא בטל ממהותו אדרבה נותן בו תוקף ועוז ועכ\"ז נק' גבור' שבחסד וכן להיפוך חסד שבגבורה שנותן כח בגבורה ודין כו' והענין הוא כידוע ע\"ד אם רעב שונאך האכילהו לחם כי גחלים<sup data-n=\"2856\">20</sup> כו' הרי בחסד וטוב זה עושה לו רעה ודין גמור לאבד נפשו וכן משלם לשונאיו כדי להאבידו<sup data-n=\"2857\">21</sup> וכה\"ג כל בחי' דין ועונש שנעשה בבחי' חסד הרי הוא עוז ותוקף הדין ביותר ונק' חסד שבגבור' וכמו והשמיע ה' את הוד קולו<sup data-n=\"2858\">22</sup> במחנה סנחרב וכן להיפוך בבחי' גבורה שבחסד שהמעשה של חסד עשוי במדת הדין להיות בו יותר תוקף ועוז כמו גבורות גשמים<sup data-n=\"2859\">23</sup> שבאים בצמצום כדי שיומשך בריבוי וכמו צמצום אור השפע בכל מקום כדי שיתקבל וכן התחלקות ע\"ב גשרים<sup data-n=\"2860\">24</sup> כו' וכן יסורים של אהבה<sup data-n=\"2861\">25</sup> וכאב את בן ירצה<sup data-n=\"2862\">26</sup> מייסרו שהחסד נעשה בלבוש דמה\"ד דוקא וה\"ז דוקא תוקף החסד יותר מעצם החסד וכמו הקדים רפואה למכה<sup data-n=\"2863\">27</sup> וכמ\"ש כי הוא יך וירפאנו<sup data-n=\"2864\">28</sup> ולכאורה למה צריך להכאה כלל אך ע\"י הרפואה יברא ויתחזק יותר כי החולה הוא בחי' הדין הקשה ויעובר ע\"י מדה\"ד שבחסד שהוא הרפואה מדברים קשים כו' וכה\"ג בכל מיתוק הדין בשרשו דוקא היינו בדין שבחסד דוקא להיותו תוקפו של חסד לגבור על הדין ולהמתיקו כו' וד\"ל. ובכ\"ז יובן איכות אופני פרטי ההתכללות דחו\"ג כמו גם גבורה שבחסד עם חסד שבגבורה דגם שהן ב' הפכים ביותר שזה תוקף החסד וזה תוקף הגבורה ומכ\"ש מצד התפשטות לבושי' מחולפים שזה פועל דין וזה פועל חסד אבל מ\"מ מצד שכ\"א פועל בשביל דבר היפוכו דוקא שגבורה שבחסד פעולתו דין ופנימיותו חסד וחסד שבגבורה פעולתו חסד ופנימיותו דין ע\"כ יוכלו לבוא כא' דוקא מפני שכ\"א מראה ב' הפכים עכ\"פ וכמו גבריאל שהציל לאברהם<sup data-n=\"2865\">29</sup> וכן צינן את הגחלים<sup data-n=\"2866\">30</sup> ה\"ז מבחי' גבורה שבחסד כמו זיעה טובה מוציא את חולי החום וכרפואה למכה כו' והוא המכה במחנה סנחרב בבחי' חסד שבגבור' כמ\"ש ויצא מלאך ה'<sup data-n=\"2867\">31</sup> כו' וכידוע וד\"ל והיינו לאכללא שמאלא בימינא<sup data-n=\"2868\">32</sup> וימינא בשמאלא שהוא כמו אור החסד בכלי הגבורה שפועל הכלי היפך האור שלו שכלי הגבורה פועל דין היפוך אור של חסד שבו וכן להיפוך כלי החסד פועל חסד היפוך אור הגבורה שבו ואין זה היפך כלל מאחר שהוא בבחי' אור וכלי שהוא כענין חומר וצורה (כמשי\"ת) וכמ\"ש במ\"א בענין<sup data-n=\"2869\">33</sup> התכללות דשם מ\"ב<sup data-n=\"2870\">34</sup> ושם ע\"ב<sup data-n=\"2871\">35</sup> שהן ב' פרשיות דק\"ש כו' וכמו עקידת יצחק באברהם<sup data-n=\"2872\">36</sup> איש החסד וכתנופת הלוים שנכללו בחסדי' דכהנים כמ\"ש וילוו עליך<sup data-n=\"2873\">37</sup> ואיך ישרת את היפוכו וכה\"ג רבים וכ\"ז אינו רק מצד בחי' ההתחלקות שבכ\"א ע\"כ מצא מין את מינו וניעור<sup data-n=\"2874\">38</sup> גם בהיותם ב' הפכי' ממש כו' וכמו ענין התחלקות מיכאל וגבריאל שר של אש ומים<sup data-n=\"2875\">39</sup> ואין מכבין זא\"ז כמ\"ש עושה השלום<sup data-n=\"2876\">40</sup> כו' לפי שיש בכ\"א מהיפוכו המנגדו דוקא אבל באורו' הפשוטי' בתכלית כמו בחי' הנקודות הנק' כתרים א\"א להם להתכלל כלל מפני שכ\"א נבדל לגמרי מזולתו ולא ימצא בו כלל מבחי' המנגדו כמו עצם בחי' הטוב שבעצמיות נפש איש הטוב הנק' עומק טוב עם עצם הרע שנק' עומק רע כו' אך בבע\"ת אנו רואים שנהפך גם עצם הרע לטוב וכן זדונות עצמן נעשו כזכיות<sup data-n=\"2877\">41</sup> הרי הוא מצד מס\"נ בעצמות אא\"ס שלמעלה<sup data-n=\"2878\">42</sup> גם",[["2855","19","<b>הוציא מים מאש</b>: מובא בכ\"מ בשם ס\"י ? ראה הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תלא. תו\"ח בראשית שם הערה 2."],["2856","20","<b>אם רעב שונאך. . כי גחלים</b>: משלי כה, כא. כב. ראה גם ביאוה\"ז חוקת צו, ב."],["2857","21","<b>משלם לשונאיו כדי להאבידו</b>: ע\"פ ואתחנן ז, י. ראה מאמרי אדה\"א דברים ח\"ב ע' תסח."],["2858","22","<b>והשמיע ה' הוד קולו</b>: ישעי' ל, ל. ראה סידור שער הלולב רסד, ג."],["2859","23","<b>גבורות גשמים</b>: משנה ריש תענית. ראה גם שע\"ת ח\"א מח, א ובהנסמן במ\"מ לשם."],["2860","24","<b>ע\"ב גשרים</b>: ראה פרדס (שער פרטי השמות) שכ\"א פ\"ה. שע\"ת ח\"א לח, ג ובהנסמן במ\"מ לשם."],["2861","25","<b>יסורים של אהבה</b>: ברכות ה, א. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תריד. תו\"ח נח עב, סע\"א ואילך."],["2862","26","<b>וכאב את בן ירצה</b>: משלי ג, יב."],["2863","27","<b>הקדים רפואה למכה</b>: ראה מגילה יג, ב. מדרש לק\"ט שמות ג, א."],["2864","28","<b>כי הוא יך וירפאנו</b>: הושע ו, א [ושם: כי הוא טרף וירפאנו יך ויחבשנו ? ראה מאמרי אדה\"א שמות ח\"ב ע' תקסט. וש\"נ]."],["2865","29","<b>גבריאל שהציל לאברהם</b>: ראה גם מעשה א\"א [אוצר מדרשים אייזענשטיין ע' 4]. ובמאמרי אדה\"ז על ענינים ע' שמב: ?בדברי רז\"ל. . בהצלת אברהם בכבשן האש\". וראה פסחים קיח, א."],["2866","30","<b>גבריאל. . צינן את הגחלים</b>: ראה יומא עז, א. מאמרי אדה\"ז ענינים ריש ע' שמג. מאמרי אדה\"א במדבר ח\"ב ע' תתיב."],["2867","31","<b>המכה במחנה סנחרב. . ויצא מלאך ה'</b>: ראה סנהדרין צה, ב. מלכים-ב יט, לה. ישעי' לז, לו."],["2868","32","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח. תו\"ח בראשית כו, א הערה 3."],["2869","33","<b>בענין התכללות דשם מ\"ב</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן לשם."],["2870","34","<b>דשם מ\"ב</b>: ראה זהר תרומה קלב, ב. פרדס (שער פרטי השמות) שכ\"א פי\"ב. פי\"ג. מאמרי אדה\"א שמות ח\"א ע' קמא. וש\"נ."],["2871","35","<b>ושם ע\"ב</b>: ראה זהר שם. פרדס שם פ\"ה."],["2872","36","<b>עקידת יצחק באברהם</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קל. מאמרי אדה\"א דברים ח\"ד ע' א'תלג. וש\"נ."],["2873","37","<b>וכתנופת הלוים. . וילוו עליך</b>: קרח יח, ב. ראה מאמרי אדה\"ז אתהלך לאזניא ע' קנג ואילך. תו\"ח וירא קטז, ד ובהערה 24."],["2874","38","<b>מצא מין את מינו וניעור</b>: עירובין ט, סע\"א."],["2875","39","<b>מיכאל וגבריאל שר של אש ומים</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' לד. וש\"נ."],["2876","40","<b>מיכאל וגבריאל. . עושה השלום</b>: איוב כה, ב [ושם: שלום ? ראה הנסמן במ\"מ לשע\"ת נב, ג]. ראה במד\"ר פי\"ב, ח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמה ובהנסמן לשם. מאמרי אדה\"א קונטרסים ע' שס. וש\"נ."],["2877","41","<b>זדונות עצמן נעשו כזכיות</b>: ראה יומא פו, ב. מאמרי אדה\"א בראשית ע' סג וש\"נ."],["2878","42","<b>שלמעלה</b>: תוקן ע\"פ: אגד. ובמהדורת טשערנאוויץ: שנתעל'."]]],[2800530251,"מהתחלקות עצם החו\"ג ולכך יכולים במס\"נ דוקא להתפלל ולומר יהי רצון בעצם מלפניך כו' וכן ויעבור ה' על פניו<sup data-n=\"2879\">1</sup> כו' אל רחום להפוך גם הדין בעצם לחסד כו' וכמשי\"ת בענין י\"ג ת\"ד כו' וד\"ל (והיינו על ידי בחי' הקו\"ח שיש בו מכח עצמות אא\"ס ממש כמ\"ש ז\"ל אליו ולא למדותיו<sup data-n=\"2880\">2</sup> גם לא למדותיו העצמיי' כו' וכמשי\"ת בעזר\"ה וד\"ל):\n(כג) <b>והנה</b> בפרטיות בחי' הכתר איך שהוא בחי' ממוצע ויש בו מבחי' האחרונה שבמאציל והוא בפנימיות שבו והוא שרש וראש לנאצלי' בחיצוניות שבו וכמ\"ש בע\"ח<sup data-n=\"2881\">3</sup> וגם היות ידוע שבחי' ג\"ר דע\"י מובדל ומרומם בלתי מלובש בנאצלים וזהו המתנשא מימות עולם<sup data-n=\"2882\">4</sup> ולכך נק' עתיק יומין מלשון המעתיק הרים<sup data-n=\"2883\">5</sup> כו' שנעתק מימות עולם כו' הנה כ\"ז ידוע. ויש להבין בזה דרך פרט בהיות שע\"י וא\"א נחשב לא' רק שבכללות נחשב בחי' ע\"י מסוף עולם הא\"ס ובחי' א\"א הוא שרש וראש לנאצלי' כמ\"ש בע\"ח<sup data-n=\"2884\">6</sup>. וביאור הדברים ידוע שזהו בחי' התענוג והרצון<sup data-n=\"2885\">7</sup> ולהיות שאנו רואים שבכל רצון יש תענוג ולולי התענוג לא היה רצון לדבר כלל כמו הרצון לעושר וכבוד לולי שיש בו תענוג לא היה רוצה בזה כלל א\"כ התענוג הוא בחי' פנימיות הרצון לכאורה ואנו רואים להיפוך ג\"כ שאם אין רצון אין תענוג שהרי דבר שלא ירצה בו לא יתענג ממנו כלל א\"כ הרצון פנימי' התענוג ואנו רואים שזה בלא זה אינו מתקיים כי אין לרצון קיום בלא תענוג ואין לתענוג קיום בלא רצון ולפ\"ז מוכרח לומר ששניהם מהות א' מאחר שמאמצעות חיבורם יחד דוקא יתקיים כו' וכ\"ז בין בתענוג ורצון פשוט ועצמי בין בתענוג ורצון מורכב שהנפש מתפשט ונמשך אחריו גם שאינו מעצמותה אלא הוא דבר נבדל כו'. ואמנם בכלל אנו רואים שהנפש טבעה להתמשך אחר דבר שיש בו תענוג עד שיכול להיות כל עצמותה נמשך ונכלל בו כעונג המורכב בפרט נבדל כמו בכבוד או ממון או חכמה ומדות בחסד<sup data-n=\"2886\">8</sup> ודין וניצוח והתפארו' וכה\"ג או בדברי' שהנפש מחמדתן כתאוות כל תענוגי העוה\"ז וכה\"ג אעפ\"י שכל אלה אינן בבחי' עצמיות התענוג ההיולי רק שהנפש תומשך ותחמוד להם אבל מזה נראה שעצם הנפש הוא בבחי' תענוג ההיולי ע\"כ תומשך אחר עונג מורכב ותברח מן הצער שהוא היפך העונג עד שב' קוין שקולין<sup data-n=\"2887\">9</sup> הן ממש שכפי ערך התפשטות הנפש במלאת אורה בדברי תענוג כן תתכווץ ותתמעט אורה בצער ויגון בתכלית כו' ומזה נראה בעצם מהותה שהוא התענוג והעיקר ממה שתברח ותתכווץ מן הצער מזה ראי' יותר כו' וע\"כ גזרו אומר המקובלי' הראשוני' שהתענוג נחשב מעצם הנפש ואמרו שאין לך למעלה מן העונג<sup data-n=\"2888\">10</sup> ואין האמת כן רק שהעצמיות דנפש תתמלא מן התענוג הרב ותומשך כל עצמותה עד שתכלה ותומשך כמעט כולה כמו כלתה נפשי<sup data-n=\"2889\">11</sup> כו' ולהיפך תכלה בגרעון אור לגמרי מכל וכל מעוצם הצער המופלג כידוע וראי' ברורה יותר ממה שאנו רואי' שגם בפרטי כחות של הנפש הנה בחי' העונג שבזה הכח בפרטו' הוא עיקר קיום מציאותו תמיד כמו הכח של מדת החסד גם שהוא עצמי וטבעי בטבע הטוב להטיב עיקר קיומו הוא העונג שמתענג בשפע הטוב וזהו קיום האמיתי לטבעיות טובו שהוא מה שטבעו להתענג ביותר מן ההטבה עד שכל עיקר חיותו בנפשו בא ע\"י עונג זה שבטוב וחסד ולהיפוך במי שהוא אכזרי בטבעו אין זה רק שזהו כל חיותו בתענוג זה שעושה רע ואכזריו' כידוע",[["2879","1","<b>ויעבור ה' על פניו</b>: תשא לד, ו."],["2880","2","<b>אליו ולא למדותיו</b>: נסמן לעיל קיב, א."],["2881","3","<b>הכתר. . ממוצע. . בע\"ח</b>: ראה שם (שער דרושי אבי\"ע) שמ\"ב פ\"א. הנסמן לעיל קטז, ב."],["2882","4","<b>המתנשא מימות עולם</b>: ע\"פ ברכת יוצר. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שמא."],["2883","5","<b>המעתיק הרים</b>: איוב ט, ה. ראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ס\"ע תקלב. תקס\"ה ח\"ב ע' תתקמא. מאמרי אדה\"א ויקרא ח\"א ע' רמא. וש\"נ. שם ע' שמא. דברים ח\"א ע' רט וע' רצג. ד\"מ לט, א."],["2884","6","<b>שע\"י וא\"א. . בע\"ח</b>: שנסמן לעיל בהערה הכתר."],["2885","7","<b>התענוג והרצון</b>: ראה סה\"מ תקס\"ח ח\"א ע' מז. מאמרי אדה\"א נ\"ך ע' תפב. וש\"נ."],["2886","8","<b>בחסד</b>: תוקן ע\"פ גד. א: כחסד."],["2887","9","<b>הצער. . העונג. . קוין שקולין</b>: נסמן לעיל קיג, א."],["2888","10","<b>שאין לך למעלה מן העונג</b>: ס\"י פ\"ב מ\"ב [מנטובא שכ\"ב] בהוספת תיבת ?לך\" ? ראה הנסמן במאמרי אדה\"א נ\"ך ע' תפ. קונטרסים ע' תקסט."],["2889","11","<b>כלתה נפשי</b>: תהלים פד, ג."]]],[2800530252,"וכן במדת הניצוח כל עיקר קיומו רק העונג המופלג עד שחיות נפשו נמשך כולה בזה שינצח לזולתו ואם לא ינצח יחלה כו' וכך הוא בכל פרטי פרטי המדות עד החכמ' והרצון הרי עיקר קיומם ומקורם העונג ולולי העונג שבהשכלה אין לו כח לחדש שום חכמ' כנראה בחוש וכמו שאמ' אלמלא חדווה דשמעתא<sup data-n=\"2890\">12</sup> כו' וכידוע בענין חכמת אדם תאיר פניו<sup data-n=\"2891\">13</sup> שהלחלוחית שבו עונג ההיולי הוא המקור להשכיל כל שכל כו' ואמנם ברצון בלבד אנו רואי' שבלא רצון אין תענוג נמצא גם בכל פרטי המדות כמו אם לא ירצה בחסד או בדין אין לו בו תענוג כלל וכן אם לא ירצה להשכיל לא ימצא העונג לזה כלל וכן אם לא ירצה בניצוח כלל אין לו תענוג בניצוח או התפארות וכן גם בשאר תענוגי עוה\"ז כממון וכבוד וכה\"ג בלא רצון אין תענוג בהן כלל וכלל והיינו מפני שכללות ענין זה הוא בהיות שכל עיקר עצם הנפש נמשך אחר התענוג והרצון (שהרצון הוא ג\"כ המשכת כל הנפש<sup data-n=\"2892\">14</sup> עד שכולה תכלה ברצון לדבר מה כו' כידוע) ע\"כ גם בכל פרטי כחותי' עיקר קיומם הוא התענוג והרצון והעדרם הוא הצער מדבר זה היפך העונג ודבר המנגד לרצון גם שאינו צער יצטער ממיל' כמו אם ירצה לאהוב שונאו יתענג ממנו ולהיפך אם לא ירצה באהובו יצטער ממנו וכן אם יתענג בשנאוי לו המזיקו ירצה בו ואם יצטער באהוב לו לא ירצה כי מהות א' הן הרצון והתענוג ולא נודע מי קדם ולפעמים זה פנימי וזה חיצוני ולפעמי' להיפך ולא ימצא א' בלא זולתו שאם אין תענוג אין רצון ואם אין רצון אין תענוג בין בפשוט בין במורכב כנ\"ל וד\"ל:\n(כד) <b>והנמשל</b> מכל הנ\"ל למשכיל למעלה יובן איך שבחי' עצמות התענוג הפשוט שבעצמות אא\"ס קודם הצמצום הוא הנק' שעשועי המלך בעצמותו<sup data-n=\"2893\">15</sup> שהוא בבחי' א\"ס ממש וגם בי\"ס העצמיים שהוא כתר ועד מל' דא\"ס הכל מבחי' העונג הפשוט שבעצמותו עד\"מ שגם החסד העצמי שבנפש עיקר קיומו העונג כו' ועכ\"ז באמת הרי עצמות אא\"ס מובדל גם מבחי' תענוג פשוט רק שנמשך ומאיר בבחי' העונג כמו שעצמות הנפש תומשך אחר העונג כו' ולזה אמר אין לך למעלה מן העונג כו' וכמו בבחי' חפץ חסד שבעצמות שיש בו תענוג הפשוט הוא נמשך ומאיר בתוס' אור עד שיורד ובא גם בדבר נבדל שהוא בבחי' תענוג והרצון הקדום הנ\"ל שאחר הצמצום להיות מקור להשתלשלות דאבי\"ע עד שיורד ונמשך בסיום הכל והוא גם בפרט דע\"ס היותר אחרון שבאצי' עד\"מ הנ\"ל בעונג הנמצא לקיום מדת הניצוח וכה\"ג וז\"ש בע\"ח דע\"י וא\"א שהוא התענוג והרצון שמהות א' הם ואין זה בלא זה (ונק' ג' רישין דמתגלפין<sup data-n=\"2894\">17</sup> דא לגו מן דא כו' ולפעמים זה פנימי כו' כנ\"ל) מלובש תוך כל ספי'<sup data-n=\"2895\">16</sup> וספי' בפרטי פרטו' שבלעדו אין לו קיום כלל כנ\"ל באריכות וגם הוא מקיף את כולם (וכמ\"ש במ\"א במשל י' חפירות<sup data-n=\"2896\">18</sup> זה אחר זה שהראשונה נמשכת בתוך כל חפירה וחפירה כו' וכך אמר בזהר עבד מנא רברבא<sup data-n=\"2897\">19</sup> וקארי בה גרמי' חכים כו' וכן מ\"ש אפיק' י' תיקונין<sup data-n=\"2898\">20</sup> וקרינן לון י\"ס כו') להיות כי בחי' ע\"י נחשב מסוף עולם הא\"ס<sup data-n=\"2899\">21</sup> עדיין לפי שעולם הא\"ס נחשב עד בחי' מל' דא\"ק שהוא בחי' אותיות וסוף מעשה שעלה במח' ורצון הקדום הנ\"ל והוא בחי' אחרונה שבעצמו' שנעשה כתר דע\"י שזהו בחי' גלוי אור העונג מהעלם העונג ורצון קדום הנ\"ל ע\"כ גם כתר דע\"י וחו\"ב ומדות שבו הכל נחשב מסוף עולם הא\"ס אבל בחי' א\"א",[["2890","12","<b>אלמלא חדווה דשמעתא</b>: ראה זהר (מדהנ\"ע) תולדות קלח, א."],["2891","13","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["2892","14","<b>שהרצון. . הנפש</b>: ראה גם מאמרי אדה\"א בראשית ע' שלט. שע\"ת ח\"א נג, ב ובהנסמן במ\"מ לשם."],["2893","15","<b>שעשועי המלך בעצמותו</b>: נסמן לעיל קכב, א."],["2894","17","<b>ג' רישין דמתגלפין</b>: ראה זהר (אד\"ז) האזינו רפח, סע\"א. ע\"ח (שער א\"א) שי\"ג פ\"ב."],["2895","16","<b>בע\"ח דע\"י. . מלובש תוך כל ספי'</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ע' שפא וע' תרנז. וש\"נ."],["2896","18","<b>במשל י' חפירות</b>: ראה מאמרי אדה\"ז הקצרים ע' תצב."],["2897","19","<b>עבד מנא רברבא</b>: ראה זהר (רע\"מ) בא מב, ב."],["2898","20","<b>אפיק' י' תיקונין</b>: ת\"ז בהקדמה (יז, א)."],["2899","21","<b>ע\"י. . עולם הא\"ס</b>: ראה גם שע\"ת קד, א ובהנסמן במ\"מ לשם."]]],[2800530253,"שהוא בחי' גלוי הרצון שבא מחמת העונג להיותו נמשך ובא להתפשט למט' כו' הוא הנק' ראש ושרש הנאצלי' שהן ע\"ס דאצי' בכלל ובפרט ולזה נק' בחי' הכתר בכלל בחי' ממוצע שיש בו מבחי' אחרונה שבעצמו' והוא ראש לנאצלים כי אורו' הנאצלים שהן בחי' גילוי ההעלם הרי הן בבחי' נבדל מן העצמות כנ\"ל (באות י\"ב)<sup data-n=\"2900\">1</sup> וכמו עד\"מ המדו' חו\"ג בדבר נבדל שבאין מכח המדות חו\"ג שבעצם כו' ועכ\"ז בחי' התענוג והרצון שבא מן העצמו' הוא מלובש תוך כל להיות קיומם תמיד כנ\"ל מפני ששרש זה התענוג והרצון בעצמות אא\"ס שנק' שעשועי המלך בעצמו כו' וכמשל הנפש שנמשך אחר כל עונג כו' שמזה ראי' שהעונג ממלא אורה כו' א\"כ גם מזה עצמו הוא הטעם שהעונג פרטי שבכל פרט מן האורו' הוא עיקר קיומו כו' עד גם בבחי' מל' שהוא ההתנשאות לולי התענוג שבו אין לו קיום כו' והעדר אור העונג הוא בחי' העדר אור מציאותם כו' וד\"ל. וכ\"ז דרך כלל אבל דרך פרט הנה רק בחי' ג\"ר דע\"י נחשב מבחי' העצמו' אבל ז\"ת שבו מלובש בגלגלתא דא\"א חסד דע\"י בגלגלתא<sup data-n=\"2901\">2</sup> וגבור' במו\"ס כו' וזהו המתנשא מימו\"ע כו' כידוע להיות כי התהוות עיקר הרצון מן התענוג הוא רק מבחי' המדות שבתענוג כמו מן החסד שבתענוג עד\"מ כאשר אדם בעונג בשמחת חתונת בנו וכה\"ג אז יטיב רב חסדו לכל מצד התענוג שמרומם את נפשו (מטעם הנ\"ל) ואז יפעלו ממנו כל רצון דהיינו להפוך גם מרצון של דין לחסד שזה תלוי בבחי' נקודת הרצון שלמעלה מטעם כמוס לרצון שמחלק לחו\"ג חסד ודין כו' וזהו דוגמא להבין איך שבחי' חסד דע\"י מלובש בגלגלת' כו' ובחי' גבורה שהוא בחי' הדין בהיפך לעונג הוא מלובש בח\"ס דא\"א שהוא טעם כמוס לרצון שזהו לדקדק ברצון שיהיה באופן זה דוקא ולא באופן אחר כו' וכמ\"ש בס' הקבלה שהראשוני' גזרו אומר על החכמ' שהיא בבחי' דין<sup data-n=\"2902\">3</sup> שכאשר הרצון בא עפ\"י חיוב החכמ' בא בדקדוק וצמצו' כך ולא כך וע\"כ ע\"פ משפט התורה דאוריית' מח\"ע<sup data-n=\"2903\">4</sup> כו' יש דינים רבים משא\"כ הארת י\"ג מדה\"ר מלמעלה מחכמ' שברצון כו' שנושא עון וכו' ומכ\"ש מבחי' ג\"ר דע\"י שבלתי מלובש בנאצלי' והוא בחי' העונג כמו שהוא בעצמו שעדיין לא נולד ממנו רצון כלל רק עתיד להיות ממנו כל רצון כו' והוא נחשב מעצמות התענוג הפשוט הכללי שהוא מבחי' מקור כל התענוגים שבעצמו' אא\"ס כמ\"ש כי עמך מקור חיים<sup data-n=\"2904\">5</sup> מקור כל התענוגים שברצון קדום כו' ונק' עתיקא דעתיקין<sup data-n=\"2905\">6</sup> בכללות הכל כו' ונק' ע\"י כמ\"ש בדניאל וע\"י יתיב<sup data-n=\"2906\">7</sup> כו' מלשון זקנה<sup data-n=\"2907\">8</sup> שהוא בחי' נצחי' דעצמיות אא\"ס כשבא ומאיר למטה בהשתלשלות דקו\"ח כו' אבל בעצמותו ממש מי איכא זקנה<sup data-n=\"2908\">9</sup> קמי קוב\"ה כו' וכמ\"ש במ\"א בענין ועד<sup data-n=\"2909\">10</sup> בחלופי אתוון דאחד<sup data-n=\"2910\">11</sup> פשוט עצמו שעצמות אא\"ס שלמעלה מן הזמן דימי קדם כו' כשמאיר בזמן אז הזמן ג\"כ נצחי כו' ואז נק' ע\"י כו' וד\"ל:\n(כה) <b>והנה</b> מעתה יש להבין בפרטי ענין ע\"ס דאצי' דהיינו בירידת האור מחיצוניות נה\"י דא\"א באו\"א ולפעמים א' דאו\"א מלבישי' לזרועות דא\"א<sup data-n=\"2911\">12</sup> (ומ\"ש רישא דמלכא בחו\"ג אתתקן<sup data-n=\"2912\">13</sup> היינו בחי' רישא דא\"א דאתתקן בחו\"ג דע\"י חסד דע\"י בגולגלת' כו' כנ\"ל) ולפעמים א' דאבא יונק ממזל הח' ונוצר ואימא ממזל הי\"ג ונקה<sup data-n=\"2913\">14</sup> כו':\n<b>אך</b> הנה ידוע בענין כח מה דהחכמה<sup data-n=\"2914\">15</sup> מאין תמצא<sup data-n=\"2915\">16</sup> בבחי' אין והבינה נק' יש<sup data-n=\"2916\">17</sup> והאור ושפע דאין דחכ' מאיר ונמשך בבחי' השגה דבינה שזהו מאין ליש ונק' תרין רעין דלא מתפרשין<sup data-n=\"2917\">18</sup> כו' כחדא שריין<sup data-n=\"2918\">19</sup> כו' והוא בחי'",[["2900","1","<b>(באות יב)</b>: טו: ליתא. ובאחדים מהכת\"י: (באות) ולא נרשם איזה. ואוצ\"ל: (באות י\"ט)."],["2901","2","<b>חסד דע\"י בגלגלתא</b>: ראה ע\"ח (שער א\"א) שי\"ג פ\"ו. פ\"ז."],["2902","3","<b>בס' הקבלה. . החכמ'. . דין</b>: ראה ע\"ח שם פ\"ו. מאמרי אדה\"א נ\"ך ע' שיג. וש\"נ. תו\"ח בראשית לא, ד ובהערה 40. לקמן קפה, ד ואילך."],["2903","4","<b>דאוריית' מח\"ע</b>: נסמן לעיל כג, א."],["2904","5","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה גם לעיל סב, א. מאמרי אדה\"א נ\"ך ע' תסח. וש\"נ. תו\"ח מקץ רכג, א ובהערה 8."],["2905","6","<b>עתיקא דעתיקין</b>: ראה זהר (אד\"ר) נשא קכח, א. ועוד."],["2906","7","<b>בדניאל וע\"י יתיב</b>: דניאל ז, ט."],["2907","8","<b>וע\"י. . מלשון זקנה</b>: ראה גם מאמרי אדה\"א בראשית ע' רסא. ויקרא ח\"א ע' שמא."],["2908","9","<b>מי איכא זקנה</b>: ראה יבמות טז, ב. ראה גם שע\"ת ח\"א כט, ריש ע\"ב. תו\"ח תולדות קנג, א הערה 9."],["2909","10","<b>בענין ועד</b>: ראה גם מאמרי אדה\"א נ\"ך ע' רכו."],["2910","11","<b>ועד בחלופי אתוון דאחד</b>: ראה זהר תרומה קלד, א. ד\"ה זה במאמרי אדה\"א דברים ח\"א ע' רכד."],["2911","12","<b>דאו\"א מלבישי' לזרועות דא\"א</b>: באמ\"ב ש' התפילין קטז, ג בשם הפרדס וע\"ח ? ראה ע\"ח (שער או\"א) שי\"ד פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד."],["2912","13","<b>רישא דמלכא בחו\"ג אתתקן</b>: במאמרי אדה\"א דברים ח\"ב ע' תרכד: באד\"ר? בראשית ע' רמט: באדרא ? ראה זהר [אדרא דמשכנא] משפטים קכב, ריש ע\"ב."],["2913","14","<b>דאבא יונק. . ואימא. . ונקה</b>: ראה זהר (אד\"ז) האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקעד? מאמרי אדה\"א קונטרסים ע' תקנז."],["2914","15","<b>כח מה דהחכמה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["2915","16","<b>דהחכמה מאין תמצא</b>: איוב כח, יב."],["2916","17","<b>דהחכמה. . אין והבינה נק' יש</b>: ראה מאמרי אדה\"א בראשית ע' ב. וש\"נ. דרושי חתונה ח\"ב ע' תעג."],["2917","18","<b>תרין רעין דלא מתפרשין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["2918","19","<b>כחדא שריין</b>: ראה זהר (אד\"ז) האזינו רצ, ב."]]],[2800530254,"נקודה דחכמה שמבריק כברק מלמעלה מן השכל (בל' העולם הבנה כו') והיינו מכח המשכיל שנק' ח\"ס דא\"א ונק' חכמה נעלמה שהוא מקור מוצא כל שכל מאין כו' ונק' משכיל כידוע והיינו שאמר דאור אבא יונק ממזל הח' ונוצר אותיות צינור<sup data-n=\"2919\">20</sup> כצינור דק כך בחי' שערות דמזל הח' הוא בחי' צומח שבמשכיל הנ\"ל להצמיח מאין כל מיני השכלות והיניקה הוא בחי' הגדלת מוחין דאבא והגדלת מוחין דאימא היינו ממזל הי\"ג ונקה וב' מזלות הללו מזל העליון ומזל התחתון הן שרשי המוחין דאו\"א והוא בכח המשכיל עצמו יש שרש הגדלת מוח ההבנה ושרש הגדלת מוח התפיסא וההשגה שהן נק' מוח אבא ומוח אימא כידוע וכמו שבחי' מוח בינה שהוא מוח התפיסא וההשגה מקבל מבחי' האין דמוח החכמה כך בשרשם ביחוד ב' מזלות דא\"א ונוצר ונקה כו' וידוע דגם שהמזלות נק' שערות<sup data-n=\"2920\">21</sup> שנבקעים ויוצאים רק מבחי' מותרי מו\"ס דא\"א אבל שרשן מעצמו' הגלגלתא<sup data-n=\"2921\">22</sup> שלמעל' מגוף פנימיו' המ\"ס שלכך נבקעו ויצאו בבחי' מותרות כמשל בקיעת הנוד סתום ביותר כו' כמו החכ' כשגובר עליו כח השכל ביותר נופל ממנו נובלות ששרש הנובלו' יותר גבוה מגוף אור השכל ולכך אמר דנובלו' חכמ' ש\"מ תורה לשבח<sup data-n=\"2922\">23</sup> דוקא כמ\"ש במ\"א וכך הוא טעם מעלות ענין שרש י\"ג מדה\"ר שנק' בשם י\"ג ת\"ד<sup data-n=\"2923\">24</sup> כו' שיוצאי' ממותרי מוחא סתימאה כו' וכמ\"ש ויעבור ה' על פניו ויקרא ה' ה' שהוא מלמעלה ממו\"ס שנק' טעם וחכמה כמוסה לרצון הנעלם ונק' ג\"כ שכל הנעלם מכל רעיון<sup data-n=\"2924\">25</sup> או פלאות חכמ'<sup data-n=\"2925\">26</sup> ולפ\"ז כשאמר דאור אבא יונק ממזל כו' הרי זה למעלה מח\"ס עצמה ולזה אמר הכל תלוי במזל<sup data-n=\"2926\">27</sup> אפי' ס\"ת בהיכל שהוא בחי' יחוד או\"א למטה נקודה דחכמה בהיכל' דבינה<sup data-n=\"2927\">28</sup> מאין ליש כנ\"ל שזהו ספר וספור<sup data-n=\"2928\">29</sup> שנק' ס\"ת בהיכל כידוע וזהו למעלה הרבה ממ\"ש דאבא ואימא מלבישין לזרועות דא\"א ומכ\"ש מבחי' נה\"י דא\"א שמלובשין באו\"א כו' להיות ידוע שבחי' ז\"ת דא\"א היינו רק בחי' המדות חג\"ת כו' שנק' יד הגדולה ויד החזקה<sup data-n=\"2929\">30</sup> כו' ונק' ג\"כ בזהר בשם טורי חשוכא (כידוע במאמר דהאי איילתא<sup data-n=\"2930\">32</sup> אזלת לטורא חשוכא ומשם ארחת מזונא שזהו בחי' עלי' המל' בחג\"ת דא\"א כו' וכמ\"ש ותרם התיבה<sup data-n=\"2931\">33</sup> כו'<sup data-n=\"2932\">34</sup> בחדש הז'<sup data-n=\"2933\">35</sup> שהוא ר\"ה<sup data-n=\"2934\">36</sup> שעולה המל' בהרי אררט טורי קרדניתא<sup data-n=\"2935\">37</sup> כו') כמו הרים הגבוהים שאין אור השמש מאיר עליהם כו' והיינו בחי' המדות שברצון שלמעלה מן השכל וטעם גלוי משא\"כ המדות שמצד השכל וטעם נק' טורי דנהורא<sup data-n=\"2936\">31</sup> דחכ' נק' אור<sup data-n=\"2937\">38</sup> כו' אבל המדות שברצון נק' טורי חשוכא מדות שבהעלם הרצון ושרשם מבחי' ח\"ס הנ\"ל שהוא הנק' תעלומות חכמה<sup data-n=\"2938\">39</sup> ענין טעם כמוס לרצון שנחלק ממנו ב' קוין חו\"ג שברצון כו' ולזה א' דאו\"א מלבישין לזרועות חו\"ג דא\"א כמו שאנו רואים שמחמת מדת החסד ואה\"ר שברצון נמצא שרש לשכל וטעם לזכות ולחסד כמו השוחד יעור כו' שמחמ' השוחד שיש לו אהב' ברצון ממציא טענה ומטעה כח שכלו מחוב לזכות כמו ר\"י שלקח כלכלה דפירי<sup data-n=\"2939\">40</sup> אמ' אי בעי טעין הכי כו' נמצא המדות חו\"ג מלובשי' בפנימי' דאו\"א ובחי' או\"א מלבישי' אותן מבחוץ וכמ\"ש אני בינ' לי גבור' דא\"א כו' כמ\"ש בע\"ח<sup data-n=\"2940\">41</sup> וד\"ל וביריד' המדריגה עוד אין מוחין דחו\"ב דאצי' מקבלי' רק מבחי' נו\"ה דא\"א שהוא הבאת השפע דחו\"ג למט' כמו נו\"ה שנק' מאזני צדק בכ\"מ גם למט' במדות שמצד אור השכל רק במדות שברצון שנק' אריכות דאנפין הן בלתי מוגבלים כמו הרצון עצמו שהוא בלתי מוגבל",[["2919","20","<b>ונוצר אותיות צינור</b>: תשא לד, ז [ושם: נצר]. ראה אג\"ק מכ\"ק אדמו\"ר שליט\"א ח\"ב ע' קיט ואילך. מאמרי אדה\"א ויקרא ח\"א ע' רמג. וש\"נ. שמות ח\"א ע' קעב. וש\"נ."],["2920","21","<b>שהמזלות נק' שערות</b>: ראה גם לקו\"ת אמור לט, א. מאמרי אדה\"ז שבהערה 27."],["2921","22","<b>שהמזלות. . שרשן מעצמו' הגלגלתא</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקכד ואילך. דברים ח\"א ע' רכח ואילך."],["2922","23","<b>דנובלו' חכמ' ש\"מ תורה לשבח</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז. ראה תו\"ח נח סג, ב ובהערה 26."],["2923","24","<b>י\"ג מדה\"ר. . י\"ג ת\"ד</b>: ראה זהר (אד\"ר) נשא קלא, א. תרומה [ספדצ\"נ פ\"ת] קעז, א. ע\"ח (שער א\"א) שי\"ג פ\"ט."],["2924","25","<b>שכל הנעלם מכל רעיון</b>: באוה\"ת לך (כ\"ד) ע' תרפה: נז' ברע\"מ. ראה הנסמן במאמרי אדה\"א בראשית ע' ח? ויקרא ח\"ב ע' תרכב."],["2925","26","<b>פלאות חכמ'</b>: ראה גם לעיל צה, ב. מאמרי אדה\"א נ\"ך ע' קנו. וש\"נ. דרושי חתונה ח\"ב ע' תקכב. תו\"ח בראשית כא, ב ובהערה 13."],["2926","27","<b>הכל תלוי במזל</b>: ראה זהר (אד\"ר) נשא קלד, א. דברים נחמדים ממהר\"ם שיף בתחלתן [נדפסו בסוף מס' חולין]. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קכז ובהנסמן לשם."],["2927","28","<b>נקודה דחכמה בהיכל' דבינה</b>: ראה זהר בהקדמה ו, רע\"א. תצוה קפ, א. הנסמן במאמרי אדה\"א בראשית ע' א. תו\"ח לך פא, ג."],["2928","29","<b>ספר וספור</b>: ס\"י פ\"א מ\"א."],["2929","30","<b>דא\"א. . חג\"ת. . יד הגדולה ויד החזקה</b>: בשלח יד, לא. בא יג, ט. ראה גם שע\"ת קג, ד. מאמרי אדה\"א ויקרא ח\"א ע' ריג. וש\"נ."],["2930","32","<b>דהאי איילתא</b>: ראה זהר שם."],["2931","33","<b>ותרם התיבה</b>: נח ז, יז [ושם התיבה ותרם ? ראה לעיל נה, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'רמ? שע\"ת מט, א]."],["2932","34","<b>כו'</b>: אג: ליתא."],["2933","35","<b>ותרם התיבה בחדש הז'</b>: כ\"ה גם בסידור ערבית לשבת קסט, ב."],["2934","36","<b>בחדש הז' שהוא ר\"ה</b>: נח ח, ד. ראה זהר בהעלותך קמט, ב. פינחס רנח, ב. מאמרי אדה\"א בראשית ע' קד. וש\"נ. תו\"ח נח נח, ד ובהערה 57. לעיל כד, ב. קה, א."],["2935","37","<b>בהרי אררט טורי קרדניתא</b>: ראה ת\"א ות\"י נח שם. רש\"י פסחים ז, א ד\"ה אפילו? חולין נד, ב ד\"ה דינרא."],["2936","31","<b>טורי חשוכא. . טורי דנהורא</b>: ראה זהר פינחס רמט, ריש ע\"ב. סה\"מ תקס\"ב ח\"ב ע' תקח וע' תקיג (בשם הה\"מ). מאמרי אדה\"א דברים ח\"א ע' פט. וש\"נ. שמות ח\"א ע' פח. וש\"נ. לעיל קד, ב. קה, א."],["2937","38","<b>דחכ' נק' אור</b>: ראה זהר בראשית ל, ב. תרומה קסז, א. לקוטי שיחות (דברים) כרך לד ע' 15 הערה 42. תו\"ח בראשית ז, ד הערה 50."],["2938","39","<b>תעלומות חכמה</b>: נסמן לעיל קט, ב."],["2939","40","<b>ר\"י שלקח כלכלה דפרי</b>: ועד\"ז מובא במאמרי אדה\"ז על מאמרי רז\"ל ע' כ ?שנתן לו. . מחמת שלקח\". אבל לעיל קב, ב ועד\"ז בתו\"ח וירא קיד, ב ?שהביאו לו שוחד\" ? ראה כתובות קה, ב."],["2940","41","<b>אני בינה. . דא\"א. . בע\"ח</b>: משלי ח, יד. ראה שם (שער או\"א) שי\"ד פ\"ב."]]],[2800530255,"ע\"כ גם בחי' נו\"ה הן בבחי' בלתי מוגבל וכידוע דפי' זכר רב טובך הוא בחי' יסוד דא\"א<sup data-n=\"2941\">1</sup> וכן ובטובך הגדול<sup data-n=\"2942\">2</sup> וכה\"ג וכן אם יגאלך טוב<sup data-n=\"2943\">3</sup> ורב טוב לבית ישראל<sup data-n=\"2944\">4</sup> וכה\"ג משא\"כ בחי' יסוד ז\"א שהוא בחי' מדות שנולדים מבינה הוא בבחי' הקטנות ביותר וכמ\"ש במ\"א בענין צדיק כתמר שזהו בחי' יסוד ז\"א כארז<sup data-n=\"2945\">5</sup> בלבנון ישגה בבחי' א\"ח שהוא ביסוד ע\"י וא\"א וכן מ\"ש בשלמה וידבר מן הארז<sup data-n=\"2946\">6</sup> אשר בלבנון עד האזוב בחי' קטנות יסוד ז\"א במל' שנק' קיר<sup data-n=\"2947\">7</sup> כו' (וכידוע בכוונות דאיש\"ר מברך<sup data-n=\"2948\">8</sup> דשמו גי' רצון<sup data-n=\"2949\">9</sup> ושמו הגדול בבחי' יסוד ומל' דאריך שיהי' מבורך באו\"א וזו\"נ כו' לאגברא ימינא על שמאלא<sup data-n=\"2950\">10</sup> וכמו ובטובך הגדול ישוב כו' וד\"ל):\n(כו) <b>ומעתה</b> יש להבין בירידת האור עוד בע\"ס דאו\"א עצמן מבחי' פנימית המוחין דאו\"א כשהן מקבלים מחו\"ג דא\"א ומכ\"ש כשעולין לקבל ממזלות דא\"א כנ\"ל לבחי' חיצוני' נה\"י דאו\"א שמלובשין במוחין דז\"א<sup data-n=\"2951\">11</sup> וכמ\"ש בע\"ח. והענין ידוע כמו שבת וי\"ט הן בבחי' פנימית המוחין דאו\"א כי השבת נק' קודש<sup data-n=\"2952\">12</sup> בעונג דחכ' מלה בגרמיה<sup data-n=\"2953\">14</sup> והוא בחי' פנימית אור אבא (שהוא פנימי' ע\"י<sup data-n=\"2954\">15</sup> וזה שנאמר וקראת לשבת עונג<sup data-n=\"2955\">16</sup> וכמ\"ש במ\"א בענין ג' סעודו' דשבת<sup data-n=\"2956\">17</sup> באריכות) וי\"ט נק' מקרא קדש<sup data-n=\"2957\">18</sup> בחי' שמחה<sup data-n=\"2958\">13</sup> כמ\"ש אם הבנים שמחה<sup data-n=\"2959\">19</sup> שהוא בחי' מוחין דאימא שמקבל מאבא כי השביתה דשבת הוא בחכ' ג\"כ דהיינו בפנימית אבא בחי' כח מ\"ה אין דחכמה קודם שמתפשט ליש בהשגה דבינ' וכן בינה בבחי' פנימי' הוא עומק נקודת המושג כו' כידוע שיש אין חכמה<sup data-n=\"2960\">20</sup> בבינה ובינה בחכמה והיינו הבן בחכמה וחכם בבינה<sup data-n=\"2961\">21</sup> שזהו בחי' יחוד פנימי' דאו\"א משא\"כ בחיצונית השפע דחו\"ב בחג\"ת נה\"י כו' כמו מדות שבחכמה שנק' בחי' ו\"ק דאבא<sup data-n=\"2962\">22</sup> כמו חסד שבחכמה דהיינו כח שכל המטה כלפי חסד או כח שכל אחר שמטה כלפי דין כו' ומאירי' בחו\"ג דבינה שהוא בא בהשגה בטוב טעם בהסבר לזכות ולחוב ונק' מדו' שבשכל המושג קודם שנולדו במהות בפ\"ע (כמשי\"ת) וכאשר אינו מוצא טעם בהסבר השגה ומ\"מ לא יוכל לומר בהיפוך כי שכלו מטה כך היינו בבחי' חו\"ג דאבא קודם שמאיר מאין ליש בבינה (כמו ענין שתיק רב<sup data-n=\"2963\">23</sup> כו') (והשתיקה סייג לחכ'<sup data-n=\"2964\">24</sup> משתוקא בתרין<sup data-n=\"2965\">25</sup> מפני שעולה ביטול כח מ\"ה דחכ' זה למקור המוציא כל השכלות שנק' ח\"ס כנ\"ל ומוציא משם השכלה חדש' כו') ובחי' נה\"י דאבא היינו בחי' מאזני השכל והחכמה איך שיבא הדבר חכ' לידי השפעה בבחי' כליות יועצות כו' (והיינו ענין התוקף שיש במוח שנק' תקיף בדעתו כמו הרגלים שיש בהן כח להקים כל הגוף כך בחי' נו\"ה דאבא מקימין לגוף המוחין ולהיפוך כשאינו תקיף בדעתו בקל יפול מסברתו מחוב לזכות ומטמא לטהור כו' וכן בנו\"ה דאמא) ודרך כלל הרי רק מבחי' נה\"י דאבא שמלובשים בנה\"י דאימ' משם נמצא מקור המוחין לז\"א שהן בחי' המדות שלמטה מן השכל (כמשי\"ת) וידוע פרטי עניני יחודים דאו\"א בין כשהוא בבחי' הפנימי' לצורך עצמן שהוא בבחי' ג\"ר שבהן קודם שמתפשטים במדות עדיין כו' ובין כשמתייחדים לצורך מוחין חדשים לזו\"נ שהוא בבחי' נה\"י לבד כו' וזהו ההפרש בין שבת לחול כו' (ובק\"ש הכוונה בה' אלקינו היינו בפנימי' דאו\"א<sup data-n=\"2966\">26</sup> שמשם ה' אחד יחוד דזו\"נ<sup data-n=\"2967\">27</sup> כשבא להם בחי' תוס' מוחין חדשי' כדי שיוכלו להוליד כו' והיינו במס\"נ דק\"ש משא\"כ בתורה ומצות בלא מס\"נ אין היחוד רק בחיצוניות דאו\"א בזו\"נ<sup data-n=\"2968\">28</sup> כמ\"ש במ\"א וכמו בענין עשרה הרוגי מלוכה שהעלו מ\"ן לאו\"א<sup data-n=\"2969\">29</sup> בבחי' הפנימי' ע\"י מס\"נ",[["2941","1","<b>זכר רב טובך. . יסוד דא\"א</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קע."],["2942","2","<b>ובטובך הגדול</b>: נוסח רבונו של עולם (תפלת השחר). ראה גם סידור סדר סעודת שבת רב, א [ובטובו]. מאמרי אדה\"ז על ענינים ע' רח."],["2943","3","<b>אם יגאלך טוב</b>: רות ג, יג."],["2944","4","<b>ורב טוב לבית ישראל</b>: ישעי' סג, טז."],["2945","5","<b>צדיק כתמר. . כארז</b>: תהלים צב, יג [בדילוג]. ראה גם לקמן קלד, ב. סידור ערבית לשבת קסט, ב. פיה\"מ פז, ב. מאמרי אדה\"א במדבר ח\"א ע' א'קמו."],["2946","6","<b>וידבר מן הארז</b>: מלכים-א ה, יג [בדילוג. ושם: ועד]. ראה גם פיה\"מ פז, ג."],["2947","7","<b>במל' שנק' קיר</b>: ראה זהר ויחי רכח, ב. תרומה קלג, א. מאו\"א מערכת קיר (אות כג)."],["2948","8","<b>דאישמ\"ר מברך</b>: נוסח הקדיש."],["2949","9","<b>דשמו גי' רצון</b>: נסמן לעיל קכב, ב."],["2950","10","<b>לאגברא ימינא על שמאלא</b>: ראה זהר וישלח קסה, ב. מקץ קצח, ב. וארא לב, סע\"א. יתרו סז, א. אמור צב, ב."],["2951","11","<b>נה\"י דאו\"א. . במוחין דז\"א</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח פ\"ב. (שער הולדת או\"א וזו\"נ) שט\"ז פ\"ז."],["2952","12","<b>השבת נק' קודש</b>: תשא לא, יד. טו. ראה זהר אמור צה, א. פע\"ח (שער מקרא קודש) ש\"כ פ\"א. סידור שער המועדים ריז, א. לקו\"ת צו יב, א. מאמרי אדה\"א בראשית ע' מה. אג\"ק מכ\"ק אדמו\"ר שליט\"א ח\"ב ע' קכט ואילך. לקו\"ש (שמיני) כרך לב ע' 64 הערה 47."],["2953","14","<b>קודש. . מלה בגרמיה</b>: זהר אמור צד, ב. ראה גם לעיל כט, א ובהנסמן במ\"מ לשם."],["2954","15","<b>פנימית אור אבא. . פנימי' ע\"י</b>: ראה סה\"מ תקס\"ה ח\"ב ע' תתסה. לקו\"ת נצבים מט, ד. לעיל פט, א בשם הע\"ח. הנסמן במאמרי אדה\"א בראשית ע' כה? דברים ח\"ג ע' תתע וע' תתי? קונטרסים ע' תכה ואילך. שם ע' סט (במהדו\"ת)."],["2955","16","<b>וקראת לשבת עונג</b>: ישעי' נח, יג."],["2956","17","<b>בענין ג' סעודו' שבת</b>: ראה סידור סדר סעודה שלישית רד, ג."],["2957","18","<b>וי\"ט נק' מקרא קדש</b>: בא יב, טז. אמור כג, ד ואילך. הנסמן לעיל בהערה השבת נק' קודש."],["2958","13","<b>השבת. . בעונג. . ויו\"ט. . שמחה</b>: נסמן לעיל קיג, א."],["2959","19","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["2960","20","<b>חכמה</b>: אזיב: דחכמה."],["2961","21","<b>הבן בחכמה וחכם בבינה</b>: ס\"י פ\"א מ\"ד."],["2962","22","<b>ו\"ק דאבא</b>: ראה גם סידור סדר הגדה רצה, ב. תו\"ח בראשית טו, א ובהנסמן לשם."],["2963","23","<b>שתיק רב</b>: ביצה ו, א. ראה גם מאמרי אדה\"א בראשית ע' צד ואילך. וש\"נ."],["2964","24","<b>והשתיקה סייג לחכ'</b>: אבות פ\"ג, מי\"ג."],["2965","25","<b>משתוקא בחרין</b>: מגילה יח, א. ראה גם מאמרי אדה\"א ויקרא ח\"ב ס\"ע תתטז ואילך. וש\"נ. נ\"ך ע' שנח ואילך. וש\"נ. תו\"ח ח\"ש קמ, ד. לעיל קא, א."],["2966","26","<b>בה' אלקינו. . דאו\"א</b>: ואתחנן ו, ד. פע\"ח (שער הק\"ש) ש\"ז פ\"ז."],["2967","27","<b>ה' אחד יחוד דזו\"נ</b>: ראה גם מאמרי אדה\"א בראשית ע' שפ."],["2968","28","<b>בתורה ומצות בלא מס\"נ. . בזו\"נ</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכא. וש\"נ."],["2969","29","<b>עשרה הרוגי מלוכה. . לאו\"א</b>: ע\"ח (שער מ\"ן ומ\"ד) של\"ט ד\"א. ראה גם הנסמן במ\"מ לשע\"ת ח\"א נו, ב."]]],[2800530256,"דוקא) (וזהו ענין יחוד או\"א עילאין ויחוד או\"א תתאין שהוא יש\"ס ותבונה כמ\"ש למעלה בענין בינה ותבונה<sup data-n=\"2970\">30</sup> באריכות ובחי' יש\"ס הוא ו\"ק דאבא ותבונה ו\"ק דאימא שנק' או\"א תתאין ויש עוד יש\"ס למעלה גם מאו\"א עילאין שהוא ו\"ק דח\"ס דא\"א<sup data-n=\"2971\">31</sup> ותבונה ו\"ק דבינה דא\"א שמשם נמשך שורש יחוד או\"א עלאין בבחי' ג\"ר שבהן כו') והנה כאשר נמשך מאו\"א מוחין לזו\"נ בשביל תולדות הנשמות צריך להיות היחוד באו\"א בפנימי' המוחין בשרשם בב' מזלות דא\"א (והיינו בני כו' במזלא תליא<sup data-n=\"2972\">32</sup> כו') כמ\"ש במ\"א שזהו ענין אל עליון עליית אור פנימית אבא כשמקבל ממזל ונוצר כו' אז גומל חסדים טובים בבחי' יסוד שנק' קונ' הכל להוליד תולדו' בזו\"נ וזהו וזוכר חסדי אבות ומביא גואל לבני בניהם<sup data-n=\"2973\">33</sup> כו' והמשל בזה ידוע כמו איש שהוא חכם מופלג ביותר כאשר יודע לעומק השכל ממקור חוצבו דוקא אז יכול להיות משפיע לנמוך ביותר גם לתינוק קטן לעשות צירופים חדשים באופן השכלת השכל ההוא לא כהוויתו דוק' וכן ביכולתו לחדש שכל אחר להוליד מחדש מחמת זה השכל משא\"כ מי שאינו חכם מופלג ואינו תופס רק החכמה והשכל דברים כהוויתן לבד די להפקיע להשיגו לעצמו בלבד אבל לא יוכל להוליד חדשו' ממנו כלל וכ\"ש שלא יוכל להוריד ולהשפיל הסבר השכל להבינו לתינוק כו' ונמצא שבחי' נה\"י דחכמ' שהוא בחי' יסוד הכח המשפיע למקבל תלוי בכח המשכיל מקור חוצב השכל מאין ליש דוקא כו' וכך הוא בענין תולדות הנשמות מבחי' נה\"י שאינו מוליד כ\"א בתוס' כח במקור המוחין שלו מלמעלה מעלה מן השכל כו' והוא הטעם שבשביל תולדות נשמות ע\"י יחוד או\"א צריך להיות מלמעלה ממקור המוחין דאו\"א שזהו מבחי' מזלות דח\"ס שהוא למעלה גם מחכמה ובינה דא\"א עצמו כנ\"ל והיינו טעם ליחוד פנימית דאו\"א בליל שבת קודש מפני שהוא בשביל להוליד נשמות שלכך אז דוקא זמן זיווגא דחכימין<sup data-n=\"2974\">34</sup> שהן ת\"ח שנק' קודש ושבת שרשו בקודש העליון בחי' פנימית אור אבא כנ\"ל וד\"ל:\n(כז) <b>והנה</b> אחר שנתבאר דרך פרט קצת בענין אורות דאו\"א ובחי' יחודם בפנימית וחיצוניות כנ\"ל מעתה יש לבאר פרטי ענין אורות דז\"א שנק' ישראל ויעקב<sup data-n=\"2975\">35</sup> וכל פרטי היחודי' דזו\"נ שנק' יחוד ישראל ולאה או יחוד יעקב ורחל כו' כידוע. אך תחל' יש להבין הקדמה בענין אורות וכלים בכלל ובפרט דהנה ידוע פי' מה שאמר דאיהו וחיוהי חד הן אורות ואיהו וגרמוהי חד<sup data-n=\"2976\">36</sup> הן בחי' הכלים ומצד בחי' האורות דע\"ס בכלל ובפרט נק' ע\"ס בלי מה בלי מהות<sup data-n=\"2977\">37</sup> וכמ\"ש ולאו מכל אינון מדו' כלל<sup data-n=\"2978\">38</sup> כו' אך מצד בחי' הכלי' הן בבחי' מציאת דבר מה וז\"ש אפיק י' תיקונין וקרינן לון עשר ספירין כו' לאחזאה כו' לאנהגא בהון עלמין<sup data-n=\"2979\">39</sup> כו' וכן מה שכללות ע\"ס דאצי' נק' בד' שמו'<sup data-n=\"2980\">40</sup> ע\"ב ס\"ג מ\"ה ב\"ן ע\"ב במילוי יודין<sup data-n=\"2981\">41</sup> בחכ'<sup data-n=\"2982\">42</sup> וס\"ג<sup data-n=\"2983\">44</sup> ביודי\"ן וא'<sup data-n=\"2984\">43</sup> בבינה<sup data-n=\"2985\">45</sup> ומ\"ה במלוי אלפין בז\"א<sup data-n=\"2986\">46</sup> וב\"ן במילוי ההי\"ן במל'<sup data-n=\"2987\">47</sup> כידוע ובל' הזהר כלל הע\"ס נק' רזא דשמא קדישא<sup data-n=\"2988\">48</sup> בלבד כידוע הכל הוא רק מצד בחי' הכלים דוקא כידוע. וביאור הדברי' ידוע על מאמ' דתלת שליטין לעילא<sup data-n=\"2989\">49</sup> מוחא ולבא וכבדא כו' שהן בחי' ג' כלים לנר\"ן נשמה במוחא<sup data-n=\"2990\">50</sup> ורוח בלבא ונפש בכבדא כו' אבל בחי' חי' יחידה הוא למעלה מהגבלת כלים<sup data-n=\"2991\">51</sup> כו' ובבחי' הכלים כלול מראש תוך סוף שהוא פנימי' הכלים ואמצעית הכלים וחיצוני'<sup data-n=\"2992\">52</sup> הכלים כו' וכידוע בענין רמ\"ח איברים דמלכא<sup data-n=\"2993\">53</sup>",[["2970","30","<b>בענין בינה ותבונה</b>: לעיל קי, א ואילך."],["2971","31","<b>יש\"ס. . ותבונה. . דא\"א</b>: ראה גם הגהת צמח בע\"ח (דרוש עגו\"י) ש\"א ע\"ה. לקמן קלג, א ובהנסמן במ\"מ לשם."],["2972","32","<b>בני כו' במזלא תליא</b>: ראה מועד קטן כח, א. ביאוה\"ז פקודי נז, א. מאמרי אדה\"א שמות ח\"ב ע' תט. דברים ח\"ד ע' א'תל. וש\"נ."],["2973","33","<b>אל עליון. . לבני בניהם</b>: נוסח תפלת העמידה. ראה פע\"ח (שער העמידה) ש\"ט פ\"ג. סה\"מ תקס\"ח ח\"א ע' שסג."],["2974","34","<b>בליל שבת. . זיווגא דחכימין</b>: ראה זהר בהקדמה יד, סע\"א. תרומה קלו, רע\"א. ויקהל רד, ב."],["2975","35","<b>דז\"א שנק' ישראל ויעקב</b>: ראה לקמן קלג, א ובהנסמן במ\"מ לשם."],["2976","36","<b>דאיהו וחיוהי חד. . וגרמוהי חד</b>: ראה ת\"ז בהקדמה (ג, ב). אגה\"ק ס\"כ."],["2977","37","<b>ע\"ס בלי מה בלי מהות</b>: ס\"י פ\"א מ\"ב ובמפרשים שם."],["2978","38","<b>ולאו מכל אינון מדו' כלל</b>: ראה ת\"ז בהקדמה (יז, ב)."],["2979","39","<b>אפיק י' תיקונין. . עלמין</b>: ראה ת\"ז שם (יז, א-ב)."],["2980","40","<b>בד' שמו'</b>: ראה ע\"ח (שער טנת\"א) ש\"ה רפ\"א. (שער דרושי אבי\"ע) שמ\"ב רפ\"א."],["2981","41","<b>ע\"ב במילוי יודין</b>: ראה ע\"ח (שער טנת\"א) ש\"ה פ\"א. (שער רפ\"ח ניצוצין) שי\"ח פ\"א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קצב."],["2982","42","<b>ע\"ב. . בחכ'</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח פ\"ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שנג."],["2983","44","<b>וס\"ג ביודי\"ן וא'</b>: אגוזיאיביג: וס\"ג במילוי ההי\"ן ? ראה גם תו\"ח וירא צז, ד ובהערה 48."],["2984","43","<b>וס\"ג ביודי\"ן וא' </b>[ וא\"ו]: ראה זהר (רע\"מ) פינחס רמו, ב. לוח השמות במק\"מ סוף בראשית קכו, ב. ע\"ח (שער אח\"פ) ש\"ד פ\"ג."],["2985","45","<b>וס\"ג. . בבינה</b>: ראה ע\"ח שער הכללים פ\"ח. הנסמן במאמרי אדה\"א שמות שם."],["2986","46","<b>ומה במלוי אלפין בז\"א</b>: ראה ע\"ח (שער לאה ורחל) של\"ח פ\"א. פ\"ב. מאמרי אדה\"א שמות ח\"ב ע' תמה. וש\"נ."],["2987","47","<b>וב\"ן במילוי ההי\"ן במל'</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח פ\"ג."],["2988","48","<b>ובל' הזהר. . דשמא קדישא</b>: ראה זהר יתרו סז, ב ובמפרשים שם. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' שנ. וש\"נ."],["2989","49","<b>דתלת שליטין לעילא</b>: ראה זהר תרומה קנג, א. (מדהנ\"ע) תולדות קלח, א. ז\"ח רות פ, א."],["2990","50","<b>לנר\"נ נשמה במוחא</b>: ראה אב\"ע משפטים כג, כה. הנסמן במאמרי אדה\"א קונטרסים ע' שכא. שמות ח\"ב ע' תקמג ואילך."],["2991","51","<b>חי' יחידה. . כלים</b>: ראה ע\"ח (שער הפרצופים) ש\"ל פ\"ב. (שער פנימיות וחיצוניות) ש\"מ ד\"א. הנסמן במאמרי אדה\"א קונטרסים ע' רנג. שמות ח\"ב ע' תקמח ואילך."],["2992","52","<b>הכלים. . פנימי'. . ואמצעית. . וחיצוני'</b>: ראה ע\"ח (שער המוחין) ש\"כ פ\"ה."],["2993","53","<b>רמ\"ח איברים דמלכא</b>: נסמן לעיל ד, ב."]]],[2800530257,"דט\"ס של בחי' ז\"א<sup data-n=\"2994\">1</sup> שט' פעמי' ט' עולה פ\"א וג' פעמי' טפ\"ט נגד ג' מדריגות שבכלים רת\"ס הנ\"ל עולה רמ\"ג וה\"ח המגדילים הוא רמ\"ח<sup data-n=\"2995\">2</sup> והוא כללות ענין כלים דז\"א שנק' גופא דמלכא וגם לבושין תקינת לון דמנהון פרחין נשמתין<sup data-n=\"2996\">3</sup> כו' שהן לבושין דמח' כו' כמשי\"ת הכל ואמנם הנה ענין אור וכלי דרך כלל הגם שיש בו הרבה אופנים שוני' מאד אך כללותו הוא ע\"ד אור וחיות הרוחני של ראיה רוחני' כשמתלבש וממוזג בהגשמה בכלי חומר העין בבחי' ראי' גשמית שיש בזה ב' דברים הא' שינוי המהות מרוחניות לגשמיות שהראות גשמי<sup data-n=\"2997\">4</sup> יתפוס בגשם משא\"כ ברוחניו' אור הראי' וכן אור וכח השכל הרוחני הממוזג בגשם כלי המוח עד שנק' התחכמות וכח התנועה בתנועת הגשם וכה\"ג בכח הצמיחה רוחני' שמורכב ומלובש בצמיחה גשמי' בגשם הצומח והב' ענין ההגבלה ושיעור שבחומר הכלי מוגבל ונמדד בשיעור כמו בראי' גשמי' עד ס' מילין<sup data-n=\"2998\">5</sup> כו' וכן ענין התחכמות ותנועת הגשם מתפשטים בהגבלה מצומצמת דוקא עד שיכלה כחם המוגבלת כמו שתקצר גשם השגת כלי המוח ויכלה כחו מצד קוטן הכלי וכן יוקטן ויופסק כח תנועה הגשמי' שמכח היד בפעולה או בהגבהת משאוי וכה\"ג מצד הגבלת הכח המניע (משא\"כ מצד עצם כח הרוחני של המניע התנועה שאין בו הגבלה והפסק וראי' מהגבהת משא כבד הבא בבהלה פתאומי' ביתר הרבה מכחו מצד בחי' המקיף כידוע) וכך הוא כל ענין חומר וצורה<sup data-n=\"2999\">6</sup> שהחומר מלבד שהוא בא בשינוי המהות הנה הוא מגביל לצורה אבל החומר הוא מעין ודוגמת הצורה<sup data-n=\"3000\">7</sup> כמו חומר כלי העין לראות וחומר כלי המוח להשכיל וכה\"ג אבל החומ' נעשה מהתעבות והגשמה של הצורה הרוחני' מסוף כל המדריגות שבו כמו מסוף המדריגה דרוחניות הצמיחה נעשה כח צמיחה בגשם וכמו סוף של חיות הרוחני דנפש מלובש בדם כמ\"ש כי הדם הוא הנפש<sup data-n=\"3001\">8</sup> כו' וכך סוף המדריגה של אור השכל הרוחני מתמזג בחומר כלי המוח וכן סוף הגשמה דרוחניו' הראי' ממוזג בחומר העין ולזאת אנו רואים שבכ\"מ באין הגדלת החומר עם הגדלת הצורה כא' ממש כמו בהגדלת חומר כלי הגוף שנגדלי' ביחד עם גידול אור וחיות הצורה הרוחניו' כמו גידול הכנת חומר המוח לפי ערך גידול האור והצורה של השכל שכאשר יגדל התינוק ויצמח אור שכלו ברוחניותו ממילא יצמח כלי הכנת מוחו כמ\"ש ימים ידברו ורוב שנים<sup data-n=\"3002\">9</sup> כו' שנגדל הכלי עם האור יום ויום עד ע' שנה שבא לכלל גדלות המוחין<sup data-n=\"3003\">10</sup> כידוע וד\"ל:\n(כח) <b>והנמשל</b> מדוגמא זו הוא בבחי' ג' כלים דמוחא ולבא כו' בדרך כלל עכ\"פ דאור החכמה דאצי' מצד אצילותה מעצמות אור המאציל ה\"ז כאור השכל הרוחני עצמו שנמשך מעצם כח החכמה שבבחי' עצמו' הנפש שמתאחד הוא עדיין במקור חוצבו ממש כשלהבת כו'<sup data-n=\"3004\">11</sup> או גם כגלוי הרצון הנ\"ל מעצם הרצון דבחי' א\"ק הגם שזהו כמו מראה וגוון בלבד (כמ\"ש למעלה בענין קורא הדורות מראש שזהו עשר ספי' דאצי' שיצאו מהעלם דא\"ק שהוא גילוי רצון בדבר נבדל כו'<sup data-n=\"3005\">12</sup> בסוף אות הי\"ט) עכ\"ז נק' עשר ספי' בלי מ\"ה בלי מהות עדיין כי כמו שהגוון הוא ג\"כ עצמי שא\"א להיות גוון היפוכו לדבר בעצם כגוון התפוח בלובן להורות על עצם טעם המתיקות<sup data-n=\"3006\">13</sup> שבו וכן אור שכל ורצון מטה כלפי חסד גם שהוא בענין נבדל מאחר שהוא מורה על העצם כו' ולכך כל התהוות אורות דע\"ס הן באים מבחי' אותיות עצמיים דמאצילן וכמו",[["2994","1","<b>דט\"ס של בחי' ז\"א</b>: בלקו\"ת שה\"ש יח, א מציין ?כמ\"ש במ\"א בד\"ה אלפי שנאן בפ' יתרו [תו\"א יתרו עב, א] ועיין בזהר נח דס\"ה א' ובע\"ח שער א\"א פ\"ב\"."],["2995","2","<b>שט' פעמי' ט'. . רמ\"ח</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד פ\"ו. לקמן קל, ב. הנסמן במ\"מ לשע\"ת ח\"א מב, ב."],["2996","3","<b>לבושין. . דמנהון </b>[אג: דמנייהו]<b> פרחין נשמתין</b>: ת\"ז בהקדמה (יז, א)."],["2997","4","<b>שהראות גשמי</b>: אג: שהראי' גשמי'."],["2998","5","<b>בראי'. . ס' מילין</b>: ראה גם סה\"מ תקס\"ה ח\"ב ע' תשכז ?בס' הטבע. . עד ס' מילין\". מאמרי אדה\"א הנחות תקע\"ז ע' שלו. וש\"נ."],["2999","6","<b>חומר וצורה</b>: ראה מו\"נ ח\"א פי\"ז. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קעו. מאמרי אדה\"א שמות ח\"א ע' כג."],["3000","7","<b>החומר הוא מעין. . הצורה</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 3 [במהדורת תשמ\"ט]. מאמרי אדה\"א קונטרסים ע' רח."],["3001","8","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["3002","9","<b>ימים ידברו ורוב שנים</b>: איוב לב, ז."],["3003","10","<b>ע' שנה. . גדלות המוחין</b>: ראה גם שע\"ת ז, סע\"א ובהנסמן לשם."],["3004","11","<b>כשלהבת כו'</b>: ס\"י פ\"א מ\"ז. לעיל קכג, ריש ע\"ב."],["3005","12","<b>כו'</b>: אג: כנ\"ל."],["3006","13","<b>כגוון התפוח בלובן. . המתיקות</b>: ראה גם מאמרי אדה\"א במדבר ח\"ה ע' א'תתסח. ספר הערכים חב\"ד ח\"ד מערכת אורות דספירות פשיטותם ע' קלד ס\"ה."]]],[2800530258,"שם ע\"ב שממנו בא בחי' אור החכמה דאצי' בגילוי ה\"ז שם המורה על עצם דחכמה דא\"ק כו' וכן שם ס\"ג המורה על עצם אור דבינה דא\"ק כו' והן ע\"ב ס\"ג כו' שלפני ע\"ס דאצי' ונק' שמות המאציל כו' וכמו בחי' האחרונה שבצורה הרוחניות שמקושר אל תחילת התהוות האור והצורה בכלי החומ' כו' כנ\"ל בדם הוא הנפש ובצמיחה הרוחני' ובעין ומוח כו' אבל בחי' הכלי המגביל האור דחכמה דאצי' הוא כמו אור השכל שממוזג כבר בחומר המוח שחומר המוח מקבל רק מהתעבות סוף אור השכל ע\"כ מגבילו מלבד שינוי המהות כו' כך הוא אור החכמה כשמתלבש במוחא ונק' חכמה מוחא<sup data-n=\"3007\">14</sup> כו' שאז מצד בחי' כלי החכ' הוא בא בשם מציאות דבר שכל הנקרא התחכמות דבר מה בפרט וכן המדות הרוחניי' בלבא והנפש הרוחניות בכבדא כו' והן ענין ג' שליטין לעילא בחי' ג' כלים כללים לנר\"נ דז\"א דאצי' נשמה שהוא בחי' מוחין דחו\"ב שבז\"א במוחא ורוח בלבא כו' והן האותיות דאורות דאצי' שזהו ענין ד' שמות ע\"ב ס\"ג דאצי' כו' שנק' כלים לע\"ס דאצילות המגבילים האור ומצמצמו לפי שמהתעבות האור נעשה הכלי כמ\"ש בע\"ח<sup data-n=\"3008\">15</sup> והוא הנק' בחי' הישות של האור כשנראה לבחי' יש ודבר מה במציאות כידוע וד\"ל (ונמצא ב' מיני שמות ע\"ב ס\"ג כו' א' לפני האצי' והב' אחר האצי' שהן הכלים המגבילים ולפי זה המכוין בשמות מכוין במקור האורות כמו מכוין בבחי' שם ע\"ב מקור לאור החכמה כו' וממילא הוא מכוון בכלי החכמ' שיומשך למטה כו' וד\"ל והיינו כוונות שמות דח\"י ברכות שמו\"ע כי הא בהא תליא משום דשורש הכלים המגבילים משמות דעצמות המאציל כמשי\"ת וד\"ל) והיינו מ\"ש וקרינן לון י' ספי' כו' לאחזאה לאנהגא כו' כי תיקוני' הן בחי' הכלים<sup data-n=\"3009\">16</sup> לאורות דאצי' וכמו ע\"ד משל תיקון העין שיתפשט ראי' גשמית שבו יותר הוא ע\"י אמצעות כלי ההבטה כו' כך תיקון התפשטות ראי' הרוחניות ע\"י אמצעות כלי העין הגשמי כו' וכמ\"ש במ\"א ע\"כ מצד בחי' הכלים המגבילים עי\"ז דוקא יוכל להיות כל בחי' השפעות והמשכות למטה מטה וכמו ע\"י כלי המוח שישיג השכל ימשיכנו להמדות או להשפיעו לזולתו וכן ע\"י אמצעות כלי הלב לאור האהבה והחסד הרוחני יבא לכלל השפעה למקבל כידוע ולכך נק' תיקונין כדי שיבא ע\"י בחי' המשכה מאצי' לבריאה והיינו רק לאחזאה כו' אבל מצד עצמות אור המאצי' נק' ע\"ס בלי מה<sup data-n=\"3010\">17</sup> כנ\"ל וכמ\"ש במ\"א באריכות:\n(כט) <b>אך</b> גם הנה בהתבוננות באורות וכלים דאצי' דרך פרט יותר אין כללות ועיקר המכוון בהם רק בענין זה דאיהו וחיוהי חד וגרמוהי חד שבאמת אין הפרש בין איהו וחיוהי חד לאיהו וגרמוהי חד דגם שהאורות הן בלי מה והכלים הן בבחי' יש כו' מ\"מ מצד עצמות המאציל הרי עשה שורש להתהוות הכלים קודם שעשה שורש להתהוות האורות דמה שמהתעבות האור נעשה כלי הרי קדם לזה עצמו שרש ומקור והוא שנק' חומר הפשוט או חומר ההיולי שקודם לצורה כו' וביאור הדברים ידוע ומובן מהקדמה הידוע בענין כלים המגבילים ממש שיש ב' מיני גבול הא' כח המגביל בעצם כמו כלי המוח המגביל והעין המגביל וכה\"ג אבל הוא רק בכח ולא בפועל עדיין כמו שיש בכח ביד להגביל כל תנועה בגשם קודם שיגביל בפו\"מ התנועה ואעפ\"י שגבול זה שבפועל ובגלוי הוא ממש כמו אופן אותו הכח המגביל הרוחני שביד שהוא מקור ושרש להגבלה זו שבפועל מ\"מ נבדל ערך הגבול בכח מגבול בפועל הא' שזה רוחני ועצמי",[["3007","14","<b>חכ' מוחא</b>: זהר (רע\"מ) פינחס רלה, ב. ת\"ז בהקדמה (יז, א). ת\"ע (קכג, א)."],["3008","15","<b>שמהתעבות האור. . בע\"ח</b>: ראה שם (שער העקודים) ש\"ו פ\"ג. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנג. מאמרי אדה\"א נ\"ך ע' קלד. וש\"נ."],["3009","16","<b>תיקוני'. . הכלים</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' צח ובהנסמן במ\"מ בריש המאמר שם."],["3010","17","<b>לאחזאה. . ע\"ס בלי מה</b>: ת\"ז בהקדמה (יז, ב). ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקטז ואילך. וש\"נ. דברים ח\"ב ע' תנו ואילך."]]],[2800530259,"וזה גשמי ונבדל מן העצם והב' שהגבול בכח אינו גבול ממש רק שמגביל בכחו עפ\"י רצון ובחירה לזה ואינו גבול מוכרח לומר שאין לו כח התפשטות עוד רק שאינו רוצה להתפשט יותר כו' וה\"ז רק עוש' את ההגבלה ואינה הגבל' אמיתי' כגבול בפועל שהוא הגבלה אמיתי' כו' (וכמ\"ש במ\"א בענין פנימי' הכלים וחיצוניות הכלי'<sup data-n=\"3011\">1</sup> שיתבאר בעזר\"ה) וכך יובן למעלה בשרש ומקור כלים המגבילים לאור דהיינו בשרש ומקור כח המגביל שלהם שבא ונמשך מן העצמות שמשם נמשך התהוות האור עצמו כמו מקור התהוות אור הרצון מהעלם עצם המקור לכל רצון הרי משם ג\"כ נמשך כח הגבול להגביל כח התפשטות אור הרצון שלא יתפשט עוד כדי שיוכל להיות טעם לרצון שאם לא היה פוסק כח ואור הרצון לא הי' בא לעולם לכלל טעם לרצון והוא ממאמר קו המדה העושה כל גבול בפועל ממש באורות וכך הוא עושה כל גבול בפו\"מ בכלים דע\"ס המגבילים איך שיגבילו בפו\"מ אבל מקור ושרש שלהם אינו בחי' גבול אמיתי רק שהוא עושה את אופן ההגבלה (שזהו בא מקו המדה מבחי' גבו'<sup data-n=\"3012\">2</sup> דאא\"ס בחי' כח המכווץ שדומה לכח המתפשט וב' קוין שקולין הן כו' כי כל יכול יש בו כח המגביל<sup data-n=\"3013\">3</sup> ג\"כ כו' (וכמ\"ש במ\"א) ומבואר למעלה<sup data-n=\"3014\">4</sup> שזהו בחי' הרשימו כו' שמשם הוא שרש הגבלת הכלים דע\"ס דאצי' ומבחי' הקו שנמשך מהרשימו הוא שרש כל האורות<sup data-n=\"3015\">5</sup> כו' וכמ\"ש במ\"א באריכות) וא\"כ גם שבחי' הכלי' דאצי' מגבילים ממש בבחי' שמות דע\"ב ס\"ג הנק' אותיות הרי אין זה רק מצד כח העושה לגבול זה בעצמו' המאציל והיינו דאיהו וגרמוהי חד מכח דא\"ס עצמו כמו דאיהו וחיוהי חד בבחי' האורות כו' (ובאמת גם בחי' הכלים דע\"ס דאצי' הן<sup data-n=\"3016\">7</sup> כח הגבול<sup data-n=\"3017\">6</sup> ולא גבול בפועל רק כאשר האור ושפע נגבל מאין ליש בבי\"ע אז נק' גבול בפו\"מ וכמשי\"ת בעז\"ה) ולפ\"ז המכוין בשמות דע\"ב ס\"ג שהן בבחי' הכלים המגבילים ממש כו' ה\"ז עצמו הכוונה במקור השמות דע\"ב ס\"ג כו' שמהם נמשך מקור האור דאצי' (והוא שם העצם שהוא מורה על עצם המקור כנ\"ל) והיינו ממקור התהוות הכלים דאיהו וגרמוהי חד כנ\"ל וממילא מובן דגם בבחי' תיקונין הנ\"ל ע\"ז אמר ג\"כ איהו וגרמוהי חד משום דגבול בפועל מתאחד עם הגבול בכח המגביל לגבול זה שבפועל ע\"ד דוגמא מכח המגביל שביד שמיוחד ומקושר בגבול בפועל שבתנועה כנ\"ל (ומכ\"ש בכלים דמוחא ולבא כו' שאינם נק' גבול בפועל עדיין כנ\"ל רק שמגבילי' ומתארי' לאורות שיהיה ניכר במציא' יש בלבד אבל יש להן שרש בעצמות כמו שיש לאורות שורש בעצמות בשקול וכח ומקור א' ממש שהוא בחי' א\"ס ממש דכמו שאא\"ס למטה עד כו' כך למעלה<sup data-n=\"3018\">8</sup> כו' שהן חו\"ג שבעצמות<sup data-n=\"3019\">9</sup> ואמנם באו\"כ בשרשן נהפוך הוא מבבחי' גילויין דבגלויין הרי בחי' צמצום באורות וחסדים בהתפשטות בכלים דגם שהן מגבילים הרי ע\"י כל התפשטות למטה דוקא ובשרשם להיפוך דהצמצום ברשימו העושה הגבול בכח כו' והחסדים בהתפשטות הוא לאורות שהוא מבחי' הקו כו' כמ\"ש במ\"א וד\"ל:\n(ל) <b>ובזה</b> יובן המאמר וכד אנת תסתלק מנייהו<sup data-n=\"3020\">10</sup> אשתארו כו' כגופ' בלא נשמתא שהוא בחי' הכלים דמוחא ולבא כו' שנק' גופא בלא נשמתא שהן בחי' האורות דנר\"נ כו' אך מאין ימצא מציאת כלי בלא אור מאח' שמהתעבות האור נעשה כלי כנ\"ל אבל לפי הנ\"ל דשרש הכלי' קדם לשרש האורות כו' א\"כ יש מציא' לכלי' בפ\"ע וע\"ז א' דאיהו וגרמוהי חד כו' (ולפ\"ז המכוין בשם הוי'",[["3011","1","<b>פנימי' הכלים וחיצוניות הכלי'</b>: ראה ביאוה\"ז פקודי נז, ד."],["3012","2","<b>גבו'</b>: א: גבול. ג: גבורה."],["3013","3","<b>כל יכול. . כח המגביל</b>: ראה עבודת הקדש ח\"א רפ\"ח. דרך אמונה ? להנ\"ל ? רפ\"ב [קה\"ת תשמ\"ח ע' יג]. מאמרי אדה\"א קונטרסים ע' תקפד. לעיל קכא, א ובהערה 9."],["3014","4","<b>ומבואר למעלה</b>: קיט, ב."],["3015","5","<b>הרשימו. . הכלים. . הקו. . האורות</b>: ראה מאמרי אדה\"ז על ענינים ע' שמו ואילך בשם הע\"ח. תקס\"ח ח\"א ע' שכב ואילך. סידור ערב שבת קסו, א. דר\"מ נא, א. לקו\"ת ויקרא (הוספות) נד, א."],["3016","7","<b>הן</b>: אזיאיביג: נק'. ג: רק."],["3017","6","<b>הכלים. . כח הגבול</b>: ראה אגה\"ק ס\"כ. מאמרי אדה\"ז תקס\"ב ח\"א ע' קפח. תקס\"ז ס\"ע רמא ואילך. ענינים ע' שטו. ע' שמז. פרשיות התורה ח\"א ס\"ע קעז ואילך. מארז\"ל ע' קסב ואילך. סה\"מ תרמ\"ג ע' קיח. ספר הערכים חב\"ד ח\"ד מערכת אורות דספירות פשיטותם וציורם ע' סח ואילך. וש\"נ."],["3018","8","<b>שאא\"ס למטה. . למעלה</b>: נסמן לעיל קכא, א."],["3019","9","<b>חו\"ג שבעצמות</b>: נסמן לעיל שם."],["3020","10","<b>וכד אנת תסתלק מנייהו</b>: ראה ת\"ז בהקדמה (יז, ב)."]]],[2800530260,"כמו בח\"י ברכאן דצלותא יכוין למקור התהוות הכלי שהוא עיקר בחי' השם דאיהו וגרמוהי חד כו' וממילא נמשך האור אחר הכלי כי דרכו של איש<sup data-n=\"3021\">11</sup> כו' וד\"ל). והנה יש ג' מדריגות בכלים<sup data-n=\"3022\">12</sup> פנימים ואמצעים וחיצוניות. והענין ידוע כי לנגד ט\"ס חב\"ד חג\"ת נה\"י יש ג' מיני כלים פנימי' הכלי' הוא בחי' הגבלת האור דחב\"ד שבאור ואמצעות הכלי' הגבלת חג\"ת דאור וחיצוניות הכלי' הוא הגבלת נה\"י דאור כו' והיינו אתה סתר למפרע דרת\"ס<sup data-n=\"3023\">13</sup> שעיקר ההגבלה וההסתר בחיצוניות הכלי' כו' וגם בענין מה שיש בכלי בחי' השפעת וירידת השפע למקבל דוקא כנ\"ל ג\"כ כלול מג' מדריגות פנימית הכלי הוא בחי' הבאת אור שפע דחב\"ד ואמצעית להבאת והמשכת אור דחג\"ת וחיצוניות להבאת שפע דנה\"י כו' ועד\"מ ט\"ס שבאור מדת החסד המוגבל בג' מיני אותיות אותיות המח' בחי' פנימית הכלי לחב\"ד שבחסד ואותיות הדבור אמצעי' כלי לחג\"ת שבחסד ואותיות המעשה לבחי' נה\"י שבאור החסד שהוא בחי' כח המעשה שבחסד לעשותו בפו\"מ יש לו כלי מיוחד ואהבה שבחסד יש לו כלי מיוחד ושכל וטעם שבחסד יש לו כלי מיוחד כו' ועל הרוב השכל והטעם שבחסד מהרהר במח' והאהבה שבו יאמר בדיבור וכח המעשה שבו יעשה בפו\"מ (אמנם כשבא בג' מיני אותיות דמחדו\"מ נק' לבושין דמנהון כו' שלמטה מבחי' כלים דעליהם אמר איהו וגרמוהי חד כו' ולא על הלבושין אבל בחי' הכלי' לנר\"נ הוא מוחא ולבא כו' ובלב יש ג' מדריגות פנימי' ואמצעים וחיצוניות לנגד ט\"ס כו' בחי' חב\"ד שבמדת האהבה או היראה כו' שנק' מושכל של המדות כו' הוא בחלל הימיני שבלב שמאיר בו ממוח החכ' ששליט על הלב כו' וחג\"ת שבאהוי\"ר כו' שהוא הנק' מורגש היינו בבחי' אמצעית כלי הלב שהוא רוח החיים שדופק בחלל השמאלי שנמשך ממוח בינה שנק' רוח והוא בחי' כלי הרגש החיות של המדות בהתפעלותם כו' וחיצוניות הלב הוא הבל החזה כו' ששם כלי הטבע' המדות כו' שהוא לנגד בחי' נפש בחי' נה\"י שבמדות כו' ומשם מאיר בנפש שבדם שהוא מרכבה לגבי רוח שבלב בכלל וגם בחי' נפש שבכבדא כלול מג' מדריגות פנימי ואמצעי וחיצון כו'. פנימי הוא הנק' בזוהר קיסטא דחיותא<sup data-n=\"3024\">14</sup> דהיינו בחי' רשימו שנשאר מבחי' רוח בשעת השינה כו' והוא בחי' מוחין חב\"ד דקטנות שבנפש כו' ואמצעי היינו התפעלות חיות גשמי של כח התנועה וההרגש שבדם הוא הנפש כמו בדפק שביד כו' והחיצון הוא בחי' נה\"י שבכבד ששולח חיצוניות החיות בכל האברים והפנימי' מבדיל כו' כמ\"ש במ\"א באריכות שבזמן הגלות שנק' שינה<sup data-n=\"3025\">15</sup> אין ההארה דמל' דאצי'<sup data-n=\"3026\">16</sup> בחי' נפש בעולמות דבי\"ע רק בחי' קיסטא דחיותא רשימו דבחי' רוח שבלב אדם העליון כו' וכנ\"י שנמשלים לבחי' עיבור בגלות<sup data-n=\"3027\">17</sup> היינו כמו הולד שמקופל ראשו בין ברכיו כו' תלת גו תלת<sup data-n=\"3028\">18</sup> כו' שהמוחין חב\"ד בהעלם בחג\"ת וחג\"ת בנה\"י כו' וכמ\"ש במ\"א). והנה בענין המצות שנק' רמ\"ח אברין דמלכא<sup data-n=\"3029\">19</sup> כידוע הרי ג\"פ טפ\"ט בג' מיני מדריגות דרת\"ס שבכלי' כנ\"ל עולה רמ\"ג וה\"ח המגדילים הן רמ\"ח<sup data-n=\"3030\">20</sup> כו' ובחי' חב\"ד היינו אור הכוונה שבמצוה שיש לזה כלי פנימי' מיוחד ובהגבלה כו' ובחי' חג\"ת אוי\"ר וביטול כו' יש לזה כלי אמצעי כו' ובחי' נה\"י בחי' כח המעשה לעשות רצון המלך בלבד כו' יש לזה כלי החיצוני (ובכלל היינו כונה וברכה ומעשה<sup data-n=\"3031\">21</sup> או יחוד ברכה וקדושה שנק' יב\"ק<sup data-n=\"3032\">22</sup> כו' שהוא ענין בשר וגידין ועצמות<sup data-n=\"3033\">23</sup> שבכל אבר כמ\"ש במ\"א באריכות) וה\"ח המגדילים כו' היינו בחי' כללות",[["3021","11","<b>דרכו של איש</b>: קידושין ב, ב."],["3022","12","<b>ג' מדריגות הכלים</b>: ראה לקו\"ת שלח מא, ד."],["3023","13","<b>אתה סתר למפרע דרת\"ס</b>: תהלים לב, ז. ראה עמה\"מ שי\"ב פ\"ד (סט, א). מאמרי אדה\"א דברים ח\"ג ס\"ע תשצב. וש\"נ. שע\"ת צט, ד ובהנסמן במ\"מ לשם."],["3024","14","<b>קיסטא דחיותא</b>: זהר לך פג, א. לקו\"ת אמור לא, ב ובהנסמן במ\"מ לשם."],["3025","15","<b>שבזמן הגלות שנק' שינה</b>: ראה תו\"א ר\"פ וארא. מאמרי אדה\"א הנחות תקע\"ז ע' קפט. וש\"נ [ושם צ\"ל: ?לקמן ע' רמד\"]."],["3026","16","<b>אין ההארה דמל' דאצי'</b>: ראה ביאוה\"ז בלק קה, ב."],["3027","17","<b>וכנ\"י. . עיבור בגלות</b>: ראה תו\"א ר\"פ וארא. מאמרי אדה\"א קונטרסים ע' רכג. וש\"נ. תו\"ח מקץ רטו, ג."],["3028","18","<b>תלת גו תלת</b>: ראה זהר (תוספתא) בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ג. ביאוה\"ז בשלח מז, ג ואילך. בלק קג, ד. מאמרי אדה\"א קונטרסים ע' תלה. לקמן קלג, א."],["3029","19","<b>רמ\"ח אברין דמלכא</b>: נסמן לעיל ד, ב."],["3030","20","<b>ג\"פ טפ\"ט. . רמ\"ח</b>: ראה גם לעיל קכט, רע\"א ובהנסמן במ\"מ לשם."],["3031","21","<b>כונה וברכה ומעשה</b>: ראה שע\"ת ח\"א מב, ב. מאמרי אדה\"א דברים ח\"ג ע' תתקכז ואילך."],["3032","22","<b>יב\"ק</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תיג ואילך. דברים ח\"ד ס\"ע א'תקטז ואילך. הנסמן בתו\"ח תולדות קסב, ג הערה 43."],["3033","23","<b>בשר גידין ועצמות</b>: ראה גם ד\"ה זה במאמרי אדה\"א דברים ח\"ג ע' תתקטו."]]],[2800530261,"המשכת גלוי אור אלקי שע\"י כל מצוה ע\"י המשכת הקו שממשיך למקור<sup data-n=\"3034\">1</sup> כל החסדים דאיהו שקיו דאילנא<sup data-n=\"3035\">2</sup> כו' וכמאמר אנת ממלא כל שמהן<sup data-n=\"3036\">3</sup> כו' (ולפ\"ז מ\"ש אשתאר כגופא כו' משום דגם בחי' גופא בג' כלים הנ\"ל צריך להארת אא\"ס שבקו שממלא כל שמהן לפי שיש שרש להתהוות הכלים בפ\"ע כנ\"ל. אך א\"כ למה תלה הדבר במה שאינו עיקר הדבר שהוא מ\"ש בלא נשמתא אך להיות שעיקר הכלים הן לנגד ט\"ס דנר\"נ ובסיבת הגדלת האור יבא הגדלת הכלי בשביל הבאת אור השפע למטה ואי אנת תסתלק כו' ישאר הכלי כגוף בלא נשמה בלא התפשטות כלל וד\"ל):\n(לא) <b>והנה</b> יש יתרון מעלה בבחי' הכלים מבחי' האורות ממה שיש בחי' ההתכללות בכלים יותר מבאורו' שזהו עיקר בחי' התיקון כידוע דעיקר בחי' התיקון הוא בא מריבוי הכלים<sup data-n=\"3037\">4</sup> כו' ודוקא ע\"י בחי' חיצוניות הכלי שהוא בחי' נה\"י כו' וראיה לזה ממה שמצינו בכמה מקומות דאור החסד יוכל להאיר בכלי הגבו' ואור הגבו'<sup data-n=\"3038\">5</sup> בכלי החסד וא\"כ מה שיחליף האור להאיר בכלי היפוכו אם היה זה מצד עצמו למה לא יוכלל ויחובר באור היפוכו המנגדו כמו אור מדת החסד שלא יסבול אור מה\"ד כלל וכלל אלא מוכרח לומר שזהו מצד בחי' הכלי שיכול לסבול אור היפוכה המנגדה כי יש בכלים דוקא בחי' וענין ההתכללות מדבר והיפוכו משא\"כ באורות כו' וזהו עיקר התיקון בבחי' האדם מצד גופו כמו שאנו רואים בחוש טבעי אברי האדם שכ\"א יש בו התכללו' מזולתו<sup data-n=\"3039\">6</sup> עד שיכולים להשלים חסרון א' ע\"י רפואת אבר זולתו כמו לקלקול הראות בעין ירפאו לכח הגידין שברגל שיש בהן בהתכללו' מגידין שבעין אבל לא ירפאו לאור וחיות שנחלש במוח עד שנחלש בראות מצד הזקנה וכה\"ג ע\"י חיזוק כח ואור חיות המדות שבלב אע\"פ שהמוח ולב כלולים זע\"ז רק מצד חיזוק כלי הלב יחזקו לכלי המוח ויאיר כח השכל בראות יותר כו' מפני שאין לאור השכל עם אור המדות חיבור והתכללות כ\"כ כמו שיש חיבור והתכללות של כלי הלב עם כלי המוח וכן כלי העין עם כלי החוטם וכלי האוזן וכה\"ג ולזה הטעם הנה דוקא מצד בחי' הכלי יוכל להאיר בה אור המנגדה כו' וד\"ל. ויובן זה יותר במה שאנו רואים במדות חו\"ג שהן הפכיי' מנגדיים ממש כו' אך כאשר באין המדות בכלי כמו למח' ולדו\"מ בפו\"מ יוכל אור החסד להאיר במחשבה ודוב\"מ היפוכו ממש שהרי יכול לחשוב ולדבר ולעשות נגד מה שבלבו וגם לכעוס בלב על אוהבו בלבו ולרחם בלבו על שונאו כו' שהלב מוכן להיות כלי למה שהוא היפוכו כו' לפי שבכלים יש התכללות דבר והפוכו יותר מבאורות (דמה שבגילה יש רעדה וברוגז יש רחמי' וכן להיפך ברעדה גילה וברחמים רוגז הכל מצד הכלי דוקא כו') וכך אנו מוצאי' בו' ימי המעשה שביום א' הוא בחי' חסד יהי אור וביום הב' בחי' גבורה<sup data-n=\"3040\">7</sup> יהי רקיע<sup data-n=\"3041\">8</sup> כו' וכמ\"ש בזהר דכל יומא בעבידתי'<sup data-n=\"3042\">9</sup> כו' ועכ\"ז בכל יום יש התכללות מיום זולתו דוקא כידוע לפי שכאשר בא האור בכלי שנק' יום אז יש התכללות דבר והיפוכו דוקא להיות שכאשר בא הדבר לידי השפעה בפ\"מ א\"א שלא יוכלל בחסד מבחי' הדין ובדין מבחי' החסד משא\"כ כשהאור והשפע עדיין בלא כלי כו' כמו פסק דין למעש' דוקא שבהכרח יוכלל חסד בדין ודין בחסד משא\"כ כשאינו למעשה כו' ונמצא שמצד בחי' חיצוניות הכלי שהוא למעשה שם הוא עיקר בחי' ההתכללות כו' וד\"ל:\nאך הנה לכאורה יש סתירה לכ\"ז שהרי באמת",[["3034","1","<b>למקור</b>: אג: ממקור."],["3035","2","<b>דאיהו שקיו דאילנא</b>: ת\"ז בהקדמה (יז, א)."],["3036","3","<b>אנת ממלא כל שמהן</b>: ראה ת\"ז שם (יז, ב)."],["3037","4","<b>התיקון. . מריבוי הכלים</b>: ראה ע\"ח (שער התיקון) ש\"י פ\"ה. תו\"א נח ט, ג ואילך. מאמרי אדה\"ז תקס\"ה ח\"א ע' א ואילך. פרשיות התורה ח\"א ע' סט ואילך."],["3038","5","<b>דאור החסד. . ואור הגבו'</b>: ראה לעיל עג, ב בשם הע\"ח. (ובהמובא בסמוך מציינים לע\"ח: בשער מטי ולא מטי). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. ע' תשכג. ענינים ע' סב ובהנסמן במ\"מ לשם."],["3039","6","<b>אברי האדם. . התכללו' מזולתו</b>: ראה סידור שער נפ\"א צא, סע\"ג ואילך. מאמרי אדה\"א קונטרסים ע' תז. וש\"'נ."],["3040","7","<b>שביום א'. . חסד. . הב' בחי' גבורה</b>: ראה שעהיוה\"א פ\"י (פז, ב)."],["3041","8","<b>יהי אור. . יהי רקיע</b>: בראשית א, ג. ו."],["3042","9","<b>דכל יומא בעבידתי'</b>: ראה זהר ויגש רה, סע\"א. אמור צד, ב. השמטות לזח\"א רסד, ב."]]],[2800530262,"מה שהאור יוכל להאיר בכלי היפוכו הוא מצד בחי' הביטול של הכלי לגבי האור והוא ע\"י בחי' שם מ\"ה מלגאו<sup data-n=\"3043\">10</sup> שרש בחי' ההתכללות באורות דוקא מצד הארת הקו כו' ולזה הטעם דוקא בפנימיו' הכלים יש התכללות (וכמו הכונה שבמעשה המצות שמתכלל ב' הפכים כו' והיינו כמו עצמות וגידים כו' משא\"כ גוף המעש') ולא בחיצוניו' שהרי אין מלאך א' עושה ב' שליחות<sup data-n=\"3044\">11</sup> הפכים מפני שכל שליחות השפע בא מחיצוניות הכלי' דוקא שמביא השפע לחוץ כמו חיצוניות הכלי דאותיות וכה\"ג ולכך פני אריה להימין<sup data-n=\"3045\">12</sup> כו' לא ישנו את תפקידם ולא יתחברו להחליף מעשיהם מזה לזה כו' ולכך כל יומא בעבידתי' דווקא כו'. אך הענין הוא משום דפנימית הכלי הוא מקבל מבחי' או\"פ המוגבל בכלי וכאשר יש התכללות באורות ממילא יש התכללות בפנימית הכלים כמו התפעלו' והשגות מיכאל וגבריאל כו' וחיצוניו' הכלים מבחי' הכח המגביל שבבחי' מקיף ע\"כ יש בו ב' הפכים כא' בחי' התכללו' דבר והיפוכו דוקא כמו כל הנסים שהם דוקא בבחי' חיצוניו' הכלי' בפו\"מ כמו כ\"מ<sup data-n=\"3046\">13</sup> שנעשה בו הנס שהמקום הזה סובל דבר והיפוכו<sup data-n=\"3047\">14</sup> מלמעל' מן הטבע בטבע כו' כהפיכת ים ליבשה כו' וכה\"ג מקום ארון אינו מן המדה<sup data-n=\"3048\">15</sup> וכו' וכמ\"ש במ\"א וגם משם הוא בא שרש בחי' ההתחלקו' כ\"א מובדל בפ\"ע שהוא בא מצד בחי' קו המדה שבמקיף שהוא שרש הכלי' המגבילי' כו' ולזה עיקר בחי' התיקון הוא בחי' ריבוי ההתחלקות דוקא שבזה דוקא יהיה ריבוי ההתכללות דבר והיפוכו כא' וזהו עיקר בחי' אדם דתיקון כו' שעליו אמר אחור וקדם צרתני<sup data-n=\"3049\">16</sup> יצירה בגוף חומר דוקא כו' קדם בבחי' החומר הפשוט שקדם לצור' שהוא האור והוא בשרש הכלי' שקדם לאור ואחור בכלי החומ' שאחר האור והצורה כו' וד\"ל<sup data-n=\"3050\">17</sup> וכמ\"ש<sup data-n=\"3051\">18</sup> במ\"א ביאור ענין זה באריכו' (וד\"ל)<sup data-n=\"3052\">19</sup> :\n(לב) <b>ומעתה</b> יש להבין בבחי' אדם העליון דאצי' שעל הכסא<sup data-n=\"3053\">20</sup> כו' שהוא בחי' ז\"א<sup data-n=\"3054\">21</sup> דאצי' שמקבל מבחי' נה\"י דאו\"א<sup data-n=\"3055\">22</sup> כו' וידוע שהוא ענין ובחי' המדות דאצי' שהוא עיקר ושרש להשפעת מקור למקור לחיי העולמו' ועדיין הוא סוף עולם הא\"ס משום דאיהו וחיוהי וגרמוהי חד כנ\"ל ע\"כ גם עד בחי' כלים דז\"א בבחי' חיצוניות דנה\"י שבו כו' נחשב עדיין מסוף עולם הא\"ס<sup data-n=\"3056\">23</sup> :\n<b>וביאור</b> הדברים הנה מבשרי אחזה<sup data-n=\"3057\">24</sup> כו' דבצלם אלקים עשה את האד'<sup data-n=\"3058\">25</sup> כו' וכמ\"ש בצלמינו כדמותינו<sup data-n=\"3059\">26</sup> כו' דהנה אנו רואי' בנפש האדם שבחי' חיה יחידה שבו הוא בחי' מקיפי' דנר\"ן שלמעלה מהגבלת האורות בכלים<sup data-n=\"3060\">27</sup> והוא בחי' הרצון והתענוג העצמי הפשוט שבבחי' יחידה וגם בחי' פנימית ומקור השכל שנק' משכיל שזהו בחי' מקיף דחיה בלתי מוגבלים בכלי כלל רק מהחכמ' ולמטה נמשך בכלי והוא הנשמה שבמוחא ורוח בלב כו' והנה עכ\"ז מאיר אור המקיף דרצון ותענוג מבחי' פנימית אור החכמ' בנר\"ן שבג' כלים מוחא ולבא כו' מן ההעלם והוא גלוי הרצון שבא בשכל וטעם גלוי בבחי' מוח החכמה שנק' אור אבא ומשם נמשך ומתפשט בבינה שהוא ההשגה ומבינה שבמוח נמשך התפעלות המדות בלב דהיינו מל\"ב חדרים שבמוח<sup data-n=\"3061\">28</sup> שנק' ל\"ב שבילין דבינה דמתפתחין להיות מוחין לז\"א<sup data-n=\"3062\">29</sup> כו' כי המוחין נחלקים לד' חו\"ב וחו\"ג<sup data-n=\"3063\">30</sup> וכ\"א יש בו ח' חדרי' שהוא ל\"ב והיינו הטע' שנק' לב<sup data-n=\"3064\">31</sup> מפני ששרשו בל\"ב שבילין הן ל\"ב חדרים שע\"י דעת שכולל חו\"ג<sup data-n=\"3065\">32</sup> מטה אור השכל דחו\"ב להתפעלות לחו\"ג כלפי זכות או כלפי חוב ונק' ג\"כ מדות שבשכל שהן בחי' ז\"ת דבינה<sup data-n=\"3066\">33</sup> וכ\"א כלול מז' שהן נש\"ב<sup data-n=\"3067\">34</sup> והכל ענין א' רק שנש\"ב הוא",[["3043","10","<b>שם מ\"ה מלגאו</b>: נסמן לעיל כ, א."],["3044","11","<b>אין מלאך. . ב' שליחות</b>: ב\"ר פ\"נ, ב. ראה גם לעיל נג, א. ביאוה\"ז נח ו, א [נדפס גם בסה\"מ תקס\"ח ח\"א ע' תעה]. בלק צט, א. לקו\"ת אמור לז, ג. חוקת סב, ד. שה\"ש מ, א. מאמרי אדה\"ז תקס\"ו ע' רעג. תקס\"ח ח\"ב ס\"ע תרטז ואילך. פרשיות התורה ח\"ב ע' תרלב. מאמרי אדה\"א במדבר ח\"ג ע' א'לב. וע' א'קנד. דרושי חתונה ח\"ב ע' תעד."],["3045","12","<b>פני ארי' להימין</b>: יחזקאל א, י."],["3046","13","<b>כ\"מ</b>: ג: כל מקום."],["3047","14","<b>שהמקום. . דבר והיפוכו</b>: ראה גם שע\"ת ח\"א יד, ג ואילך ובהנסמן במ\"מ לשם."],["3048","15","<b>מקום ארון אינו מן המדה</b>: יומא כא, ב. ראה סה\"מ תקס\"ג ח\"א ע' שז (נוסחא שני'). הנסמן בתו\"ח נח סה, ג הערה 38."],["3049","16","<b>אחור וקדם צרתני</b>: תהלים קלט, ה."],["3050","17","<b>וד\"ל</b>: אגיאיביג: ליתא."],["3051","18","<b>וכמ\"ש</b>: גזיאיג: (וכמ\"ש."],["3052","19","<b>(וד\"ל)</b>: אגיג: וד\"ל. זיא: וד\"ל)."],["3053","20","<b>אדם. . שעל הכסא</b>: יחזקאל א, כו."],["3054","21","<b>אדם. . ז\"א</b>: ראה ע\"ח (שער רפ\"ח ניצוצין). שי\"ח פ\"ה."],["3055","22","<b>ז\"א. . נה\"י דאו\"א</b>: נסמן לעיל קכח, א."],["3056","23","<b>ז\"א. . מסוף עולם הא\"ס</b>: ראה סה\"מ תקס\"ה ח\"א ע' תקה ובהגהת הצ\"צ שם. מאמרי אדה\"א בראשית ע' רכח. וש\"נ. נ\"ך ע' תקפה. וש\"נ."],["3057","24","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו. ראה גם לעיל מב, א. מה, א ואילך. הנסמן במאמרי אדה\"א קונטרסים ע' רכח. הנחות תקע\"ז ע' כב. וש\"נ."],["3058","25","<b>דבצלם אלקים. . האד'</b>: נח ט, ו."],["3059","26","<b>בצלמינו כדמותינו</b>: בראשית א, כו."],["3060","27","<b>חיה יחידה. . שלמעלה. . בכלים</b>: נסמן לעיל קכח, ב."],["3061","28","<b>מל\"ב חדרים שבמוח</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'רמב."],["3062","29","<b>ל\"ב שבילין. . מוחין לז\"א</b>: ראה זהר (אד\"ר) נשא קכח, ב. קכט, א. קלו, א."],["3063","30","<b>המוחין. . חו\"ב וחו\"ג</b>: ראה זהר ואתחנן רסב, א. סידור שער התפילין ז, א. הנסמן בתו\"ח נח עח, ד בהערה 34."],["3064","31","<b>הטע' שנק' לב</b>: בסמוך (קלב, א) בשם הע\"ח. וש\"נ."],["3065","32","<b>דעת שכולל חו\"ג</b>: ראה ע\"ח (שער תיקון הנוקבא) של\"ד פ\"ג. מאמרי אדה\"א בראשית ע' ד. וש\"נ. הנחות תקע\"ז ע' ח. וש\"נ. לעיל פב, ב."],["3066","33","<b>ז\"ת דבינה</b>: נסמן לעיל קי, ב."],["3067","34","<b>נש\"ב</b>: ר\"ה כא, ב. ראה הקדמת פי' הראב\"ד לס\"י [ירושלים תשכ\"ב א, ד]. שיעור קומה להרמ\"ק סצ\"ב."]]],[2800530263,"עדיין בהשגה דבינה כמו חסדי' המכוסים תוך יסוד אימא<sup data-n=\"3068\">1</sup> כו' היינו בחי' התפעלות האהבה שבשכל והשגה עדיין שנק' מכוסה ונעלם בהשגה ואח\"כ יוצא לגילוי מהות התפעלות מדת אהבה שבלב שנק' ז\"א ועד\"ז יוצאים ל\"ב שבילין הנ\"ל בהתגלות מן התפעלות ההעלם שבמוח ללב וע\"כ נק' בשם לב כמ\"ש בע\"ח<sup data-n=\"3069\">2</sup> בטעם שנק' לב מפני שמתקבצי' שם ל\"ב אורו' דאו\"א שהן ל\"ב שבילין (והן ל\"ב ויאמר אלקי'<sup data-n=\"3070\">3</sup> דבינה שמקבל מאבא) וכמ\"ש במ\"א באריכות. והנה ודאי כאשר צ\"ל התהוות התפעלות המדה בלב מן העלם התפעלות המדה בהיותה בשכל והשגה דבינה הוצרך להיות תחלה בחי' צמצום והעלם וכיווץ שנק' הסתלקות (כמו משל רקבון הגרעין<sup data-n=\"3071\">4</sup> בשביל השתנות ממהות למהות וכידוע) והוא בחי' מיצר הגרון דבינה שנתעלם שם התפעלות השכל ונמשך להיות בשינוי המהות בהתפעלות הלב (וכמו בחי' קרומא כו'<sup data-n=\"3072\">5</sup> שהוא המעלים ומפסיק מכח עליון שלמעל' מן השכל לבוא לשינוי המהות בגלוי אור השכלה כו' וכמו חצר הכבד שמפסיק<sup data-n=\"3073\">6</sup> ומבדיל בין אברי הנשימה לאברי המזון להיות שינוי המהות וכמ\"ש במ\"א באריכות) אך עכ\"ז המדות שבלב הן בדומה ממש אל המדו' שבשכל ממש כאופני התפעלותם במוח בלי נטי' כקש\"י כידוע רק שבלב באין בשינוי המהות ובהגבלה וצמצום דבחי' נו\"ה דבינה שהוא שליחות שפע אור ההשגה בעצם בשביל התפעלות המדה לבד כידוע ובמדות שבלב כלול מג' מדריגות חב\"ד חג\"ת נה\"י דהיינו בחי' המושכל ומורגש ומוטבע<sup data-n=\"3074\">7</sup> הנ\"ל וג' כלים לכ\"א פנימי' ואמצעי' וחיצוניות כנ\"ל באריכות אך הנה גם בחי' החיצוניות דכלים דנה\"י שבלב שהוא בחי' התפעלות החסד והאהבה שבלב כשבאה לידי השפעה לחוץ שנק' נה\"י דחזה במחדו\"מ היינו ע\"י חיצוניות הכלי דלב שהוא בחי' המוטבע אשר בהבל החזה דז\"א דאצי' שעז\"א איהו וגרמוהי חד הכל עדיין בבחי' א\"ס וכמו עד\"מ באדם התחתון כאשר הרצון העצמי שבבחי' מקיף דיחיד' הנ\"ל מאיר ובא בגלוי במוחין דחו\"ב עד שיורד ומתצמצם בקטנו' המוחין דכלי דנו\"ה דחסד מורגש שבלב שהוא בהבל החזה הרי גם שם הרצון מאיר כי אנו רואי' שבהבל הלב ג\"כ מורגש הרצון ונק' רעותא דלבא<sup data-n=\"3075\">8</sup> מה שלבו חפץ במורגש לדבר טוב ולמאוס בהעדר הרצון בלב לדבר רע השנאוי כו' א\"כ מתאחד ומתקשר ממקור הרצון העצמי עד הבל הלב ברגע א' כאילו הוא מהות א' ממש והיינו דמיון להבין באדם העליון שהוא בחי' ז\"א שבבחי' לב דז\"א נאמר ויאמר אל לבו<sup data-n=\"3076\">9</sup> להטות לחסד וכן ויתעצב אל לבו<sup data-n=\"3077\">10</sup> לבחי' דין וכה\"ג הרי בבחי' חיצוניות הכלי דנו\"ה דלב זה מאיר שם מבחי' הרצון הפשוט העצמי שבעצמות אא\"ס שלפני הצמצום הראשון (הנז' באות יו\"ד בבחי' יחיד ואחד כו' במשל חפץ חסד העצמי בעצמות הנפש כו') וא\"כ עד בחי' חיצוניות הלב דז\"א נחשב עדיין הכל מסוף עולם הא\"ס משום דאיהו וגרמוהי חד כמו באדם שלבו ורצונו העצמי אחד הוא כו' וד\"ל:\n(לג) <b>ובכל</b> זה יובן ענין ההתבוננות אחת מן רבוי כל הפרטים אל כלל א' הכוללם יחד והוא כמו כל אשר חפץ ה' עשה בשמים ובארץ<sup data-n=\"3078\">11</sup> כו' שחפץ ה' זה הרי שרשו במקור הראשון (שנק' יחיד כו') הוא בחי' חפץ חסד ההיולי העצמי שבעצמו' אא\"ס הפשוט בתכלית כטבע הטוב והחסד העצמי הנטוע בעצם הנפש (כמ\"ש באות יו\"ד) וכאשר עלה רצון וחפץ ה' להטיב בדרך",[["3068","1","<b>החסדים המכוסים. . אימא</b>: ראה לקו\"ת במדבר ו, ד. וש\"נ."],["3069","2","<b>בשם לב כמ\"ש בע\"ח</b>: ראה שם (שער פרצופי זו\"ן) של\"א פ\"ד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקצד. שמות ח\"ב ע' תמב."],["3070","3","<b>ל\"ב ויאמר אלקי'</b>: נמנו בפרטיות בתז\"ח קיב, ג. ראה הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרכה. דברים ח\"ב ע' תרנא. דרושי חתונה ח\"א ע' מא. תו\"ח נח מו, ג ובהערה 30."],["3071","4","<b>רקבון הגרעין</b>: ראה אגה\"ק ס\"ח (קיג, א). מאמרי אדה\"א ויקרא ח\"ב ע' תקצח. וש\"נ. הנסמן במ\"מ לשע\"ת ח\"א סג, ב."],["3072","5","<b>קרומא כו'</b>: ראה סה\"מ תקס\"ב ח\"א ע' רנג. ח\"ב ס\"ע תקכא ואילך. הנסמן לעיל קכה, א."],["3073","6","<b>חצר הכבוד שמפסיק</b>: ראה סה\"מ שם ע' רמה. ח\"ב ע' תקטז. אמ\"ב שער הק\"ש טו, ד."],["3074","7","<b>המושכל ומורגש ומוטבע</b>: ראה פי' הראב\"ד והרמב\"ן לס\"י פ\"א מ\"ה. מאמרי אדה\"א נ\"ך ע' קיא. וש\"נ."],["3075","8","<b>רעותא דלבא</b>: זהר וירא ק, א."],["3076","9","<b>ויאמר אל לבו</b>: נח ח, כא [בדילוג]."],["3077","10","<b>ויתעצב אל לבו</b>: בראשית ו, ו."],["3078","11","<b>כל אשר חפץ. . ובארץ</b>: תהלים קלה, ו. ראה גם לעיל נז, ב."]]],[2800530264,"פרט מכללות אור ההיולי הזה ירד ברבוי השתלשלות בעצמותו עדיין בבחי' א\"ס עד שבא זה הרצון לבחי' נו\"ה בחיצוניות כלי הלב דהיינו חיצוניות מדו' שבמל' דא\"ס הגם ששם למעלה מעלה מבחי' הגבלת אורו' בכלי' כו' אלא הכל בבחי' א\"ס ממש כששיער בעצמו<sup data-n=\"3079\">12</sup> כו' ואח\"כ נתצמצם וירד ע\"י בחי' קו בע\"ס דעגולים כו' עד בחי' כתר דא\"ק שהוא מקור הרצון הנעלם שבא לידי גלוי רצון לרצון בכתר דע\"י כו' עד בחי' רצון ותענוג שבאו\"א שמתצמצמי' ברצון ושכל והשגה ג\"ר דחו\"ב כו' עד בחי' מדות ז\"ת דבינה עד בחי' קטנות מוחין דנה\"י דאו\"א בז\"א כנ\"ל ומשם מתצמצם עוד בג' מדריגות דחב\"ד חג\"ת דז\"א כו' עד בחי' חיצוניות הכלי' דנו\"ה שבבחי' הבל החזה כו' שם מסתיים אור הרצון הפשוט שהיה כלול בהעלם עצמו' חפץ חסד ההיולי כו' והרי מכל רבוי פרטי ההשתלשלות הזאת נעשה ונמשך בבת א' מרצון שעלה בהעלם העצמות עד שבא במורגש בהבל הלב משום דאיהו וחיוהי וגרמוהי חד פי' איהו בחי' עצמו' אא\"ס ממש וחיוהי בחי' ע\"ס דהעלם וגלוי כשלהבת כו'<sup data-n=\"3080\">13</sup> עד ע\"ס דז\"א כו' וגרמוהי בחי' הכלים דז\"א חד הכל בבחי' א\"ס עדיין כי גם שבחי' הכלים המגבילים למדות חיצוניות דלב דז\"א הן בתכלי' הקטנות לגבי ערך רוממות עצמות המדות שבבחי' מל' דא\"ס מ\"מ נחשב בחי' סוף לראש וכמ\"ש קורא הדורות מראש<sup data-n=\"3081\">14</sup> כו' וסיומן בסוף הוא בבחי' קטנות המדות דז\"א ולכך נק' ז\"א קטנות הפנים כאנפי זוטרי דתינוק קטן לגבי בחי' אנפי רברבי<sup data-n=\"3082\">15</sup> זקן שקנה חכמה<sup data-n=\"3083\">16</sup> כו' שזה תכלית הקטנות במוחין וזה תכלית הגדלות מ\"מ משתווי' בערך אדם רק שזה נק' אדם קטן וזה נק' אדם הגדול כו' אבל ציור אופניו א' הוא כי בקטן מדותיו ג\"כ ע\"פ שכל ורצון הנעלם כו' רק שבא בתכלי' הקטנות מאד ובאדם הגדול מדותיו גדולי' עפ\"י רוחב שכלו ורצונו הרמה ונשגבה ביותר כו' כך ערך קטנות המדות דז\"א שהם המדו' שמצומצמין בקטנו' השכל דנו\"ה כו' לגבי בחי' א\"א שנק' אנפי רברבי גדלות הפנים והמוחין דזקן שקנה חכמה ממקור החכמה הנעלמה שלמעלה מקרומא כו' שהוא בחי' שכל הנעלם שברצון הנעלם כו' שהוא שרש הנאצלים כו' וכן גם המדות שברצון ושכל הנעלם דא\"א הוא בבחי' קטנות הערך לגבי בחי' אדם הגדול יותר והוא בחי' א\"ק שנק' אדם דבריאה כו'<sup data-n=\"3084\">18</sup> (וכידוע דז\"א נק' אדם דעשיה וא\"א נקרא אדם דיציר'<sup data-n=\"3085\">17</sup> וא\"ק אדם דבריאה ובכ\"א יש ע\"ס בהעלם וגלוי כו' וכמ\"ש לכבודי שהוא מל' דא\"ס בראתיו<sup data-n=\"3086\">19</sup> א\"ק יצרתיו ע\"י וא\"א אף עשיתיו בחי' ז\"א שנאמ' בו נעשה אדם בצלמינו<sup data-n=\"3087\">20</sup> כו') והוא עד\"מ ציור קוין שעושין בקטנות לדבר גדול כמו דמיון המפה לכדור הארץ כו' שעכ\"ז יש בציור זה הכל לא נעדר אפי' כקש\"י כו' רק שהוא בקטנות מאד ומה שמצוייר בו קו קטן בכדור הארץ הוא אורך נהר ת\"ק פרסא<sup data-n=\"3088\">21</sup> וכה\"ג כו' וכך עד\"מ המדות דקטנות דתינוק לגבי מדות דזקן בן ע' כו' וכמו כח המוליד בדומה לו כו' (וכמ\"ש במ\"א בענין בוצין בוצין<sup data-n=\"3089\">22</sup> כו') וכך הוא בחי' המדות דאדם דאצי' דגם שבאים בצמצום היותר אחרון לגבי בחי' המדות דא\"ק וא\"א כו' אבל מ\"מ הכל א' רק שבא מן בחי' האריכות היותר מופלג אל הקיצו' היותר מופלג (וז\"ש מה שמו מה שם בנו<sup data-n=\"3090\">23</sup> מה שמו מ\"ה דא\"ק מה שם בנו בחי' ז\"א כו' וכמ\"ש בכמה דוכתי) והיינו כללות ההתבוננו' בכל אשר חפץ ה' בעצמות אא\"ס ממש עשה בשמים שהוא בחי' ז\"א<sup data-n=\"3091\">24</sup> אש ומים<sup data-n=\"3092\">25</sup> חו\"ג<sup data-n=\"3093\">26</sup> דקטנות דאצי' כו' (עד בחי' שמים",[["3079","12","<b>כששיער בעצמו</b>: נסמן לעיל קטז, ב."],["3080","13","<b>כשלהבת כו'</b>: ס\"י פ\"א מ\"ז."],["3081","14","<b>קורא הדורות מראש</b>: ישעי' מא, ד. וראה לעיל קכג, ריש ע\"ב."],["3082","15","<b>כאנפי זוטרי. . אנפי רברבי</b>: ראה חגיגה יג, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקא. קונטרסים ע' שמג."],["3083","16","<b>זקן שקנה חכמה</b>: תו\"כ קדושים יט, לב. קידושין לב, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשמ."],["3084","18","<b>כו'</b>: גזיא: ניתוסף: (כמ\"ש באות) והניחו מקום פנוי ? ראה לעיל אות יז. יג: ניתוסף: כמשי\"ת."],["3085","17","<b>א\"ק שנק' אדם דבריאה. . דיציר'</b>: נסמן לעיל קכב, ב."],["3086","19","<b>לכבודי. . בראתיו</b>: ישעי' מג, ז [ושם: ולכבודי ? ראה לקמן קמה, ב. הנסמן בשע\"ת קו, ד]."],["3087","20","<b>נעשה אדם בצלמינו</b>: בראשית א, כו."],["3088","21","<b>נהר ת\"ק פרסא</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' רט."],["3089","22","<b>בוצין בוצין</b>: ברכות מח, א. ראה גם סידור ערב שבת קסד, ד. מאמרי אדה\"א קונטרסים ע' רז."],["3090","23","<b>מה שמו מה שם בנו</b>: משלי ל, ד [ושם: ומה שם ? ראה לקמן קלג, א. לעיל צה, ב. קד, ב. הנסמן בתו\"ח ויצא קעה, ב הערה 25]."],["3091","24","<b>בשמים. . ז\"א</b>: ראה זהר בשלח סב, ב. (אד\"ז) האזינו רפח, א."],["3092","25","<b>בשמים. . אש ומים</b>: חגיגה יב, סע\"א."],["3093","26","<b>אש ומים חו\"ג</b>: ראה ס\"י פ\"א מי\"א? מי\"ב ובמפרשים שם. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תצח. דברים ח\"ד ע' א'שצב."]]],[2800530265,"דעשי') לפי שנעוץ תחלתן בסופן<sup data-n=\"3094\">1</sup> מחכמ' בראש דא\"ק עד חכמ' בסוף מדות דז\"א (וז\"ש ברוך ה' אלקי ישראל<sup data-n=\"3095\">2</sup> סבא בחי' א\"ק שנאמר בו בראתיו כו' וכן שמע ישראל<sup data-n=\"3096\">3</sup> כו' שהוא בי\"ע שבכללות) (ודרך פרט יותר הרי כל אשר חפץ ה' במדות דאצי' עשה בשמים וארץ דבי\"ע עד בחי' מזלות דגלגלים הגשמיים שרש השפעת דצח\"מ הגשמיים כמשי\"ת בעזר\"ה):\n(לד) <b>והנה</b> בבחי' ז\"א דאצי' יש ב' מדרי' הנק' ישראל ויעקב<sup data-n=\"3097\">4</sup> כידוע וביאור פרטי המדריגות שבזה. הנה תחלה יש להבין בטעם קריאת שם ישראל כי שרית עם אלקי'<sup data-n=\"3098\">5</sup> כו' והוא שם מ\"ה שמברר ושולט על שם ב\"ן<sup data-n=\"3099\">6</sup> כו' כי בחכמה אתברירו<sup data-n=\"3100\">7</sup> וכח הדכר לברר<sup data-n=\"3101\">8</sup> כו' האיש דרכו לכבוש<sup data-n=\"3102\">9</sup> כו' וביאור הדברי' הנה תחלה יש להבין ההפרש בין יש\"ס לישראל זוטא<sup data-n=\"3103\">10</sup> שבחי' המדות שבחכמה עצמה נק' יש\"ס<sup data-n=\"3104\">11</sup> ויש בזה ב' מדריגות הא' מדות שבאור אבא והב' מדות שבח\"ס<sup data-n=\"3105\">12</sup> והוא הנק' אדם קדמא' בל' הזהר וז\"ש מה שמו מה שם בנו כו' ובחי' המדו' שלמטה מן החכמה נק' ישראל זוט'<sup data-n=\"3106\">13</sup> כי הם בבחי' קטנו' לאחר שהן באין בבחי' הצמצום והעלם עיקר עצם השכל רק מה שהכלי חיצוניו' דנו\"ה דאבא ממשיך להוליד ולהמציא שכל לחסד ואהבה נק' חסד זוטא כו' (וכמשל טיפה במוח האב כו' כך נאמר מה שם בנו שהוא יש\"ז<sup data-n=\"3107\">14</sup> שנמשך לו מטיפת אבא כו' וכידוע) והנה מבחי' נה\"י דאבא נמשך בנה\"י דאימא שהוא בחי' השפעת והשפלת השגה וטעם למדת החסד כו' אך בחי' נה\"י דאימא מסתלקין בשעת תולד' גלוי התפעלות מדת האהבה וכה\"ג כנראה בחוש שמתקצר ומסתלק הטעם והשכל בשעת התפעלו' המדה (והוא ענין וראיתן על האבנים כו' שהירכים מצטננות בשעת לידה<sup data-n=\"3108\">15</sup> שנסתלקו נה\"י הראשונים ונמשכי' נה\"י חדשים כו' כמ\"ש במ\"א) ונק' בחי' בקיעת יסוד דאימא להוליד המדה ותחלה כלולה האהבה בהעלם מכוסה בשכל כעובר במעי אמו כו' אבל לאחר שנולדו המדות הרי הם כלולים מחסדי' דאבא וגבורו' דאימא בכללות ופרטו' שלהם הרי יש בזה ג' מדריגות בחי' מוחין דיניקה ובחי' מוחין דגדלות ראשון דאימא וגדלות שני דאבא כו' כידוע. וביאור הדברי' בהיות ידוע שהמדות הם בבחי' עיבור תלת גו תלת<sup data-n=\"3109\">16</sup> כו' דהיינו רק חיצוניות נה\"י ובהם כלול בהעלם חב\"ד וחג\"ת כו' והוא רק בחי' טבעיות המדות כו' וביניקה מתגדלים להיות בהכנה לקבל מוחין והוא כמו התינוק שמתגדלי' אבריו מיניקת חלב אמו כידוע עד שבהיותו בן ו' שנה יש במדותיו מוחין בצמצום אך בבחי' הטעם ושכל לנהוג בכל דרכיו ולא מדות טבעיות כבהמה לבד כו' עד היותו בן ט' שאז ראוי להוליד<sup data-n=\"3110\">17</sup> שאז הוא בחי' גדלות המוחין יותר דהיינו יותר מכפי המצטרך אל המדות לבד וגם יוכל להיות התחלת התהוות המדה רק מצד השכל והטעם וכשיחייב השכל להיפך יולד מדה הפכית עד שמדותיו רק ע\"פ השכל משא\"כ קודם לבן ט' אין בו מוחין רק לפי המדה שכבר מוטבע בו שיוכל להתחכם בזה שזה ימצא גם בחיות ובהמות התחכמות במדתם למצוא טרף ומזון רק שבאדם נק' חי שבמדבר כו' וד\"ל. ומבן ט' ואילך מוכן לגדלות שני דאבא דהיינו שיהיה התגברות השכל על המדות (וכמ\"ש במ\"א בענין כי מראש צורים<sup data-n=\"3111\">18</sup> כו' באריכות) ולכך ראוי להוליד להיות שאז כל מדה כלולה מט\"ס חב\"ד חג\"ת נה\"י שכאשר נגדלו המוחין דכל מדה בבחי' חב\"ד אז ממילא יש כח בבחי' נה\"י להוליד ולד כי הא בהא תליא (כמ\"ש",[["3094","1","<b>שנעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א מ\"ז."],["3095","2","<b>ברוך ה' אלקי ישראל</b>: שמואל-א כה, לב. מלכים-א א, מח. ח, טו. ועוד."],["3096","3","<b>שמע ישראל</b>: ואתחנן ו, ד."],["3097","4","<b>ז\"א. . ישראל ויעקב</b>: ראה ע\"ח (שער הקליפות) שמ\"ח פ\"ב. פ\"ג. הנסמן במ\"מ לשע\"ת קטו, א."],["3098","5","<b>כי שרית עם אלקי'</b>: וישלח לב, כט."],["3099","6","<b>מ\"ה שמברר. . ב\"ן</b>: ראה ע\"ח (שער טנת\"א) ש\"ה פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["3100","7","<b>בחכמה אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה? שמות ח\"ב ע' שכא."],["3101","8","<b>וכח הדכר לברר</b>: ראה פע\"ח (שער התפלה) ש\"א פ\"ז. הנסמן במאמרי אדה\"א קונטרסים ע' תקמג. שע\"ת ח\"א מח, ג ובהנסמן במ\"מ לשם."],["3102","9","<b>האיש דרכו לכבוש</b>: יבמות סה, ב."],["3103","10","<b>יש\"ס לישראל זוטא</b>: ראה זהר ויקהל רטז, א."],["3104","11","<b>המדות שבחכמה. . יש\"ס</b>: נסמן לעיל קי, ב."],["3105","12","<b>יש\"ס. . מדות שבח\"ס</b>: ראה גם לעיל קכח, ב (ובהנסמן לשם). מאמרי אדה\"א דברים ח\"ד ע' א'שכב."],["3106","13","<b>המדו'. . ישראל זוט'</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שכב."],["3107","14","<b>יש\"ז</b>: ג: ישראל זוטא."],["3108","15","<b>וראיתן על האבנים. . לידה</b>: שמות א, טז. סוטה יא, ב. ע\"ח (שער המוחין) ש\"כ פ\"ג. מבו\"ש ש\"ה ח\"ב פ\"ב. ראה גם ביאוה\"ז בלק קה, סע\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ריש ע' תקיח. מאמרי אדה\"א דברים ח\"ב ע' שעח."],["3109","16","<b>תלת גו תלת</b>: נסמן לעיל קל, ב."],["3110","17","<b>בן ט' שאז ראוי להוליד</b>: ראה בסמוך בפנים. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסט ובהנסמן במ\"מ לשם. תו\"ח לך פג, א ובהערה 1. לעיל סד, ב."],["3111","18","<b>בענין כי מראש צורים</b>: ביאוה\"ז בלק קג, ד."]]],[2800530266,"למעלה באות כ\"ו באריכו') ובהיותו בן ו' הי' כל מדה כלול' מחג\"ת נה\"י לבד כו' שהמוחין מצומצמין מאד רק לפי צמצום הטבעיות של המדות כו' וגדלות שני היינו מבן י\"ג עד ך'<sup data-n=\"3112\">19</sup> שראוי למכור בנכסי אביו<sup data-n=\"3113\">20</sup> כו' שהוא בחי' כחב\"ד שבכל מדה כו' והוא בחי' הטיית הרצון בכל מדה מלמעלה מן השכל של המדה כו' עד בן ך' שהוא גדלות המוחין דמדו' בשלימות שיודע למכור בנכסי אביו במוחין דאבא שרש ומקור המדות לשנות מרשות לרשו' כו' כמו עד\"מ שינויי צירופי האותיות של השכל שבא מצד שרש ומקור של עומק השכל ממקורו העצמי דוקא (כמ\"ש שם<sup data-n=\"3114\">21</sup> במשל חכם מופלג כו') והיינו בחי' ישראל לי ראש<sup data-n=\"3115\">22</sup> ומוחין דהיינו בחי' כחב\"ד כו' שאז הוא בחי' גדלות המוחין ביותר שיוכל לברר לבחי' ב\"ן שהוא בחי' אלקי'<sup data-n=\"3116\">23</sup> כידוע משום דבחכמ' פנימית כח מ\"ה<sup data-n=\"3117\">24</sup> דוקא שמבחי' הכתר דחכמ' שבמדות כו' אתברירו כו' וכמשל חכם גדול ביותר שיודע העומק של השכל ממקור הראשון יודע יותר איך לברר וללבן להוציא הטעות כו' וכן חכמתו עמדה לו להתפרנס באומנו' או בריוח עבוד' כו' שנק' תורתו אומנתו<sup data-n=\"3118\">25</sup> כו' והיינו ענין האיש דרכו לכבוש כו' שהוא בחי' שם מ\"ה דחכמ' שמברר לב\"ן כו' וז\"ש כי שרית עם אלקים כו' וד\"ל:\n(לה) <b>וזהו</b> בחי' ישראל שר אל<sup data-n=\"3119\">26</sup> דהיינו ע\"י הארת הכתר בחכמ' שנק' אל נהירו דחכמתא<sup data-n=\"3120\">27</sup> שהכתר הוא המשתרר כו' כמ\"ש במ\"א בענין כי שרית<sup data-n=\"3121\">28</sup> וכו':\n<b>והנה</b> מעתה י\"ל ענין יחוד ישראל ולאה שהוא יחוד המדות במחשבה שנק' לאה<sup data-n=\"3122\">29</sup> ויחוד יעקב ורחל שהוא יחוד המדות בדבור<sup data-n=\"3123\">30</sup> ותחלה יש להבין בהפרש שבין ישראל ליעקב דהנה בחי' יעקב הוא בחי' ת\"ת<sup data-n=\"3124\">31</sup> דז\"א דאצי' וכו' שהוא מדה\"ר<sup data-n=\"3125\">32</sup> כידוע שהאבות הן המרכבה<sup data-n=\"3126\">33</sup> אברהם בבחי' חסד<sup data-n=\"3127\">34</sup> דז\"א יצחק בבחי' גבורה<sup data-n=\"3128\">35</sup> ויעקב בחי' ת\"ת וכתיב תתן אמת ליעקב<sup data-n=\"3129\">36</sup> חסד לאברהם כו' ואית' בזהר ע\"פ ונתתם לי אות אמת דא אות וי\"ו<sup data-n=\"3130\">37</sup> בחי' יעקב שהוא קו האמצעי בריח התיכון<sup data-n=\"3131\">38</sup> כו' והענין ידוע דקו הימין חח\"ן הרי קו השמאל בג\"ה<sup data-n=\"3132\">39</sup> סותרו כמו שמדת הדין סותר למדת החסד ומגביל אורו ולהיפך החסד מגביל אור הדין ונמצא שניהם נפסקים שאין זה נקרא אמת כי עיקר האמת הוא מה שיש לו קיום כמו שפת אמת תכון כו' ועד ארגיעה<sup data-n=\"3133\">40</sup> כו' שהשקר הוא הכזב מלשון יכזבו מימיו<sup data-n=\"3134\">41</sup> שהנהר נפסק כידוע ואמנם מדת האמת הוא המתקיים להיותו כלול מב' הפכים דחו\"ג באין מונע ומנגדו כלל ע\"כ לא יכזבו מימיו<sup data-n=\"3135\">42</sup> כו' וזהו אות אמת דא וי\"ו קו האמצעי שכלול מחו\"ג והוא דת\"י (כמ\"ש למעלה באות הכ\"א) ועוד יש מעלה בקו האמצעי דת\"י שאין בו שינוי מראשו לסופו כי כמו שהוא בראש כך הוא בסוף ולא ישתנה מצד אריכות המשכתו למטה והוא מצד חבור וקשר שיש בכולו מראשו לסופו יחד כמהות א' כבריח התיכון<sup data-n=\"3136\">43</sup> המבריח מן הקצה העליון לקצה<sup data-n=\"3137\">44</sup> התחתון משא\"כ ב' הקוין ימין ושמאל שאין בכל אחד מהם בחי' החיבו' והקשר ע\"כ לא ימצא בסופו כמו בראשו כמו חח\"ן הרי בנצח יגרע אור השפע וכן בהוד וכידוע בענין נו\"ה שנק' תרין בדי ערבות<sup data-n=\"3138\">45</sup> שאין בהם טעם וריח<sup data-n=\"3139\">46</sup> והוא מפני שנפסק בהן הארת המוחין כי החסד רק ענף החכמה<sup data-n=\"3140\">47</sup> שהשכל והטע' שבחסד כבר חלף ועבר עקרו ולא נשאר בו רק בצמצום והעלם אמנם עדיין יש בו בהעלם<sup data-n=\"3141\">48</sup> אבל מופסק ממנו ואין ביניהם חיבור וקשר כ\"כ כמו חסד דרועא ימינא<sup data-n=\"3142\">49</sup> כח היד ימין שנפסק מן המוח כו' ובחי' הנצח שהוא ניצוח ההסכם לבד כבר נפסק מן המוחין דחכמה",[["3112","19","<b>וגדלות שני. . י\"ג עד ך'</b>: ראה גם שע\"ת ח\"א ז, א ובהנסמן לשם."],["3113","20","<b>ך' שראוי למכור בנכסי אביו</b>: ב\"ב קנה, א. קנו, א. ראה גם מאמרי אדה\"ז תקס\"ו ע' קצג ואילך. פרשיות התורה ח\"א ע' רי. לקו\"ת במדבר ב, א. מאמרי אדה\"א נ\"ך ע' תקיט. וש\"נ."],["3114","21","<b>כמ\"ש שם</b>: לעיל קכח, ב."],["3115","22","<b>ישראל לי ראש</b>: ראה פע\"ח (שער הלולב) שכ\"ט פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' צה? לשע\"ת צד, ד."],["3116","23","<b>ב\"ן. . אלקי'</b>: ראה לעיל צט, א. הנסמן בתו\"ח ויצא קסו, א הערה 9. שע\"ת ח\"א מח, ג."],["3117","24","<b>דבחכמ'. . כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["3118","25","<b>תורתו אומנתו</b>: שבת יא, א. וראה גם תו\"ח בראשית ב, ג ובהנסמן לשם."],["3119","26","<b>ישראל שר אל</b>: ראה פע\"ח (שער הק\"ש) ש\"ח פ\"ט. מאמרי אדה\"א הנחות תקע\"ז ע' רעא. וש\"נ."],["3120","27","<b>אל נהירו דחכמתא</b>: ראה זהר לך צד, א. צו ל, ב. לא, א. אחרי סה, א."],["3121","28","<b>בענין כי שרית</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קעט. תקס\"ג ח\"ב ע' תערב ואילך. שע\"ת קיד, ד."],["3122","29","<b>במחשבה שנק' לאה</b>: ראה סידור שחרית ס, ג. סט, א. מאמרי אדה\"א נ\"ך ע' קג. וש\"נ. לעיל צ, ב. צה, ב."],["3123","30","<b>ורחל. . בדבור</b>: ראה ע\"ח (שער אח\"פ) ש\"ד פ\"א. סידור שם. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רכז. לעיל צה, ב."],["3124","31","<b>יעקב. . ת\"ת</b>: זהר (ס\"ת) ויצא קנז, ב. שם ח\"ג (תוספות) שב, א."],["3125","32","<b>ת\"ת. . מדה\"ר</b>: ראה זח\"א בהשמטות רנא, ריש ע' ב. פרדס (שער ערכי הכינויים) שכ\"ג מערכת רחמים."],["3126","33","<b>שהאבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42."],["3127","34","<b>אברהם בבחי' חסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["3128","35","<b>יצחק בבחי' גבורה</b>: ראה פרדס (שער הכינויים) שכ\"ב פ\"ד. מאמרי אדה\"ז שם ובהנסמן לשם."],["3129","36","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["3130","37","<b>ונתתם לי אות אמת. . וי\"ו</b>: יהושע ב, יב. זהר ויקרא ב, א. ראה סה\"מ תקס\"ה ח\"א ע' שסח ואילך."],["3131","38","<b>יעקב. . בריח התיכון</b>: ראה זהר תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט."],["3132","39","<b>דקו הימין חח\"ן. . בג\"ה</b>: ראה לעיל קכד, ב והנסמן לשם."],["3133","40","<b>שפת אמת. . ארגיעה</b>: משלי יב, יט."],["3134","41","<b>יכזבו מימיו</b>: נסמן בהערה הבאה."],["3135","42","<b>לא יכזבו מימיו</b>: ישעי' נח, יא."],["3136","43","<b>בקו האמצעי. . כבריח התיכון</b>: נסמן לעיל קכה, א."],["3137","44","<b>כבריח התיכון. . לקצה</b>: ע\"פ תרומה כו, כח. ויקהל לו, לג."],["3138","45","<b>נו\"ה. . בדי ערבות</b>: ראה זהר ויחי רכ, ב (ובאוה\"ח שם). שם בהשמטות רסב, א. בלק קצג, ב (ובמק\"מ שם). מאמרי אדה\"א במדבר ח\"ה ע' א'תתסח. לעיל קא, ב. שע\"ת קיד, ג."],["3139","46","<b>ערבות שאין בהם טעם וריח</b>: ויק\"ר פ\"ל, יב."],["3140","47","<b>החסד רק ענף החכמה</b>: נסמן לעיל קכד, ב."],["3141","48","<b>נשאר בו. . ההעלם</b>: ראה שע\"ת קיד, ג. מאמרי אדה\"א במדבר ח\"ה ס\"ע א'תתסז ואילך. נ\"ך ע' קעט. וש\"נ."],["3142","49","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה (יז, א)."]]],[2800530267,"יותר כי לא נשאר בו רק רושם בעלמא מן האהבה וחסד והוא כמו הירך הימין שנפסק מחסד שביד ימין כו' ואין לירך חיבור עם היד כו' וכך ביד שמאל וירך שמאל שהן בבחי' קו השמאל בג\"ה מופסקין זמ\"ז ע\"כ בסופו לא ימצא מראשו מפני הפסק הארת המוחין עד שיוכל להיות שם גרעון לגמרי כמו ותקע כף ירך יעקב<sup data-n=\"3143\">1</sup> שנגע בנצח בגיה\"נ<sup data-n=\"3144\">2</sup> כו' עד שמקבלים חיצונים משם כמ\"ש בזהר בענין ירך סוטה<sup data-n=\"3145\">3</sup> והיינו הטעם ג\"כ בחו\"ג עצמן במ\"ש אברהם יצא ממנו ישמעאל<sup data-n=\"3146\">4</sup> שהוא מותרי ופסולת החסדים כו' ויצחק יצא ממנו עשו<sup data-n=\"3147\">5</sup> מותרי ופסול' הגבו' כו' אבל יעקב שהוא בחי' קו האמצעי דת\"י הרי יש בקו זה חיבור וקשר מראשו לסופו עד שימצא בסופו כמו בראשו ממש (כמו שידוע דאין קישוי אלא לדעת<sup data-n=\"3148\">6</sup> שבראש הרי קשור בחי' היסוד בדעת שבמוח הראש כאילו הן מהות א' כו') שהרי הדעת הוא פנימי' המאיר ומקושר ברחמי' שבלב והיו לאחדים תמיד וכמו שאמ' בזהר משה מלגאו יעקב מלבר<sup data-n=\"3149\">7</sup> והוא בחי' הדעת שהוא פנימי' המדות של הרחמי' כי לפ\"ע הדעת ממש כך ערך הרחמי'<sup data-n=\"3150\">8</sup> וכל מי שאין בו דעת הוא אכזרי כתינוק וכה\"ג ויוסיף דעת<sup data-n=\"3151\">9</sup> יותר ירגיש הרחמנות כמ\"ש במ\"א באריכות שאין בין הדעת והרחמים שום הפסק כלל כמו בין החכ' וחסד הנ\"ל ומכ\"ש החיבור אל השפעת היסוד שהוא בחי' התקשרות המשפיע אל המקבל שהוא בא במהירות מן הדעת כמו והאדם ידע<sup data-n=\"3152\">10</sup> כו' (ויש בחי' נה\"י בפנימי' והן כליות<sup data-n=\"3153\">12</sup> יועצו'<sup data-n=\"3154\">11</sup> ופנימיו' יסוד סיומ' דגופ'<sup data-n=\"3155\">13</sup> ונו\"ה בחיצוניות הן תרין ירכין<sup data-n=\"3156\">14</sup> כו') וכמ\"ש בזהר בראשית בענין יקוו המים<sup data-n=\"3157\">15</sup> כו' אל מקום א' שהוא בחי' יסוד שמתקבץ שם כל השפע ונק' כנישו דכל נהורין כו' והוא קו האמצעי שמבריח כו' וע\"כ נק' אמת שהן אותיו' א'מ'ת' ראש תוך סוף<sup data-n=\"3158\">16</sup> של האותיות שכתחלתו כן סופו שזהו עיקר האמת ולזה אמרו יעקב לא מת<sup data-n=\"3159\">17</sup> כו' מפני שאין אחיזה למות שרש הקליפות בקו האמצעי כלל מטעם זה ולזה אמר כי שרית עם אלקים בחי' ב\"ן כו' והוא בבחי' הדעת וחכמה בראש דישראל לי ראש דוקא כנ\"ל ולכך אמר לו ישראל יהי' שמך<sup data-n=\"3160\">18</sup> משא\"כ יעקב מצד בחי' חיצוניות דנו\"ה תרין ירכין כו' שבאין מכחו של חו\"ג דאברהם ויצחק כו' ע\"כ נגע בכף יריכו בנצח דקו הימין מטעם הנ\"ל משא\"כ בישראל נאמר וגם נצח ישראל לא ישקר<sup data-n=\"3161\">19</sup> כו' כי ישראל הוא בבחי' הפנימי' של המדות דחו\"ג בבחי' קו האמצעי דדעת כו' שנאמר בו כי שרית כו' וכן מ\"ש יעקב לא מת משום שנאמר ימותו ולא בחכמה<sup data-n=\"3162\">20</sup> כו' (כן משארז\"ל יעקב משמש במרו'<sup data-n=\"3163\">21</sup> שהוא בחו\"ב כי גדול' דעה<sup data-n=\"3164\">22</sup> כו' והוא למעלה מהחזה כו' כמ\"ש במ\"א) היינו מצד שרש יעקב למעלה מעלה בבחי' הקו האמצעי דת\"י מטעם הנ\"ל אבל בחיצוניות המדות דיעקב נאמר ויגע בכף יריכו<sup data-n=\"3165\">23</sup> כו' וכמ\"ש במ\"א וד\"ל:\n(לו) <b>והנה</b> כתיב אלה תולדות יעקב יוסף<sup data-n=\"3166\">24</sup>. שהוא בחי' יסוד<sup data-n=\"3167\">25</sup> בחי' צדיק עליון כו' והוא הנק' וי\"ו זעירא<sup data-n=\"3168\">26</sup> כו':\n<b>וביאור</b> הדברים ידוע בענין כי כל בשמים ובארץ ותרגומו דאחיד<sup data-n=\"3169\">27</sup> בשמיא כו' שהוא בחי' אור השפע דיסוד צדיק עליון הנק' חי העולמים<sup data-n=\"3170\">28</sup> כו' ועד\"מ מי שמבין אור השכל לעצמו אבל אין לו כח להביא אור השכל לידי השפעה לחוץ למקבל ה\"ז עדיין רק בבחי' עצם השפע הזאת כמו שהוא בעצמו אבל מי שיוכל להביאו להשפעה בגלוי למקבלים הוא הנק' בחי' יסוד כו' והוא הנק' כל דאחיד כו' שנמשך מן המשפיע אל המקבל וכמ\"ש אור זרוע לצדיק<sup data-n=\"3171\">29</sup> כו' וכתיב באור כי טוב<sup data-n=\"3172\">30</sup> שבחי' יסוד נקרא טוב<sup data-n=\"3173\">31</sup> כמו",[["3143","1","<b>ותקע כף ירך יעקב</b>: וישלח לב, כו. ראה פרדס (שער ירך יעקב) שי\"ז."],["3144","2","<b>בגיה\"נ</b>: ג: בגיד הנשה."],["3145","3","<b>שמקבלים חיצונים. . ירך סוטה</b>: ראה זהר (סבא) משפטים קיא, ב ואילך."],["3146","4","<b>אברהם יצא ממנו ישמעאל</b>: ראה פסחים נו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קטו ואילך. וש\"נ. שע\"ת פה, ג ובהנסמן לשם."],["3147","5","<b>ויצחק יצא ממנו עשו</b>: נסמן בהערה שלפנ\"ז."],["3148","6","<b>דאין קישוי אלא לדעת</b>: יבמות נג, סע\"ב. ראה מאמרי אדה\"א במדבר ח\"ג ע' א'קמה. וש\"נ. ח\"ד ע' א'תקכד. וש\"נ."],["3149","7","<b>משה מלגאו יעקב מלבר</b>: ראה ת\"ז תי\"ג (כט, א). לעיל כה, א ובהנסמן במ\"מ לשם."],["3150","8","<b>לפ\"ע הדעת. . הרחמי'</b>: ראה גם לעיל שם ובהנסמן במ\"מ לשם."],["3151","9","<b>ויוסיף דעת</b>: קהלת א, יח. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' כא."],["3152","10","<b>והאדם ידע</b>: בראשית ד, א."],["3153","12","<b>כליות יועצ'</b>: ברכות סא, א."],["3154","11","<b>נה\"י. . כליות יועצו'</b>: ראה זהר (אד\"ז) האזינו רצו, א. הנסמן במאמרי אדה\"א קונטרסים ע' רכד."],["3155","13","<b>יסוד סיומ' דגופ'</b>: ת\"ז בהקדמה (יז, א). הנסמן במאמרי אדה\"א קונטרסים שם."],["3156","14","<b>ונו\"ה. . תרין ירכין</b>: ראה ת\"ז תי\"ג (כט, א) ובהנסמן בניצוצי זהר שם."],["3157","15","<b>בזהר בראשית בענין יקוו המים</b>: בראשית א, ט. ראה זהר בראשית יח, א (ובזהר\"ק ומק\"מ שם). לג, א (ובאוה\"ח ומק\"מ שם). מאמרי אדה\"א בראשית ע' רפה. וש\"נ. קונטרסים ע' רכד."],["3158","16","<b>א'מ'ת' ראש תוך סוף</b>: ראה ב\"ר פפ\"א, ב. סה\"מ תקס\"ה ח\"א ע' שסח ואילך. שע\"ת כד, סע\"א. לעיל כה, ב."],["3159","17","<b>יעקב לא מת</b>: תענית ה, ב. ראה הנסמן בתו\"ח נח סד, ד הערה 60. ביאוה\"ז ויחי לה, ג. ויגש קלז, ב."],["3160","18","<b>ישראל יהי' שמך</b>: וישלח לה, י."],["3161","19","<b>וגם נצח ישראל לא ישקר</b>: שמואל-א טו, כט. ראה גם שע\"ת קטו, א."],["3162","20","<b>ימותו ולא בחכמה</b>: איוב ד, כא. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רצט."],["3163","21","<b>יעקב משמש במרו'</b>: זהר ח\"ש קלג, א. ביאוה\"ז שם יד, ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' קמ."],["3164","22","<b>גדול' דעה</b>: ברכות לג, א."],["3165","23","<b>ויגע בכף יריכו</b>: וישלח לב, כו."],["3166","24","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב."],["3167","25","<b>יוסף. . יסוד</b>: ראה זהר (רע\"מ) פינחס רלו, א. פרדס (שער ערכי הכינויים) שכ\"ג מערכת יוסף."],["3168","26","<b>יסוד. . וי\"ו זעירא</b>: ראה זהר אחרי עד, ב. מאו\"א מערכת ו ס\"א וביאור נתיב שם."],["3169","27","<b>כי כל. . ותרגומו דאחיד</b>: דהי\"א כט, יא. ראה זהר בראשית לא, א. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תשמב."],["3170","28","<b>דיסוד. . חי העולמים</b>: ראה זהר מקץ קצג, ב. יאיר נתיב למאו\"א מערכת חי סכ\"ד."],["3171","29","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["3172","30","<b>וכתיב באור כי טוב</b>: בראשית א, ג."],["3173","31","<b>יסוד נק' טוב</b>: ראה זהר נח ס, א. הנסמן במאמרי אדה\"א קונטרסים ע' רכד."]]],[2800530268,"שמטבע הטוב להטיב<sup data-n=\"3174\">32</sup> לזולתו דוקא כך בחי' יסוד נק' צדיק וטוב כמ\"ש אמרו צדיק כי טוב<sup data-n=\"3175\">33</sup> וצדיק צדקות אהב<sup data-n=\"3176\">34</sup> כו' להחיות רוח שפלים<sup data-n=\"3177\">35</sup> כו' וכמ\"ש טוב ה' לכל<sup data-n=\"3178\">36</sup> כו' (וטוב גימ' י\"ז<sup data-n=\"3179\">37</sup> שהוא א\"ה ו\"ה ר\"ת<sup data-n=\"3180\">38</sup> דאת השמים ואת הארץ דהיינו דאחיד בשמיא וארעא כו' שזהו בחי' התקשרות המשפיע במקבל כידוע ומבואר במ\"א ונק' ג\"כ שלום וברית כמו בפנחס הנני נותן לו<sup data-n=\"3181\">39</sup> את בריתי שלום כמ\"ש במ\"א בהפרש שבין פנימי' יסוד ז\"א כיוסף לחיצוניות יסוד שהוא בחי' נח<sup data-n=\"3182\">40</sup> צדיק תמים כמ\"ש בזהר) והיינו ו' זעירא שהוא בחי' הקיבוץ ואסיפת אור ושפע של המדות דיעקב הנ\"ל. וזהו אלה תולדות יעקב יוסף בחי' התולדה של המדות ע\"י יוסף דוקא שהוא אור הזרוע לצדיק ח\"י עלמין כו' וכתיב צדיק כתמר<sup data-n=\"3183\">41</sup> כו' כארז בלבנון ששרש יסוד ז\"א הוא ביסוד דא\"א וע\"י<sup data-n=\"3184\">42</sup> שלמעלה מן השכל כו' כי נעוץ תחלתן בסופן כי יסוד נק' סיומא דגופא כו' וע\"כ עיקר התענוג בכלות השפע דוק' וכידוע בענין ויכל אלקים<sup data-n=\"3185\">43</sup> כו' (והיינו שהיה יוסף יפה תואר<sup data-n=\"3186\">44</sup> כו' מעין שופרי' דיעקב<sup data-n=\"3187\">45</sup> בחי' ת\"ת דז\"א ושופרי' דיעקב מעין שופרי' דאדם קדמא'<sup data-n=\"3188\">46</sup> בחי' א\"א וא\"ק כו') ומ\"ש אלה תולדות היינו בחי' ו\"ק דז\"א שכלול כ\"א מו' שעולה גי' אלה<sup data-n=\"3189\">47</sup> אך אין תולדה בלא תוס' מוחין חדשי' מאו\"א ע\"י בחי' הגדלות דכחב\"ד שבז\"א כנ\"ל (ובזה יש ג\"כ בחי' ההתבוננות אחת כוללת מן הרבה פרטי' בכלל א' שהוא מיסוד דמל' דא\"ס עד בחי' יסוד ז\"א (ע\"ד הנ\"ל בז\"א בכלל שהוא סוף עולם האין סוף<sup data-n=\"3190\">48</sup> כו') וכמ\"ש וידבר שלמה מן הארז אשר בלבנון<sup data-n=\"3191\">49</sup> בעצם התענוג הפשוט שבעצמות אא\"ס כשעלה ברצונו הפשוט אנא אמלוך<sup data-n=\"3192\">50</sup> כו' עד בחי' האזוב אשר בקיר שהוא בחי' וי\"ו זעירא דקטנות יסוד ז\"א בהשפעתו והתקשרותו במל' שנק' קיר<sup data-n=\"3193\">51</sup> וכמ\"ש ויתפלל כו' אל הקיר<sup data-n=\"3194\">52</sup> וכן נעשה נא עליי' קיר<sup data-n=\"3195\">53</sup> שהוא בחי' המל' כמ\"ש בזהר והיינו צדיק כתמר דסליק לע' שנין<sup data-n=\"3196\">54</sup> דא\"ק ששם כארז בלבנון ישגה בבחי' א\"ס ממש וד\"ל) (וגם עוד מבואר במ\"א שיוסף נק' יתום מאמו<sup data-n=\"3197\">55</sup> ולא מאביו כו' ר\"ת יתום יפ\"ת כו'<sup data-n=\"3198\">56</sup> וענין יתום מאמו היינו לפי שבחי' יסוד אימא קצר<sup data-n=\"3199\">57</sup> ומסתלק ונעלם בתולדות המדות כנראה בחוש שבהתפעלות המדות מסתלק השכל כו' ולזה א' דבינה רק עד הוד דז\"א אתפשט'<sup data-n=\"3200\">58</sup> ולא עד יסוד ז\"א שזהו רק עד בחי' ההודא' שבאה מצד השכל ולא בבחי' יסוד דז\"א שהוא בחי' ההתקשרות עצמיות שבלב שבו מאיר מבחי' יסוד אבא בחי' התקשרות בעצם אור המושכל קודם שבא להשגה והיינו לבי ראה הרבה חכמה<sup data-n=\"3201\">59</sup> כו' ראיית השכל שבלב בשר ביסוד ז\"א דוקא והוא בחי' הביטול שנמשך בהבל חזה הלב כמ\"ש בר\"מ בעין השכל דבלבא אתחזי כולא<sup data-n=\"3202\">60</sup> כו' לפי שיסוד אבא ארוך<sup data-n=\"3203\">61</sup> משל אימא ונמשך עד בחי' יסוד ז\"א גם לאחר שנסתלק אור הבינה ע\"כ נק' יתום מאמו ולא מאביו וכו' וכמ\"ש ביאור זה במ\"א באריכות והיינו ג\"כ ענין אלה תולדות יעקב בחי' טיפת יסוד אבא הוא יוסף יסוד ז\"א כו' וד\"ל):\n(לז) <b>ומעתה</b> יש להבין בענין יחוד דישראל ויעקב בלאה ורחל. וביאור ענין לאה ורחל ידוע שזהו ענין מח' ודבור<sup data-n=\"3204\">62</sup> והיינו ענין ב' ההי\"ן<sup data-n=\"3205\">63</sup> דשם הוי' כמ\"ש בזהר תרין נוקבין פריש שלמה<sup data-n=\"3206\">64</sup> כו' אתי מלבנון כלה<sup data-n=\"3207\">65</sup> כו' ה' ראשונה שם הגדולה לאה וה' אחרונה שם הקטנה רחל<sup data-n=\"3208\">66</sup> כו' ותחלה יש להקדי' בענין הקול קול יעקב<sup data-n=\"3209\">67</sup> שיש קלא פנימא' דלא משתמע<sup data-n=\"3210\">68</sup> כו' להיו' ידוע בענין יום ליום יביע אמר<sup data-n=\"3211\">69</sup> שזהו אש מים רוח חג\"ת כמו הקול שהוא מורכב מאמ\"ר<sup data-n=\"3212\">70</sup>",[["3174","32","<b>שמטבע הטוב להטיב</b>: נסמן לעיל כב, א."],["3175","33","<b>אמרו צדיק כי טוב</b>: ישעי' ג, יא."],["3176","34","<b>וצדיק צדקות אהב</b>: תהלים יא, ז [ושם: כי צדיק ה']."],["3177","35","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["3178","36","<b>טוב ה' לכל</b>: תהלים קמה, ט."],["3179","37","<b>וטוב גימ' י\"ז</b>: ראה לקו\"ת להאריז\"ל ר\"פ וישב. מאמרי אדה\"א בראשית ע' רצד. וש\"נ. ע' שכח."],["3180","38","<b>א\"ה ו\"ה ר\"ת</b>: בראשית א, א. ירמי' כג, כד. ראה השמטות לזח\"א רנא, א. מאמרי אדה\"א קונטרסים ע' רכה. וש\"נ."],["3181","39","<b>הנני נותן לו</b>: פינחס כה, יב."],["3182","40","<b>בההפרש. . כיוסף. . נח</b>: ראה זהר ר\"פ נח. וראה גם מאמרי אדה\"א קונטרסים שם ובהנסמן לשם."],["3183","41","<b>צדיק כתמר</b>: תהלים צב, יג."],["3184","42","<b>יסוד ז\"א. . וע\"י</b>: ראה גם לעיל קכח, א ובהנסמן במ\"מ לשם."],["3185","43","<b>ויכל אלקים</b>: בראשית ב, ב. ראה סידור שער המילה קלט, ב ואילך. לקו\"ת תזריע כ, ד."],["3186","44","<b>יוסף יפה תואר</b>: וישב לט, ו."],["3187","45","<b>יוסף. . מעין שופרי' דיעקב</b>: ראה ב\"ר פפ\"ד, ח."],["3188","46","<b>ושופרי' דיעקב. . דאדם קדמא'</b>: ראה ב\"ב נח, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' לה. מאמרי אדה\"א בראשית ע' קפא. במדבר ח\"א ע' קנא. וש\"נ. תו\"ח ויצא קסג, ד ובהערה 59."],["3189","47","<b>ו\"ק דז\"א. . גי' אלה</b>: ראה גם לקו\"ת פקודי ד, ג. תו\"ח נח נו, ב ובהערה 15."],["3190","48","<b>בז\"א. . סוף עולם האין סוף</b>: ראה לעיל קלא, ב ואילך ובהנסמן שם."],["3191","49","<b>וידבר שלמה. . בלבנון</b>: מלכים-א ה, יג [ושם: וידבר על העצים ? ראה תו\"ח ויחי רמט, ב ובהערה 19]."],["3192","50","<b>אנא אמלוך</b>: נסמן לעיל קטו, א."],["3193","51","<b>במל' שנק' קיר</b>: נסמן לעיל קכח, א."],["3194","52","<b>ויתפלל כו' אל הקיר</b>: מלכים-ב כ, ב [ושם: ויסב את פניו אל הקיר ויתפלל. ועד\"ז ב]ישעי' לח, ב."],["3195","53","<b>נעשה נא עליי' קיר</b>: מלכים-ב ד, י."],["3196","54","<b>כתמר דסליק לע' שנין</b>: ראה זהר ויקרא טז, א. כד, א. מאמרי אדה\"א שמות ח\"א ע' רכה. וש\"נ."],["3197","55","<b>שיוסף נק' יתום מאמו</b>: ראה ע\"ח (שער הצלם) שכ\"ו פ\"ג. ביאוה\"ז תשא נד, ג. מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות [מהדורת תשמ\"ט] ע' 21. מאמרי אדה\"א בראשית ע' רצד. נ\"ך ע' קיח. וש\"נ."],["3198","56","<b>ר\"ת יתום יפ\"ת כו'</b>: ראה ע\"ח שער הכללים ספ\"ד. הנסמן באוה\"ת בהעלותך כרך ו ע' א'תשסו."],["3199","57","<b>יסוד אימא קצר</b>: נסמן בסמוך בהערה יסוד אבא ארוך."],["3200","58","<b>דבינה. . הוד. . אתפשט'</b>: ראה זהר (רע\"מ) פינחס רכג, ב. אמ\"ב שער התפילין קכ, ד. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקפה."],["3201","59","<b>לבי ראה הרבה חכמה</b>: קהלת א, טז [ושם: ולבי ? ראה מאמרי אדה\"א שמות ח\"ב ע' תקמט. וש\"נ]."],["3202","60","<b>בעין השכל. . כולא</b>: נסמן לעיל קיא, א."],["3203","61","<b>יסוד אבא ארוך</b>: ראה ע\"ח שער הכללים פ\"י. סידור שחרית לשבת קפז, ד. פיה\"מ מג, ב. ג. מאמרי אדה\"א נ\"ך ע' קיח. וש\"נ."],["3204","62","<b>לאה ורחל. . מח' ודבור</b>: נסמן לעיל קלג, ב."],["3205","63","<b>לאה ורחל. . ב' ההי\"ן</b>: ראה זהר (רע\"מ) פינחס רמד, ב. הנסמן במאמרי אדה\"א בראשית ע' רכב."],["3206","64","<b>תרין נוקבין פריש שלמה</b>: ראה זהר (אד\"ז) האזינו רצ, ב. מאמרי אדה\"א קונטרסים ע' תכח. וש\"נ."],["3207","65","<b>אתי מלבנון כלה</b>: שה\"ש ד, ח."],["3208","66","<b>שם הגדולה. . רחל</b>: ויצא כט, טז."],["3209","67","<b>הקול קול יעקב</b>: תולדות כז, כב."],["3210","68","<b>קלא פנימא' דלא משתמע</b>: ראה זהר בראשית נ, ב. מאמרי אדה\"א קונטרסים ע' שח. וש\"נ."],["3211","69","<b>יום ליום יביע אומר</b>: תהלים יט, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תעב. וש\"נ."],["3212","70","<b>הקול. . מאמ\"ר</b>: ראה זהר (רע\"מ) בא מג, ב. תצוה קפד, ב. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תרנא. וש\"נ. תו\"ח בראשית לט, ד ובהערה 26."]]],[2800530269,"הגשמי' כך הבל הלב עצמו כלול מאמ\"ר רוחניי' שהוא בחי' חו\"ג והממוצע שהוא הרוח דהיינו בחי' כיווץ והתפשטות שבהבל הרוחני דלב כמו כאשר האדם שמח בלבו אז יש בחי' אור ההתפשטו' בלב והוא הבל דחסדי' וכשהוא בעוצב הוא בבחי' הכיווץ וצמצום והוא בחי' הבל דגבורו' והממוצע מחו\"ג הוא הבל רוחני ממוצע ממוזג מאמצעות חו\"ג כרוח הממוצע מאש ומים בגשם ההבל כידוע שהצמאון מיסוד האש<sup data-n=\"3213\">1</sup> וכן ניחר גרוני<sup data-n=\"3214\">2</sup> כו' בקול הגשמי בא מתגבורת יסוד אש שבהבל הלב ולהיפך צלילת קול הבל הלב מיסוד המים כו' והממוצע שהוא רוח ממוזג כו' וכך הוא בקול הממוצע וממוזג מחדוה ומרירות ועוצב שנק' קול ערב לנפש שזה תלוי במזיגה הרוחני' שבהבל הלב דוקא כו' וגם ברוח החיים שבחלל הימיני וחלל השמאלי הרי הוא בבחי' רו\"ש בדפיקו דלבא כידוע שזהו ג\"כ בבחי' כיווץ והתפשטו' (אלא שהוא בהיפך כאשר רוח החיים נכנס מן המוח בלב מתכווץ לקבל וכשיוצא מתפשט כו' לפי שהחיות דוקא רו\"ש כו' וכמבואר בס' הרפואה) וכ\"ז נק' קלא דמשתמע בדבור שזהו בחי' רוח הבל הדבור והיינו בחי' קול ודבור הנז' בזהר<sup data-n=\"3215\">3</sup> בכמה דוכתי והוא בחי' יחוד יעקב ורחל דהיינו בחי' ההמשכה של המדות שבלב הבא בבחי' רוח הבל הלב מורכב מאמ\"ר רוחניי' עד בחי' קול הדבור ובחי' כח הדבור נמשך מנקב החזה דלב כו' ונק' רוח ממללא<sup data-n=\"3216\">4</sup> (והיינו מ\"ש בע\"ח דכתר דנוק' דז\"א דבוק בחזה דז\"א<sup data-n=\"3217\">5</sup> וז\"ש לעולם ה' דברך נצב בשמים<sup data-n=\"3218\">6</sup> כו' וכמ\"ש במ\"א בענין ממצוא חפצך ודבר דבר<sup data-n=\"3219\">7</sup> מקור כח הדבור שנמשך מהבל הלב דז\"א וכנראה בחוש שאם הלב עצב בכיווץ ימעיט בדבור וכשהוא בהתפשטות ירחיב הדבור לפי שכח של הדבור תלוי בהבל הקול שבלב עצמו כו') וכאשר לא נמשך מהבל הלב בדבור ע\"ד שאמר לבא לפומא לא גליא<sup data-n=\"3220\">8</sup> לא נעשה דבר מלך עדיין מאין ליש כלל וכמו ואילו צדיק ורשע לא קאמר<sup data-n=\"3221\">9</sup> כי בדבור כבר נעשה כי הוא אמר ויהי<sup data-n=\"3222\">10</sup> וכן ודברי אשר יצא מפי לא ישוב ריקם<sup data-n=\"3223\">11</sup> כו' אבל בלב דז\"א עדיין יכול להתהפך מדין לחסד כמו וינחם ה'<sup data-n=\"3224\">12</sup> כו' וכן ויאמר אל לבו לא אוסיף עוד<sup data-n=\"3225\">13</sup> כו' וזהו בחי' חג\"ת דהבל הלב דז\"א שבא ומתייחד בדבור עלמא דאתגליא כו' כידוע וד\"ל. ויש בחי' קלא פנימאה דלא משתמע בדבור כלל והוא בחי' המוחין שבמדות חו\"ג כמו אהוי\"ר שלמעלה מבחי' רוח החיים שבלב כמו עצם חדוה של אהבה וחסד או עצם רוגז ודין של יראה ופחד שהמה רוחניים הרבה גם מהרכבת הרוחניו' דאמ\"ר הנ\"ל הבא במורכב בלב הגשמי וגם שיש בזה הרכב' מאמ\"ר שהוא בחי' חג\"ת אבל הוא בבחי' הפנימית שבלב שהוא במדות חג\"ת שיש בהן הארת המוחין הנק' קלא פנימאה דבינה שבז\"א הבא ונמשך מן המוח ללב וכאשר הוא בא בהתפעלות רוחניות שע\"י הדעת בחי' ישראל הנ\"ל ונמשך מיד באותיות המח' שנק' לאה נק' יחוד ישראל ולאה פנימיות המדות שבלב מיד מהרהר במח' אם מתפעל בשכל וטעם לאהבה וחסד הרי מיד יבוא מדה זו עם המוחין שבה במח' וכידוע שהמחשב' מלבשת המדות דישראל בפרטיהם ונק' לאה כמו נלאה<sup data-n=\"3226\">14</sup> להכיל המדות כו' ושרש לאה למעלה בבינה<sup data-n=\"3227\">15</sup> היינו לאה ילדה ששה בנים<sup data-n=\"3228\">16</sup> בחי' ו\"ק דמדות דז\"א אך יחוד ישראל ולאה היינו מוחין דאו\"א שבז\"א הוא מתייחד בלאה התחתונה דמח' שמקבלת מבחי' מל' דתבונה שרש המח' כו' וד\"ל. ויש יחוד ישראל ורחל כאשר בא הארת בחי' פנימי' המוחין שבמדות בדבור וכן יש יחוד יעקב",[["3213","1","<b>שהצמאון מיסוד האש</b>: ראה תניא פ\"ג."],["3214","2","<b>ניחר גרוני</b>: תהלים סט, ד."],["3215","3","<b>קול ודבור הנז' בזהר</b>: בראשית לו, א. נ, ב. נח עד, א. וירא צח, א. תולדות קמב, סע\"א ואילך. ועוד."],["3216","4","<b>רוח ממללא</b>: ת\"א לבראשית ב, ז."],["3217","5","<b>דכתר דנוקב'. . בחזה דז\"א</b>: ראה ע\"ח (שער מוחין דצלם) שכ\"ו פ\"ג."],["3218","6","<b>לעולם ה' דברך נצב בשמים</b>: תהלים קיט, פט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שפב."],["3219","7","<b>ממצוא חפצך ודבר דבר</b>: ישעי' נח, יג."],["3220","8","<b>לבא לפומא לא גליא</b>: מדרש תהלים פט, א. קה\"ר פי\"ב, י."],["3221","9","<b>ואילו צדיק ורשע לא קאמר</b>: ראה נדה טז, ב. תניא פ\"א. מאמרי אדה\"א דברים ח\"א ע' רכג. וש\"נ. תו\"ח בראשית ל, ד ובהערה 19. שע\"ת יח, א ובהנסמן במ\"מ לשם. לקמן קלט, א. לעיל מא, ב."],["3222","10","<b>כי הוא אמר ויהי</b>: תהלים לג, ט."],["3223","11","<b>ודברי. . לא ישוב ריקם</b>: ישעי' נה, יא [ושם: דברי. . אלי ריקם ? ראה שע\"ת קכא, ד]."],["3224","12","<b>וינחם ה'</b>: בראשית ו, ו."],["3225","13","<b>ויאמר אל לבו. . עוד</b>: נח ח, כא [ושם: ויאמר ה'. . לקלל עוד]."],["3226","14","<b>לאה כמו נלאה</b>: ראה לקו\"ת להאריז\"ל ס\"פ תולדות. מאמרי אדה\"א נ\"ך ע' קה. וש\"נ."],["3227","15","<b>לאה. . דבינה</b>: ראה לקו\"ת להאריז\"ל ויצא (סוד יעקב עם ב' נשיו)."],["3228","16","<b>לאה ילדה ששה בנים</b>: ויצא ל, כ. ראה גם מאמרי אדה\"א נ\"ך ע' קפח. וש\"נ."]]],[2800530270,"ולאה שנק' הרהורי לבא דהיינו מה שבבחי' חיצוניות המדו' עולה בהרהור במוח וכן יש יחוד יעקב ורחל שהוא המשכת חיצוניות המדות שבלב בדבור כנ\"ל וסדר ההמשכה לפעמים כך הוא שבחי' המדות שבלב עולה ומתייחד במחשבה ומן המח' בא אל הלב בחיצוניות הבל הלב ומהבל הלב נכנס להבל הדבור שנק' קול ודבור ולפעמי' מן המח' נכנס אל הדבור וכמו שמדבר מה שחושב שעקבי לאה נכנסין תוך ראש רחל<sup data-n=\"3229\">17</sup> כו' ובשעה זו שמדבר מה שחושב הרי יוצא מקול הבל הלב בדבור בה' מוצאות ובודאי מה שבלבו עולה במח' שאין מחשב' בלא מדות שבלב כו' ונמצא בחי' יעקב שהוא רוח הבל קול הלב משמש במח' ודבור שנק' ב' אחיות לאה ורחל עלמא דאתכסיא ועלמא דאתגליא<sup data-n=\"3230\">18</sup> מאמר סתום ומאמר פתוח<sup data-n=\"3231\">19</sup> כידוע וד\"ל (ועד\"ז יש יחוד ישראל ולאה ויחוד ישראל ורחל בפנימיו' המדות בבחי' קלא פנימאה הנ\"ל וז\"ש יביע אמר ואח\"כ אין אומר במחשבה ואין דברים<sup data-n=\"3232\">20</sup> והיינו בשבת שהיחוד בפנימיות דזו\"נ כו' כו' כידוע ומבואר הכל במ\"א וד\"ל):\n(לח) <b>והנה</b> מעתה י\"ל דרך פרט יותר בענין הלבושי' דמחדו\"מ כו' כמ\"ש לבושין תקינת לון<sup data-n=\"3233\">21</sup> כו' ולזה יש להקדים תחלה שרש ומקור לבחי' האותיות ומה שלפעמים נק' בשם כלים<sup data-n=\"3234\">22</sup> ולפעמי' בשם לבושין<sup data-n=\"3235\">23</sup> כו' ואח\"כ יתבאר דרך פרט בבחי' רחל ולאה ומל' דתבונה ובינה עד רום המעלות כו' דהנה שרש אותיות הוא בעצם הנפש ממש שהנפש מלאה אותיות<sup data-n=\"3236\">24</sup> כידוע והיינו מתחלת עצם התהוותה ובב' אופנים באותיות המח' ואותיות הדבור דהיינו מיד שתתהווה עצם הנפש מיוחדים בה אותיות מח' וכלולים בה בעצם כמו שכלול תנועת החי בחי כו' ויוצאים ובוקעים לגלוי מחשב' בג' מדריגות דמיון וציור בלא אותיות כלל ואותיות פשוטים מבולבלים בלי צירוף וחיבור ענין דבר מה ואותיו' מצורפי' ע\"פ מח' עיוני' כו' וכך יש בעצם הנפש בחי' אותיות הדבור שהרי נק' נפש המדברת<sup data-n=\"3237\">25</sup> או רוח ממללא וכלולים בה בעצם ויוצאים לגלוי כתנועת החי וכה\"ג כדבור של המלאכים דכתיב וקרא זא\"ז<sup data-n=\"3238\">26</sup> כו' והוא ג\"כ בג' מדריגות חומר פשוט של כל אות ואות ונק' הבל רוח הדבור ואותיות א\"ב ג\"ד מיוחדים בלי צירוף וחיבור האותיות שנק' צורה שבדבור ברוח ממללא כמו ב' רוחות מספרות<sup data-n=\"3239\">27</sup> וכדבור המלאכים וכו':\n<b>והנה</b> גם טרם שמתהוה מקור לרצון פשוט ותענוג פשוט כבר יש אותיות הכלולי' בעצם הנפש רק אחר התהוות הרצון יוצאי' להיות בחי' גלוי לרצון ונק' אותיות דרצון שהוא בחי' גלוי הרצון ליש ודבר מה במציאת רצון שזהו עיקר ענין האותיות בעצם הנפש שאינו רק בחי' גלוי אור עצם הנפש בכל איזה בחי' יש ומציאת דבר מה ע\"י האותיות יוצא בגלוי מבחי' היולי הנעלם כו' (וכמ\"ש בלק\"א בכ\"ב אותיות<sup data-n=\"3240\">28</sup> שקבועים בנפש שהן כ\"ב כחות כ\"ב תנועות הנפש כו') ועי\"ז יוכל הרצון לבא בגלוי באור השכל ולולי התגלות הרצון בבחי' אותיות דהיינו מה שנראה למהות ומציאת רצון לא היה בא הרצון העצמי הנעלם בלבוש אחר ממהות למהות שהוא בחי' הרצון הנראה ונגלה בשכל וטעם לרצון כידוע וד\"ל וכך בשכל וטעם לרצון שנק' חכמה שברצון מה שנראה למציאת טעם לרצון הוא בחי' אותיות שבו עי\"ז יורד ממהות למהות המדות שברצון כמו האהבה שברצון שגם הוא אינו רק מציאת רצון אלא שמלובש במהות אהבה שמצד הרצון הוא אוהב (אהבה ל' אבה<sup data-n=\"3241\">29</sup> והה\"א ה\"ח המתפשטי' מחו\"ב כו') ואותו הרצון עצמו הוא בשכל וטעם לרצון והוא עצם הרצון בהיותו עדיין למעלה",[["3229","17","<b>שעקבי לאה. . רחל</b>: ראה ע\"ח (שער לאה ורחל) של\"ח פ\"ג. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' לה."],["3230","18","<b>לאה ורחל עלמא. . דאתגליא</b>: ראה זהר (ס\"ת) ויצא קנב, א. וארא כט, ב. ע\"ח (שער מוחין דצלם) שכ\"ג פ\"ד."],["3231","19","<b>מאמר סתום ומאמר פתוח</b>: נסמן לקמן קלט, א."],["3232","20","<b>אין אומר. . ואין דברים</b>: תהלים יט, ד. ראה סידור שחרית לשבת קפא, א ואילך. מאמרי אדה\"ז הנחות הר\"פ ע' ג."],["3233","21","<b>לבושין תקינת לון</b>: ת\"ז בהקדמה (יז, א)."],["3234","22","<b>האותיות. . כלים</b>: ראה שער היחוה\"א ספ\"ד. הנסמן לשע\"ת ח\"א לח, ב."],["3235","23","<b>האותיות. . לבושין</b>: ראה גם סה\"מ תקס\"ב ח\"ב ע' שצא. תקס\"ג ח\"א ע' רמט (נוסחא שני') וע' רסא."],["3236","24","<b>שהנפש מלאה אותיות</b>: ראה ע\"ח (שער טנת\"א) ש\"ה פ\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרלט וע' תשל ובהנסמן במ\"מ לשם. הנסמן במאמרי אדה\"א במדבר ח\"א ס\"ע שט."],["3237","25","<b>נפש המדברת</b>: ראה גם לעיל מב, ב. תו\"ח נח עט, ג ובהערה 12."],["3238","26","<b>וקרא זא\"ז</b>: ישעי' ו, ג."],["3239","27","<b>ב' רוחות מספרות</b>: ברכות יח, ב."],["3240","28","<b>וכמ\"ש בלק\"א בכ\"ב אותיות</b>: ראה אגה\"ק ס\"ה."],["3241","29","<b>אהבה ל' אבה</b>: ראה שרש ישע מערכת אבה הובא בספר החקירה צב, רע\"א. מאמרי אדה\"א הנחות תקע\"ז ע' רסד. וש\"נ."]]],[2800530271,"מהשכל וטעם כו' ואמנם ע\"פ האותיו' נשתנה ונראה בלמעל' מן השכל ובשכל ובמדות כו' וכן יש אותיות למדות שהוא מה שנראה האהבה שברצון במציאת יש כו' עד הרצון שבמחדו\"מ לכולם יש בחי' אותיות עד אותיות הרצון שבמעשה כשהמעשה עולה ברצונו שיש לזה אותיות מיוחדים וכן עד\"ז בשכל שאחר הרצון שאם לא היה השכל במציאת אותיות השכל שהוא בחי' גלוי השכל במציאת איך היה השכל בא בשינוי המהות בהתפעלות האהבה הנולד מצד השכל שגם שם הוא אותו השכל שהיה טרם שהוליד האהבה רק שנתלבש במהות אהב' כו' אין זה רק ע\"י האותיות שבו וכן עד\"ז אותיות דמדות במחשב' אם לא היה המדה במציאת יש באותיות איך מתלבשת במהות מחשב' וכו' וכן אותיות המח' בדבור כו' ונמצא ע\"י האותיות יש בחי' השתלשלות עילה ועלול מעצם הנפש עד סוף מעשה ושרש האותיות הוא בעצם הנפש ממש ומכ\"ז יובן גם בשרש ומחצב האותיות בעצם הנפש שמתהווים עם עצם אור הנפש כא' כמו שמתהווה בחי כח התנועה עמו כו' וכה\"ג וד\"ל. והנמשל מכ\"ז הרי מובן ממילא דאותיות שבטה\"ע שאמר גליף גליפו<sup data-n=\"3242\">1</sup> כו' היינו בחי' אותיות העצמיי' דמח' ודבור שבעצמות אא\"ס כמו עד\"מ אותיות הקבועים בעצם הנפש דיחידה כו' בג' מדריגות הנ\"ל ואותיות הללו משתלשלים ממהות למהות כמו מרצון הפשוט שעלה במח' אנא אמלוך שלפני הצמצום עד גם ברצון ושכל ומדות דא\"ק וע\"י וא\"א ואו\"א וזו\"נ דאצי' הכל נמשך ויורד מזה לזה דרך עו\"ע בשינוי מהות<sup data-n=\"3243\">2</sup> למהות ע\"י בחי' האותיות של כל מהות שהוא בחי' גלוי היש שלו במציאת כנ\"ל עד בחי' סוף מעשה דמל' דאצי' שהוא בחי' אותיות דמעשה דמל' דאצי' עד מל' דמל' דעשי' שרש התהוות העולם השפל שלנו (כמשי\"ת בסוף הקונטרס) שנכלל הכל במ\"ש כל אשר חפץ ה' בעצמותו ממש עשה<sup data-n=\"3244\">3</sup> בפו\"מ וד\"ל:\n(לט) <b>ומעתה</b> יובן דרך כלל במה שהאותיו' נק' כלים וגם נק' לבושי' כי לכאורה בחי' הכלי הוא נחשב מן העצם גם שהוא המגביל לעצם כמו אותיות הקבועים תמיד בעצם הנפש שמתאחדים עם העצם ע\"ד דוגמא מאותיות החקוקי' בציור או בבליטה כאותיו' החותם כך ברוחניות האותיות דנפש וכמו גלוי עצם החי בכח התנוע' או כגלוי חיות המתפשט מעצם החי שקבוע כח זה בהעלם בעצמו כו' וכמו שאנו רואים באותיות השכל הכלולי' בעצם כח השכל שמיד שיוציא לאור את הסבר' מכח המשכיל שלו יצאו עמה אותיו'<sup data-n=\"3245\">4</sup> שבהם וע\"י אופן מציא' ישותו בדבר מה והוא אותיו' כל השכלה לכל מי שימציאנ' וראיה מב' בנ\"א בהשכלתם שכל וסברא א' זה יוציאנה באותיות וצרופי' כאלה וזה יוציאנה בגלוי באופני אותיו' וצרופי' אחרים (כפרושי המפרשי' לתלמוד מסבירים לשכל וסברא א' בפרש\"י ופי' התוס' ורא\"ש ור\"ן וכה\"ג בלשונות מיוחדים והכל עולה לענין ומכוין א' רק שכ\"א מפרש באותיות שכל שלו כו' כמ\"ש במ\"א<sup data-n=\"3246\">5</sup> ) כי בהולד גוף השכל יולדו עמו אותיות שלו שנרא' בהן בבחי' יש כו' ואע\"פ שמתארו ומגבילו מ\"מ נחשב עם העצם כו' וכן אותיו' הרצון ואותיות המדות כמו אהבה בלב שתתגלה בבחי' אותיות שלה שהוא בחי' אופן גלוי' במציאות בכמה אופנים שונים כמו שכל אחד שמתגלה בצירופים שונים כו' וזהו הנק' בחי' כלים שהוא בחי' היש המתאר ומגביל ונחשב עם העצם כמו כל בחי' כלים דע\"ס כלי האור דחכ' וכלי האור דחסד ונצח וכה\"ג שהוא בחי' היש והתואר שלהם כו' כידוע (וכמ\"ש באות",[["3242","1","<b>שבטה\"ע שאמר גליף גליפו</b>: ראה זהר בראשית טו, א."],["3243","2","<b>מהות</b>: אג: ממהות."],["3244","3","<b>כל אשר חפץ ה'. . עשה</b>: תהלים קלה, ו."],["3245","4","<b>השכל. . יצאו עמה אותיו'</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תתקכד."],["3246","5","<b>כמ\"ש במ\"א</b>: ראה גם שע\"ת קח, ד ובהנסמן לשם."]]],[2800530272,"כ\"ח שמהתעבות האור נעש' כלי וגם שרש הכלים קדם לאורות שנק' חומר הפשוט כו' וכמובן מהנ\"ל בהאותיו' שבעצם הנפש קדם לשרש התהוות אור עצם הרצון והתענוג כו') אך עכ\"ז גם זה אמת שהאותיות נק' ג\"כ בשם לבושים כי הנה בחי' הלבוש הוא דבר נבדל מן העצם לגמרי רק שבו מתלבש העצם כמו שהגוף מתלבש בלבוש זר ונבדל מעצמו ומכסהו ומעלימו כך האותיות של השכל אחר התהוותן במציאותן הרי העצם של השכל מתלבש ומתעלם בהם כי לא נגלה רק בחי' אותיות של השכל שהוא אופן ישותו כו' כאילו אין דבר חוץ מאופן זה ובאמת עצם אור השכל הזה איננו מובדל באופן כזה דוקא כי כמו לבוש יחליף ויתלבש באופני צירופי' שונים אחרים לגמרי וכללם<sup data-n=\"3247\">6</sup> אינם מגיעי' בעצם מהותו כלל רק שבהן מתלבש ומתגלה (ע\"ד הנ\"ל באופני גלוי שכל וסברא א' בלשונות המפרשים כו') וכך הוא באותיות הרצון שהרי רצון א' פשוט מתלבש בכמה מיני גלויי אופנים שונים ואינו רק רצון א' וכמו בלבוש יתלבש הגוף כך הרצון בא באופן גלוי שלו להחליף תמיד כו' וכמו שאנו רואי' באותי' המח' המלבישי' למדות שהאהבה שבלב שכבר באה באופן אותיות הגלוי שלה בלב הנה בבואה במחשב' הרי היא מתלבשת שם במח' זאת כגוף שמתלבש בלבוש נפרד ממש שע\"ז א' כלבוש תחליפם<sup data-n=\"3248\">7</sup> ממש שהרי לבוש המח' אינו עומד אפי' רגע שתמיד פושט ולובש ופושט ולובש כו' ממחשב' למח' כו' וכך גם אור השכל בבואו בלבוש דאותיות המחשב' ממש פושט ולובש ממחשב' למח' כו' (משא\"כ בחי' גלוי אותיות השכל בעצם הנ\"ל שנחשב עם העצם רק שנראה כמו לבוש דאותיות המחשבה ממש אחר התהוותן במציאת נבדל מן עצם השכל כו' כנ\"ל) ונמצא מובן דשניהם אמת בשרש בחי' האותיות דלפעמים הם בבחי' כלים בהיותם בשרש מחצבם באחדו' גמור עם העצם כנ\"ל וגם הם נעשים בבחי' לבושי' נפרדי' מן העצם לגמרי כנ\"ל (להיות כי שרש האותיות מבחי' המקיפי'<sup data-n=\"3249\">8</sup> שהן שרש הלבושי' ומשם ג\"כ שרש הכלי' המגבילים ומתארי' כו' כנ\"ל וכמ\"ש במ\"א) ובכ\"ז יובן למשכיל למעלה דרך כלל בכל בחי' לבושין דמחדו\"מ ג' מיני אותיות בכל פרטי הע\"ס בהשתלשלות עד רום המעלות בעצמות אור א\"ס באותיות דגליף גליפו בטהירו עילאה וכה\"ג וד\"ל:\n(מ)<sup data-n=\"3250\">9</sup> <b>ומעתה</b> יש להבין דרך פרט בבחי' שרש אותיות המח' דבינה ותבונה ולאה כו'. בהיות מבואר בזהר בכמה דוכתי דאית מח' ואית מח'<sup data-n=\"3251\">10</sup> כו' דהיינו בחי' מח' סתימאה דא\"א ומח' הקדומה דא\"ק וכה\"ג והענין הוא דהרצון נק' ג\"כ בשם מח' בלה\"ק כמו כאשר חשב<sup data-n=\"3252\">11</sup> כאשר רצה כידוע כי הרצון מלובש מיד במח' שבמוח ע\"כ הרצון והמח' של הרצון א' הוא ונק' המח' בשם רצון והרצון בשם מח' כמו כאשר עלה ברצונו היינו כשעלה במחשבתו כו' ונק' מחשבה סתימאה ע\"ש בחי' ההעלם של הרצון ע\"כ המח' שבו הרצון הוא ג\"כ בהעלם וסתימות ונק' מח' סתימאה (והוא בחי' אותיות הרצון הנ\"ל) אך הנה בחי' מח' הקדומה הוא מקדם לרצון הנעלם והוא המקור לרצון הנעלם שנק' רצון לרצון כו' וגם זה בחי' מח' הוא שמלובש בו הרצון הקדום שקדם לכל רצון לרצון (כמ\"ש באות י\"ז) אבל נק' בשם מח' הקדומה וכך יובן עד רום המעלות גם במח' דרצון הפשוט שבעצמות ממש (הנ\"ל באות יו\"ד). והנה אנו רואי' שהרצון הבא פתאום במוח הוא בא בגידי המוח במח' פשוטה ולא מורכבת מאותיות כלל כי באמת אין לרצון בחי' כלי כשאר האותיות כמו אור",[["3247","6","<b>וכללם</b>: זחיב: וכולם."],["3248","7","<b>כלבוש תחליפם</b>: תהלים קב, כז. ראה גם לעיל צז, א."],["3249","8","<b>שרש האותיות מבחי' המקיפי'</b>: ראה גם סה\"מ תקס\"ז ע' שצב."],["3250","9","<b>(מ)</b>: יב: בא כאן אות ?מא\" דלהלן. ואח\"כ בא אות מ. וראה להלן ברשימת הכת\"י."],["3251","10","<b>דאית מח' ואית מח'</b>: ראה ת\"ז תס\"ט (קט, א)."],["3252","11","<b>כאשר חשב</b>: ירמי' יח, ח [ושם: אשר חשבתי ? ראה מאמרי אדה\"א דברים ח\"א ע' רח. ח\"ב ע' תרמא]."]]],[2800530273,"השכל בכלי המוח אך בגידי המוח (שנק' נערוי\"ן הדקין ביותר שמהם כח התנועה וכח ההרגש באברים כידוע) מתפשט כח ואור הרצון גם להיות האברים נשמעי' לרצונו שבמוח כמו לפשוט ידו ורגלו או לכווצם רק עפ\"י הרצון שעולה במוח פתאום כידוע. והנה יש מח' אחרת בבחי' אותיות המח' ממש שהוא בא ע\"י בחי' בינה והשגה תחלה שנק' מח' עיוני' כמו שאנו רואי' בכל שכל וסברא שהשכלתו יושג במוח בינ' (בל\"א פאר שטאנד) שבא מיד בעיון המח' הנק' מחשבת שכל והוא כח מח' עיוני' להכיל כל עיון שכלי דוקא שאין בו רצון כלל ולא נק' מח' זו בשם רצון כלל להיותה אינה בגידי המוח כלל רק במוח הבינה ממש דהיינו בכלי ההשגה וההבנה של השכל עצמו שם יש כלי להמח' עיונית לכל השגה שכלי' והוא בחי' מל' דתבונה דהיינו סוף מדריגת אור ההשגה בעצם המביא להשגה בענין הנבדל (הנ\"ל באות ב') משם נעשה כח מחשבת שכל הנ\"ל כי תחלה באה אור השגת השכל גם בלא מח' עיונית עדיין (הנק' דער פאר נעמען אין פאר שטאנד אליין כו') טרם שחושב אור ההשכלה בלבוש דמח' ועיון עדיין אך מיד מתפשט המושג והמושכל במח' עיונית וזהו בחי' מל' דתבונה שלמעלה מבחי' אותיות המח' שנק' לאה<sup data-n=\"3253\">1</sup> (וכידוע בענין דלית רבתי דאחד<sup data-n=\"3254\">2</sup> כו' שהוא בחי' מל' דתבונ' שמאחוריי' דאימא כו' שמשם שרש התהוות המח' באותיות ממש כמ\"ש במ\"א) ובחי' ההשכלה עצמה המושגת בהשגה והבנה ג\"כ נק' מח' אך זהו בחי' התפשטו' יש דאור החכמ' הנק' חש\"ב מ\"ה<sup data-n=\"3255\">3</sup> דחכמ' ויש בחי' פנימי' מח' דבינה דלא משתמע גם במחשבת שכל לבוא לכלל אותיו' כלל במח' והוא כמו בחי' עומק המושג שלא נתפס גם בהשגה ומח' דבינה וכה\"ג (ונק' מי דלא קיימא לשאלה<sup data-n=\"3256\">4</sup> כמ\"ש במ\"א) וד\"ל. וזהו אית מח' סתימאה שברצון הנ\"ל ומח' עיונית דבינה הבאה לכלל בחי' אותיות דמח' ממש שנק' לאה כו' וכ\"ז יש גם ברצון שלמעלה מן השכל (דהיינו בחי' בינה סתימאה דא\"א שהוא בחי' מח' נעלמ' ברצון הנעלם כמו שיש שכל וחכמ' דא\"א הנעלם מכל רעיון הנעלם והוא בחי' ח\"ס דא\"א הנק' טעם כמוס לרצון כידוע כך יש בחי' בינה סתימאה כו') והוא ע\"ד מה שאנו רואי' ההפרש בין ב' מיני מחשבות הנ\"ל בגלוי שהוא ברצון הבא בגלוי במוח שיש רצון שבגידי המוח שנק' מח' סתימאה ע\"ש ההעלם של זה הרצון שבמוח טרם שבא לחו\"ב כו' ומח' עיונית שהוא בחי' יש דאין דחכמה עד שבא לכלל אותיות דמח' ממש (ולפי הנ\"ל (באות ל\"ח) בשרש הראשון של האותיות דמח' בעצם הנפש ממש הרי יש שרש לאותיות המח' דבינה ג\"כ בעצם הנפש כמו שיש אורות<sup data-n=\"3257\">5</sup> לאותיות הרצון הבאי' בגידי המוח וכה\"ג רק שזה בא לבחי' גלוי לרצון וזה בא לבחי' גלוי אותיות דבינה המושג בהשגת שכל ואמנם הרי אנו רואי' דמה שעולה ברצונו ומחשבתו הוא אשר בא עד בחי' אותיות המח' דבינה שנמשך בחי' הרצון ומח' הנעלם במח' הגלוי' דבינה) (וזהו ענין אהי' אשר אהי'<sup data-n=\"3258\">6</sup> דהתגלות כתר<sup data-n=\"3259\">7</sup> הכללי דא\"א בכתר הפרטי שהוא בבינה וכידוע ומבואר במ\"א בענין ועבד הלוי הוא<sup data-n=\"3260\">8</sup> דהתגלות ע\"י בבינה<sup data-n=\"3261\">9</sup> דוקא והוא ענין ג' קוצין דיוד<sup data-n=\"3262\">10</sup> כו' וכמ\"ש",[["3253","1","<b>המח' שנק' לאה</b>: נסמן לעיל קלג, ב."],["3254","2","<b>דלית רבתי דאחד</b>: נסמן לעיל קי, ב."],["3255","3","<b>מח'. . חש\"ב מ\"ה</b>: זהר בראשית כד, א. ת\"ז תס\"ט (קיב, ב)."],["3256","4","<b>מי דלא קיימא לשאלה</b>: זהר בהקדמה א, ב. ראה ביאוה\"ז תרומה מט, ג (נדפס גם בסה\"מ תקס\"ח ח\"א ע' קב]. אמ\"ב שער התפילין קכא, סע\"ב ואילך. תו\"ח נח נז, ג."],["3257","5","<b>אורות</b>: אג: שרש."],["3258","6","<b>אהי' אשר אהי'</b>: שמות ג, יד."],["3259","7","<b>אהי'. . כתר</b>: נסמן לעיל ס, א."],["3260","8","<b>ועבד הלוי הוא</b>: קרח יח, כג. ראה זהר קרח קעח, ב. תו\"א לך יא, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע פד ואילך. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שעה."],["3261","9","<b>דהתגלות ע\"י בבינה</b>: מובא בכ\"מ בשם הע\"ח. ראה הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' ד. תו\"ח לך פא, ב. בהערה שלפנ\"ז."],["3262","10","<b>ג' קוצין דיוד</b>: ראה גם תו\"ח שם פב, ב ובהערה 11."]]],[2800530274,"במ\"א באריכות וד\"ל):\n(מא) <b>והנה</b> ידוע בענין המא' דאימא אוזיפת מאנהא לברתא<sup data-n=\"3263\">12</sup> כו' שהוא בחי' ה\"ג<sup data-n=\"3264\">14</sup> מנצפ\"ך<sup data-n=\"3265\">13</sup> דאימא<sup data-n=\"3266\">11</sup> כו' פתוחי חותם<sup data-n=\"3267\">15</sup> שהוא בחי' צרופי התחלקות אותיות דמח' וכמ\"ש בזהר ע\"פ וקול התור נשמע בארצנו<sup data-n=\"3268\">16</sup> כו' (וכמ\"ש במ\"א) ותחלה יש להקדי' שיש ג' מדריגות במחשבה עצמה והוא בחי' מח' דמחשבה ודבור שבמחשבה ומעשה שבמח' וביאור הדברים ידוע להיות מבואר למעלה (באות הל\"ז<sup data-n=\"3269\">17</sup> ) שיש ג' מדריגות במח' ציור בלא אותיות כו' והוא כמו תינוק קטן שאין לו מח'<sup data-n=\"3270\">18</sup> בצירופי אותיות עדיין רק דמיון וציור שבמח' שנמשך מכח המדמה בלבד הגם שנמצא גם בדמיון זה התחלקות חלקי' לצייר בצמצום בדבר מיוחד אבל אינו רק בדמיון ואינו נק' מח' עדיין שיחשוב באותו דבר אשר לזה אמרו דקטן אין לו מח' כלל וגם כשיגדל מעט ויש לו צירופי התחלקות אותיות במח' אינם אותיות גמורים רק שיוכל לחשוב בצמצום בדבר הפרטי דוקא כמו לחשוב במוחו בדבר מה שנותנים לו ויבחין בינו לדבר מה זולתו עד שיחפוץ בזה וימאס בזה כידוע והוא התחלת ענין המח' ונק' מעשה שבמח' ובגדול היינו מה שחושב איך לעשות דבר ולצייר ולכתוב דרך פרט דוקא או שעולה במחשבתו כל מה שצריך לעשות בפו\"מ וגם מה שמצייר אותיו' הכתב במח' או כ\"ד<sup data-n=\"3271\">19</sup> גשם נבדל כפרי ועץ וציור כל תמונה וכה\"ג הכל נק' עשי' שבמח' ובקטן אין לו גם בחי' מח' זו רק בחי' דמיון לבד (ועכ\"ז הוא למעלה מדמיון החלומות כו') וכמ\"ש במ\"א בענין ביד הנביאי' אדמה<sup data-n=\"3272\">20</sup> בכח המדמה שבמח' בלבד לפי שבשעת השינה לא נשאר רק חלק האחרון יותר שהוא רק הדמיון שבמח' (וזהו ענין הגלות שנמשל לשינה<sup data-n=\"3273\">21</sup> כמ\"ש היינו כחולמי'<sup data-n=\"3274\">22</sup> כו' אך הן מעין הרהורי ליבא<sup data-n=\"3275\">23</sup> כו' כמ\"ש במ\"א) ובחי' דבור שבמח' הוא כמו שחושב צירופי אותיות הדבור שמדבר זולתו שזהו למטה מאותיות המח' שחושב לעצמו בלא שמיעת דבור זולתו כמו כאשר חושב צירופי אותיות אדון עולם הרי באופן צירוף מיוחד כזה עצמו כאשר שומע במחשבתו דבור זולתו כשמדבר אדון עולם אין זה רק שנחקק אותיות הדיבור זולתו במחשבתו שהוא למטה מאותיות אדון עולם שבמחשבת עצמו וכך כל מח' שחושב איך לדבר טרם שמדבר ומיד מדבר נק' דבור שבמח' וכידוע שזהו מבחי' דבור שבמח' נעשה בחי' מח' שבדבור כי ממה שחושב איך לדבר נעשה אופן המח' בעת שמתחיל לדבר מה שרצה במח' לדבר כו' משא\"כ המדריגה הג' שהוא מח' שבמח' היינו מחשבת עצמו כשחושב צירופי אותיו' אדון עולם בלא דבור או כשחושב שאר ענין דבר מה בצירופים שונים שנק' אותיות המח' אך גם בזה יש ב' מדריגו' הא' אשר גם הוא בכלל דבור שבמח' והוא כאשר אינו חושב כלל את ההשכל' והכוונה שבאותיו' א\"ע<sup data-n=\"3276\">24</sup> וכה\"ג שהוא ענין מחשבת הממשלה והאדנות ואין לו מח' כלל בזה רק צירופי האותיו' דאל\"ף דלי\"ת שבאדון וכה\"ג הגם שהוא בלא דבור שהוא למעלה משמיעת דבור א\"ע כנ\"ל מ\"מ נק' גם זה בשם דבור שבמחשב' (וכענין וקרא זא\"ז כמו באותיות המח' שלנו שהיה יכול אדם לקרוא לזולתו בשמו במח' מה שקוראו בדבור כך הוא בחי' דבור של המלאכים וכן ב' רוחות מספרות<sup data-n=\"3277\">25</sup> זע\"ז שאינו נשמע לאדם כו' וכמ\"ש במ\"א) והב' הוא המחשבה האמיתית שהוא מה שחושב את ההשכלה של הענין שבאותיות המח' שמחמתו הוא חושב מיד אופן הצירופים של אותיות הללו (כמו שאנו רואים בצירופי אותיו' המח' שמתהווים רק כפי הכוונה שבשכל אם כך וכך יתהווה אופן הצירוף כך וכך וכידוע) כמו אם כוונתו בשכל בענין דבר פרט לאיזה מסחור או בענין אדנות יחשוב בצירופים שונים כפי המכוון דוקא וזהו הנק' מח'",[["3263","12","<b>דאימא אוזיפת מאנהא לברתא</b>: ראה זהר בהקדמה ב, א."],["3264","14","<b>ה\"ג מנצפ\"ך דאימא</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'כג ואילך. נ\"ך ע' יז. וש\"נ."],["3265","13","<b>ה\"ג מנצפ\"ך</b>: ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רלז."],["3266","11","<b>(מא)</b>: א: (לא נסמן אות חדש) המשך ללפנ\"ז. בג: נסמן עוה\"פ מ\"ם. יד: מ\"ם. יב: נכלל באות לט. וראה להלן ברשימת הכת\"י."],["3267","15","<b>פתוחי חותם</b>: תצוה כח, יא. ראה לקמן קלח, א."],["3268","16","<b>וקול התור נשמע בארצנו</b>: שה\"ש ב, יב. ראה זהר וירא צז, ב. סה\"מ תקס\"ח ח\"א ע' תפח."],["3269","17","<b>הל\"ז</b>: אוצ\"ל: הל\"ח."],["3270","18","<b>קטן שאין לו מח'</b>: חולין יב, ב. ראה גם להלן קלח, א. לעיל טז, סע\"א. מאמרי אדה\"ז תקס\"ח שם. תק\"ע ע' יג. מאמרי אדה\"א ויקרא ח\"ב ע' תתקכה."],["3271","19","<b>כ\"ד</b>: ג: כל דבר."],["3272","20","<b>ביד הנביאי' אדמה</b>: הושע יב, יא. ראה גם אמ\"ב שער הק\"ש עא, ב."],["3273","21","<b>הגלות שנמשל לשינה</b>: נסמן לעיל קל, ב."],["3274","22","<b>היינו כחולמי'</b>: תהלים קכו, א."],["3275","23","<b>מעין הרהורי ליבא</b>: ראה ברכות נה, סע\"ב. לקמן קמ, א. מאמרי אדה\"א הנחות תקע\"ז ע' רמד. וש\"נ."],["3276","24","<b>א\"ע</b>: ג: אדון עולם."],["3277","25","<b>וקרא זא\"ז. . ב' רוחות מספרות</b>: ישעי' ו, ג. ברכות יח, ב. ראה גם מאמרי אדה\"ז תק\"ע ע' קו. ענינים ע' פב. ד\"מ עה, א. מאמרי אדה\"א קונטרסים ע' תקמז. וש\"נ. תו\"ח נח סז, ד."]]],[2800530275,"שבמח' שהוא הנק' כח המח' לחשוב כל ענין דבר מה בצירופים שונים (כמו כח הדבור לדבר כל מה שירצה כו' כמו שיתבאר) והיא בחי' הכלי למח' עיונית הנק' מחשבת השכל עצמו (הנ\"ל באות מ'<sup data-n=\"3278\">1</sup> ) בחי' מל' דתבונה כו' והוא המח' שתלויה בדעת דוקא ולזה א' דקטן אין לו מח' דלפי קטנות דעתו כך הוא קטנות המח' בלא צירופים כלל אבל גדלות הדעת הוא המביא למח' בריבוי צירופים שונים ולפי אופן העמקת הדעת בעומק המושג כך יהיה עומק המח' בבחי' עומק מח' עיונית הנ\"ל וכמו מה מאד עמקו מחשבותיך<sup data-n=\"3279\">2</sup> שתלוי בערך עומק המושג דבינה כו' וד\"ל:\n(מב)<sup data-n=\"3280\">3</sup> <b>ומעתה</b> יובן בענין שרש כח המחלק לצירופי אותיות דמח' במדריגה הג' כשחושב ענין דבר מה בצירופים שונים מאין הוא בא כח ההתחלקות זאת אך הנה ידוע דבחי' ה\"ג מנצפ\"ך דאימא הוא שרש כח ההתחלקות הזאת כו'. וביאור הדברים ידוע דבחי' אימא הוא בחי' בינה והשגה לאורך ורוחב בהסבר דבר המושכל וכאשר הוא מעיין בבחי' העומק של ההשגה עדיין הוא רק בעומק מח' עיונית הנ\"ל שלמעלה מהיות בחי' התחלקות צירופי אותיות ממש במח' להשכלת הענין רק בחי' מח' שכל בלבד כנראה בחוש אך ע\"י בחי' ה\"ג שהוא בחי' הצמצום והסתלקות שבכח ההשגה עצמה להיות יורד אור השכלת הענין שבמח' עיונית הנ\"ל לבחי' התחלקות צירופי' שוני' בפרטי פרטיות כו' והוא הנק' בחי' ה\"ג מנצפ\"ך דאימא שנק' פתוחי חותם כו' ואע\"פ שלכאורה בחי' ירידה וצמצום הוא אבל שרשו בא מלמעלה מכח ההשגה שבגוף המושכל הזה כו' וראי' לזה ממה שאנו רואים בתינוק קטן שאין בו עדיין צירופי אותיות במחשבתו בדבר פרטי כמו גם דבר מה שנותנין לו הגם שמבחין בו ולא יחליפנו בדבר אחר כנ\"ל שזה הוא התחלקות המח' אבל לא בצירופי אותיות כנ\"ל הנה מ\"מ כאשר יכול לדבר ולבקש בפה לדבר פרטי הרי אז יש לו בודאי במוח מחשבתו צירופי אותיות פרטי' לאותו דבר פרטי שמבקש בדבור כי צירופי אותיות מתחלקות במח' תחלה טרם בואם לדבור (כמשי\"ת דעקבי לאה נכנסין תוך ראש רחל<sup data-n=\"3281\">4</sup> דהיינו דבור שבמח' הנ\"ל שנעשה מח' לדבור כו') וכמ\"ש במ\"א בענין מאמר הזהר ע\"פ וקול התור<sup data-n=\"3282\">5</sup> נשמע בארצינו דוקא בבחי' הדבור אז זמן התחלקות אותיות המח' כו' (והיינו ענין כללות המאמר דאימא אוזיפת דרך שאלה ה\"ג מנצפ\"ך לברתא שהוא צירופי התחלקות אותיות הדבור כו') וא\"כ מזה ראי' שאין הצירופים שרשם בהשגה עצמה שהרי התינוק מבחין ומשיג בין טוב לרע גם טרם שיכול לדבר<sup data-n=\"3283\">6</sup> ואעפ\"כ אין לו צירופי אותיות במחשבתו עד שיכול לדבר דוקא כנ\"ל אלא שרשם מלמעלה מן ההשגה דבינה והוא מבחי' כח ומקור של כל עומק ההשגה כו' (כמו שבאותיות הדבור שרש כח הצירופים מאבא דהיינו מפנימיות החכמה שהוא כח המשכיל דחכמה שנק' קדמות השכל (כמ\"ש במ\"א בענין תרין ציפרין<sup data-n=\"3284\">7</sup> כמשי\"ת בעזר\"ה) ואף על פי שה\"ג מנצפ\"ך שבה' מוצאות הוא המחלק ומסדר הצירופים בדבור כפי אופן התחלקות צירופים שבמחשבה ממש מה\"ג דאימא הנ\"ל מ\"מ אבא יסד<sup data-n=\"3285\">8</sup> בבחי' כח המצרף שהוא בלתי כוונה בשכל והשגה איך לצרף רק ממילא בא וכמ\"ש מצרף לחכמה<sup data-n=\"3286\">9</sup> וכמ\"ש במ\"א וכמשי\"ת כך הוא במצרף דאותיות המח' מכח ומקור דבינה כו') ונמצא שגם שבחי' הצירופים עצמם שבמח' ע\"י בחי' צמצום דמח' עיונית הוא בא מ\"מ כח ושרש העושה לצירוף והתחלקות",[["3278","1","<b>מ'</b>: אגוייאיב ליתא."],["3279","2","<b>מה מאד עמקו מחשבותיך</b>: תהלים צב, ו [בדילוג ? ראה גם להלן קלח, ב. סה\"מ תקס\"ו ס\"ע שכג. מאמרי אדה\"א במדבר ח\"ג ע' א'פא. דברים ח\"ב ע' תא. תו\"ח ויצא קע, א]."],["3280","3","<b>(מב)</b>: אגויביד: מא. ז: נכלל באות מא דלעיל."],["3281","4","<b>דעקבי לאה. . רחל</b>: נסמן לעיל קלה, ב."],["3282","5","<b>מאמר הזהר ע\"פ וקול התור</b>: נסמן לעיל קלז, א."],["3283","6","<b>לדבר</b>: אגיאיב: ניתוסף כאן הנדפס לקמן קלח, ב שו\"ה דבינה ? (וכמ\"ש. . כו') בלא החצע\"ג. וכנראה שמקומו להלן כבנדפס."],["3284","7","<b>בענין תרין ציפרין</b>: ראה ביאוה\"ז פינחס קיג, ב ואילך."],["3285","8","<b>אבא יסד</b>: נסמן לעיל קי, ב."],["3286","9","<b>מצרף לחכמה</b>: כ\"ה בכ\"מ ? ראה לקמן קמד, א. מאמרי אדה\"א נ\"ך ע' קכ. וש\"נ. קונטרסים ע' תקמז. וש\"נ."]]],[2800530276,"זאת הרי הוא למעלה מכח ההשגה שבמח' עיונית עצמה כו' שלזה הטעם אין התינוק יכול לצרף אותיות מחשבתו עד שיוכל לצרף אותיות הדבור גם שמשיג ומבחין היטב בגוף הענין דבר מה כנ\"ל וא\"כ הרי מה שאמרו דקטן אין לו מח' היינו בבחי' צרופי אותיות המח' דוקא לפי ששרשם בא מכח ומקור של המח' דהשגה דבינה כו' וד\"ל (וזהו מן הדברים הנפלאים וסתומים למה המח' קדמה לדבור הרי הדבור שרשו בפנימיות ומקור החכמה והמח' שרשה בפנימית ומקור דבינה והחכמה קדמה לבינה שהחכמה נק' אין ובינה יש כו' (וכמ\"ש במ\"א בענין דבר ואמרת<sup data-n=\"3287\">11</sup> שהדבור גבוה בשרשו מאמירה דמח' כו' וגם מזה עצמו ראי' ממה שאין המח' באה בהתחלקות צרופים כ\"א בבוא התחלקות הדבור בתנוק כו'<sup data-n=\"3288\">10</sup> ) ואעפ\"כ ה\"ג מנצפ\"ך דבינה דוקא שרש לה\"ג התחלקו' דדבור דאימא אוזיפ' כו' וכמ\"ש כאמה בתה<sup data-n=\"3289\">12</sup> כו' ובשרשם הרי הדבור בחכמה ולכך אבא דוקא יסד ברתא כו' וגם מצד שרש הראשון דמחו\"ד<sup data-n=\"3290\">13</sup> כמו שהם קבועים בעצם הנפש הנ\"ל (באות ל\"ז<sup data-n=\"3291\">14</sup> ) שמבואר שם ג' מדריגות הנ\"ל במח' שבגלוי כו' הרי גם שם כלול תחלה אותיות המח' בעצם הנפש טרם שכלולה מאותיות הדבור שנק' רוח ממללא כו' דכמו שבנפש שבאה בגוף קדם המח' לדבור ב' שנים כך בנפש הרוחני' לא נק' רוח ממללא זמן מה כו' והמח' כבר יש בה כו' אם לא שכ\"ד הגבוה בשרשו בעצמיות יותר הוא בא באחרונה<sup data-n=\"3292\">15</sup> יותר שלזה נק' נפש המדברת דוקא נפש המשכלת<sup data-n=\"3293\">16</sup> שזהו בחי' החכמה העצמיות שבה שהוא קודם למח' העצמיות שבה כו' אבל בגלוי בא באחרונה דוקא מטעם המבואר במ\"א באריכות וד\"ל):\n(מג)<sup data-n=\"3294\">17</sup> <b>ומכל</b> הנ\"ל יובן ג\"כ הנמשל למשכיל למעלה בהתבוננות כמה פרטי' בהשתלשלות מלמעלה מעלה עד למטה מטה שנכללו כולם בכלל אל מקור הראשון שהוא כאשר עלה במחשבתו הפשוטה כו' בעצמות אא\"ס שלפני הצמצום שכלול מג' מדריגות מדו\"מ שבמחשבה הנ\"ל ובחי' מעשה שבמח' העצמית שבעצמות ממש הוא כמו ענין סוף מעשה שעלה במח' תחלה<sup data-n=\"3295\">18</sup> (ודלא כל' הרמב\"ם בידיעת עצמו יודע את הכל<sup data-n=\"3296\">19</sup> אלא מה שיודע את כל ההשתלשלות דאבי\"ע בידיעה שחוץ ממנו היינו בחי' עשי' שבמח' כמו שחושב בציור דבר נבדל הגם שאין לך דבר חוץ כו') ובחי' דבור שבמח' העצמי' הוא כמו מה ששיער בעצמו בכח<sup data-n=\"3297\">20</sup> מה שעתיד להיו' בהשתלשלו' כו' שז\"ש גליף גליפו בטה\"ע<sup data-n=\"3298\">21</sup> חקיקת אותיות בעצמו' כו' וכן מ\"ש כי הוא אמר במח' העצמי' ויהי<sup data-n=\"3299\">22</sup> ההוא אמר ולא יעשה<sup data-n=\"3300\">23</sup> ע\"י צמצום הראשון כו' וכה\"ג כי כל אמירה הוא בבחי' דבור שבמח' הנ\"ל (שלמעלה משמיעת דבור זולתו כמו הטה אזנך ושמע<sup data-n=\"3301\">24</sup> כו' ויקשב וישמע<sup data-n=\"3302\">25</sup> וכה\"ג) ומח' שבמח' העצמי' היינו כמו שמבואר למעלה במחשבת השכלת הענין בצירופי' שוני' כו' והוא כאשר עלה ברצונו ומחשבתו אנא אמלוך<sup data-n=\"3303\">26</sup> וכה\"ג והוא עפ\"י חכמתו ורצונו העצמי' כו' וזהו שאמר והיה העולם<sup data-n=\"3304\">27</sup> בבחי' מל' דא\"ס אנא אמלוך כו' (ולפ\"ז מה שנתעורר בחי' חפץ חסד הראשון ע\"י מעשה התחתוני' כו' שמחמתו עלה במחשבתו ורצונו כו' הרי הוא מגיע לתחלת התעוררות הרצון במח' העצמי' וכו') וז\"ש נפלאותיך ומחשבותיך אלינו כו' עצמו מספר<sup data-n=\"3305\">28</sup> כמ\"ש לתבונתו אין מספר<sup data-n=\"3306\">29</sup> כי לפ\"ע העמק' החכמה והדעת כן ערך העמק' בחי' המח' העצמי' בעצמות אא\"ס כמו מה מאד עמקו מחשבותיך וכנ\"ל וד\"ל. ועד\"ז יובן ג\"כ בירידת המדריגה בהשתלשלות אור הרצון ומח' דאח\"פ אחר הצמצום הראשון הנק' מק\"פ<sup data-n=\"3307\">30</sup> כו' בבחי' הארת הקו כו' שהוא בחי' הרצון ומחשבה הקדומה שצופה<sup data-n=\"3308\">31</sup> ומביט הכל",[["3287","11","<b>דבר ואמרת</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ע' קה. מאמרי אדה\"א דרושי חתונה ח\"א ע' לט."],["3288","10","<b>(וכמ\"ש. . כו')</b>: ראה לעיל קלח, א הערה לדבר."],["3289","12","<b>כאמה בתה</b>: יחזקאל טז, מד."],["3290","13","<b>דמחו\"ד</b>: ג: דמחשבה ודבור."],["3291","14","<b>ל\"ז</b>: אוצ\"ל: ל\"ח."],["3292","15","<b>שכ\"ד </b>[אג: שכל דבר]<b> הגבוה. . באחרונה</b>: ראה הנסמן לקמן קסט, ד."],["3293","16","<b>נפש המשכלת</b>: ראה תניא פ\"ג. פ\"ה. פל\"ג. פ\"נ."],["3294","17","<b>(מג)</b>: אגוזיביד: מב."],["3295","18","<b>סוף מעשה שעלה במח' תחלה</b>: ע\"פ נוסח לכה דודי."],["3296","19","<b>בידיעת עצמו יודע את הכל</b>: נסמן לעיל קכא, ב."],["3297","20","<b>ששיער בעצמו בכח</b>: נסמן לעיל קטז, ב."],["3298","21","<b>גליף גליפו בטה\"ע</b>: זהר בראשית טו, א."],["3299","22","<b>כי הוא אמר. . ויהי</b>: תהלים לג, ט."],["3300","23","<b>ההוא אמר ולא יעשה</b>: בלק כג, יט."],["3301","24","<b>הטה אזנך ושמע</b>: מלכים-ב יט, טז? ישעי' לז, יז? דניאל ט, יח [בדילוג השם]."],["3302","25","<b>ויקשב וישמע</b>: מלאכי ג, ט [בדילוג השם]."],["3303","26","<b>אנא אמלוך</b>: נסמן לעיל קטו, א."],["3304","27","<b>שאמר והי' העולם</b>: נוסח ברוך שאמר."],["3305","28","<b>נפלאותיך. . עצמו מספר</b>: תהלים מ, ו."],["3306","29","<b>לתבונתו אין מספר</b>: תהלים קמז, ה."],["3307","30","<b>הצמצום הראשון הנק' מק\"פ</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["3308","31","<b>שצופה. . בסקירה אחת</b>: נסמן לעיל קכא, ב."]]],[2800530277,"בסקירה אחת כו' שכלול ג\"כ מג' מדריגות מדו\"מ (שנק' בי\"ע<sup data-n=\"3309\">1</sup> כי המח' בבריאה והדבור ביצי' והמעשה בעשי' וכמ\"ש בראתיו יצרתיו<sup data-n=\"3310\">2</sup> כו' כידוע) עד בחי' הרצון שבמח' סתימאה דא\"ק וע\"י וא\"א כו' שבא למטה בסדר השתלשלות בדרך פרט כמשל באדם למטה שיורד הארת אור עצם המח' העצמי' הנעלמה בעצמו' הנפש בגלוי ברצון ושכל ומדות כו' עד בחי' המחשבה שמלבשת המדות שבלב שנק' לאה שכלול מג' מדריגות מחדו\"מ כו' כנ\"ל ולמעלה היינו עד בחי' אותיות מחשבותיו של מדותיו שבאצי' שנק' ז\"א שע\"ז אמר ויאמר ה' אל לבו<sup data-n=\"3311\">3</sup> אמירה זו במחשבה כו' ולפעמים נשאר הדבר במח' עלאה דז\"א שנק' אדם<sup data-n=\"3312\">4</sup> העליון כמו וינחם ה'<sup data-n=\"3313\">5</sup> כו' שחזרה זו במח' שלא הביאה לדבור ולמעשה כלל כענין ליבא לפומי' לא גליא<sup data-n=\"3314\">6</sup> וכמו צדיק ורשע לא קאמר<sup data-n=\"3315\">7</sup> כידוע וד\"ל (ודרך כללות הכל בחי' ג' מדרגות במחדו\"מ א\"ק במח' בחי' אדם דבריאה ובחי' ע\"י וא\"א בבחי' דבור אדם דיצי' ובחי' ז\"א נק' בחי' אדם דעשי'<sup data-n=\"3316\">8</sup> ובדרך פרט גם בז\"א כלול מג' מדרגות בי\"ע מחדו\"מ כו') ונמצא מובן למשכיל בכללות מכמה ריבוי פרטי' מבחי' מעשה דמח' העצמי' בעצמו' אא\"ס עד בחי' עשי' שבמח' דז\"א דאצי' וז\"ש כל אשר חפץ ה' במח' העצמית עשה<sup data-n=\"3317\">9</sup> מאין דאצי' לבריאה כו'<sup data-n=\"3318\">10</sup> ) והנה עד\"ז יובן בענין ד' רבתי דאחד<sup data-n=\"3319\">11</sup> שהוא בבחי' מל' דתבונה שמבחי' אחוריים דאימא כו' והוא ענין קשר של תש\"ר<sup data-n=\"3320\">12</sup> כו' כידוע הרי יובן דרך פרט בבחי' ז\"א שנק' אחד בבחי' אחדות דע\"ס דאצי' (בבחי' אדם דעשי' בכללות) שזהו בחי' השרש דמח' דלאה<sup data-n=\"3321\">13</sup> הבא בבחי' אותיות וצירופים הנק' מח' שבמח' (אך נקרא דלי\"ת רבתי שהוא בחי' גדלות הדבור<sup data-n=\"3322\">14</sup> להיות מבואר למעלה שיש ב' מדריגות בזה ובאמת גם זה בחי' דבור שבמח' יחשב מה שחושב המושכל בצירופים גם שלא להביא בדבור כלל והוא דלי\"ת רבתי דא\"ח ט\"ס דז\"א<sup data-n=\"3323\">15</sup> כו' שכל מדה וספירה באה באותיות וצירופים דמח' דלאה כו' מכח ושרש המחשבה בחי' מל' דתבונה כו' ולכך צריך להאריך בדלי\"ת<sup data-n=\"3324\">16</sup> להיותו שרש בחי' המל' בד' סטרי עלמא שביחו\"ת דבשכמל\"ו<sup data-n=\"3325\">17</sup> כו') וגם הנה מובן דרך כללות במחשבה הקדומה עד במח' הפשוטה דאחדות הפשוטה בעצמותו ממש בבחי' סדכ\"ס<sup data-n=\"3326\">18</sup> דלית מח' ת\"ב<sup data-n=\"3327\">19</sup> אפי' מח' דא\"ק כו' דדלי\"ת רבתי הוא כשעלה באותיות מחשבתו ורצונו הפשוט כו' שהוא בא מבחי' מל' דתבונתו העצמו' כו' וד\"ל (ומ\"ש בע\"ח דעקבי לאה נכנסין תוך ראש רחל כו' וכמארז\"ל מה שעשתה ענוה<sup data-n=\"3328\">20</sup> עקב לסולית' עשתה יראה עטרה לראשה כו' היינו בחי' דבור שבמח' שנעשית מח' שבדבור שזהו עקב ענוה כי המחשב' בהעלם ואין והדבור בגלוי ויש כו' ונעשית עטרה וכתר לרחל בחי' הדבור כי בחי' כח ושרש וראש לדבור הן צרופי אותיות שבמח' שאם יופסקו יופסק הדבור כידוע וז\"ש עקב ענוה יראת ה'<sup data-n=\"3329\">21</sup> כו' וכמ\"ש במ\"א):\n(מד)<sup data-n=\"3330\">22</sup> <b>ומעתה</b> יובן ג\"כ שרש ענין ההתחלקות דאותיות המח' מבחי' ה\"ג מנצפ\"ך כו' ולמעלה מעלה גם במח' העצמית ומח' הקדומ' ומח' סתימא' דא\"ק וא\"א כו' עד מח' דז\"א ע\"ד הנ\"ל בפרטיות הענין באדם התחתון ששרש התחלקות הצירופי' באי' מלמעל' ממקור ההשגה דבינה עצמה כו' וזהו ענין מאמר סתום ומאמר פתוח<sup data-n=\"3331\">23</sup> כמו ויאמר אלקי'<sup data-n=\"3332\">24</sup> אלקים ק\"ך צירופים<sup data-n=\"3333\">25</sup> דמח' סתימאה שבעצמות ממש נק' מאמר סתום בעצמות סדכ\"ס כו' עד רום המעלות כמו אלקי' הבין דרכה<sup data-n=\"3334\">26</sup> כו' ובחי' אלקי' הזה הוא בחי' הצמצום",[["3309","1","<b>מדו\"מ. . בי\"ע</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' רב. וש\"נ. לקמן קמה, ב."],["3310","2","<b>בראתיו יצרתיו</b>: ישעי' מג, ז."],["3311","3","<b>ויאמר ה' אל לבו</b>: נח ח, כא."],["3312","4","<b>דז\"א שנק' אדם</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח פ\"ה."],["3313","5","<b>וינחם ה'</b>: בראשית ו, ו."],["3314","6","<b>ליבא לפומי' לא גליא</b>: מדרש תהלים פט, א. קה\"ר פי\"ב, ו."],["3315","7","<b>צדיק ורשע לא קאמר</b>: נסמן לעיל קלה, א."],["3316","8","<b>א\"ק. . אדם דבריאה. . דעשי'</b>: נסמן לעיל קכב, ב."],["3317","9","<b>כל אשר חפץ ה'. . עשה</b>: תהלים קלה, ו."],["3318","10","<b>כו')</b>: א: כו'."],["3319","11","<b>ד' רבתי דאחד</b>: נסמן לעיל קי, ב."],["3320","12","<b>ד'. . קשר של תש\"ר</b>: ראה זהר (רע\"מ) פינחס רלו, ב. פע\"ח (שער התפילין) ש\"ד פ\"ה. לקו\"ת להאריז\"ל תשא לג, כג (וראית את אחורי)."],["3321","13","<b>ד' רבתי דאחד. . דלאה</b>: ראה פע\"ח (שער הק\"ש) ש\"ח פי\"ג."],["3322","14","<b>דלי\"ת רבתי. . גדלות הדבור</b>: ראה גם הנסמן במאמרי אדה\"א במדבר ח\"ג ע' א'כד."],["3323","15","<b>דא\"ח ט\"ס דז\"א</b>: ראה פע\"ח (שער הק\"ש) ש\"ח פי\"ב."],["3324","16","<b>צריך להאריך בדלי\"ת</b>: ראה ברכות יג, ב."],["3325","17","<b>שביחו\"ת דשכמל\"ו</b>: זהר בראשית יח, ב. פסחים נו, א."],["3326","18","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["3327","19","<b>דלית מח' ת\"ב</b>: ת\"ז בהקדמה (יז, א)."],["3328","20","<b>מה שעשתה ענוה</b>: ראה ע\"ח (שער לאה ורחל) של\"ח פ\"ג. מאמרי אדה\"א ויקרא ח\"א ע' רנג. וש\"נ. תו\"ח ויצא קעג, ג הערה 20."],["3329","21","<b>עקב ענוה יראת ה'</b>: משלי כב, ד."],["3330","22","<b>(מד)</b>: אגוזיביד: מג. ז: לא נסמן אות."],["3331","23","<b>מאמר סתום ומאמר פתוח</b>: שבת קד, א. ראה גם להלן (קלט, ב). לעיל לב, ב. פד, ב. קג, א. קלה, ב. מאמרי אדה\"א שמות ח\"א ע' ריג. וש\"נ. שע\"ת צא, ב ובהנסמן לשם."],["3332","24","<b>ויאמר אלקי'</b>: בראשית א, ג."],["3333","25","<b>אלקים ק\"ך צירופים</b>: ראה ע\"ח (שער הזיווגים) שט\"ו פ\"ו. (שער השמות) שער מ\"ד פ\"ה. הנסמן במאמרי אדה\"א שמות ח\"א ע' קלז."],["3334","26","<b>אלקי' הבין דרכה</b>: איוב כח, כג."]]],[2800530278,"וההסתלקות וכמארז\"ל בתחלה עלה במח'<sup data-n=\"3335\">27</sup> לברוא במדה\"ד שהוא שם אלקים<sup data-n=\"3336\">28</sup> כו' והיינו בחי' התחלקות צירופי אותיות שבמח' סתימאה ג\"כ (כמו לפי ת\"א בראשית בקדמין<sup data-n=\"3337\">29</sup> שהוא הרצון הקדום היינו הרצון שבמח' הקדומה כו' נק' בחי' אלקי' בבחי' הצמצום וההתחלקות לפי מארז\"ל דבראשית נמי מאמר<sup data-n=\"3338\">30</sup> הוא שהוא בחי' מאמר סתום במח' הסתומה עד גם בבחי' מח' הפשוטה והעצמי' כנ\"ל וכידוע דאלקים אותיות מי אלה<sup data-n=\"3339\">31</sup> שהוא בחי' התחלקות מי ברא אלה<sup data-n=\"3340\">32</sup> כו' ואלקי' עלאה בינה ומח' סתימא' דא\"א וא\"ק כו' ואלקי' תתאה בחי' מל' דתבונ' ולאה וכו' וכמ\"ש בזוהר ול\"ב ויאמר אלקי'<sup data-n=\"3341\">33</sup> הן ל\"ב שבילין<sup data-n=\"3342\">34</sup> דמתפתחין בבינה שכולן בחי' מאמר סתום דדיבור שבמח' שמזה נעשה מח' שבדיבור דמל' שנק' מאמר פתוח כמשי\"ת בענין בחי' מ\"ם סתומה ומ\"ם פתוחה כו') ואמנם הנה שרש כח ההתחלקו' הזאת אעפ\"י שהוא בא בבחי' הצמצום הנה הוא מלמעלה מכח ומקור עצם ההשגה כו' וכמ\"ש בזוהר ע\"פ וקול התור<sup data-n=\"3343\">35</sup> נשמע בארצינו כו' שהוא בחי' קול דבינה שנשמע בבחי' התחלקות צירופי' ע\"י בחי' ה\"ג מנצפ\"ך כו' שהוא בבוא האור בבחי' הדבור עלמ' דאתגלי' שנק' ארצנו כו' וכנ\"ל באריכו' ממשל התנוק שאין לו מח' בהתחלקו' אותיו' כ\"א כשידבר כו' דבזמן שיש מצרף לדבו' מחכמ' מבחי' פנימי' חכמ' אז יש מצרף לאותיו' דמח' מפנימיו' ומקור דבינ' כו' ודוקא כח העושה הצירוף הוא מבחי' מקור דבינה אבל גוף הצירופי' בפרטי אופניהם הרי הוא דווקא מכוון עפ\"י הכונה שבהשגה בפרט עפ\"י צמצום דמחשבת שכל העיונית שמסדר אופן הצירופי' כו' כנ\"ל ובאמת זהו בחי' מ\"ם פתוחה. כי הנה בבינה עצמ' יש מ\"ם סתומה ומ\"ם פתוחה<sup data-n=\"3344\">36</sup> שנק' מאמר סתום ומאמר פתוח כי כל מאמר הוא במח' דבינה עצמה והוא ענין ההפרש בין בחי' מקיפי' דאימא שהוא עדיין בבחי' מ\"ם סתומה שמקיף מכל צד והוא בריבוע דוקא כמ\"ש בזוהר על מ\"ם דלמרבה המשרה<sup data-n=\"3345\">37</sup> כו' ומבואר במ\"א ובין בחי' הארת המקיף הזה לעשות התחלקות הצירופי' ע\"י בחי' ה\"ג מנצפ\"ך כו' שהוא ענין מ\"ם פתוח' מאמר פתוח שהמח' הסתומ' נעשית פתוחה בהתחלקות אותיות כו' שזהו ענין ציור המ\"ם פתוחה כידוע. וביאור הדברים הנה ידוע בביאור ענין מקיפי' דבינה בענין והאם רובצת על האפרוחי'<sup data-n=\"3346\">38</sup> כו' שהמדות מקבלים רק מבחי' השגה דאו\"פ דבינ' כשנק' אם הבנים<sup data-n=\"3347\">39</sup> שאז נק' אפרוחי' כו' ובחי' גדלות המוחין דמדות בהעלם הבא מבחי' מקיפי' היינו כשאם הבנים רובצת כו' דהיינו להמשיך מה שלמעלה מהמוחין דבינה הנמשכים למדות (ע\"ד אהבה התלוי' בדבר<sup data-n=\"3348\">40</sup> שדבר זה בא באהבה בבחי' או\"פ ע\"כ כשבטל דבר בטלה האהבה מ\"מ נשאר בבחי' מקיף שהוא בחי' ההעלם מאותו הדבר שיוכל עי\"ז לחזור ולהתעורר ולבוא בבחי' או\"פ כידוע) שחופף עליהם והוא בריבוע שמתיישב עליהם ממש כמ\"ש במ\"א בענין מ\"ם דלמרבה<sup data-n=\"3349\">41</sup> כו' וכללות הענין הוא ע\"ד דוגמא מידיעה במוח שמקפת את הדבר שיודע אותו דהגם שהדבר נבדל מ\"מ חופף ידיעה זו ומקפת מכל צד לאותו הדבר (כמו ידיע' אלקות שמשגיח ויודע את כל הנבראים שבידיעה זו מקיף אותם כמ\"ש בלק\"א בידיעה שיודע<sup data-n=\"3350\">42</sup> כל הארץ כו') וזהו כמו מ\"ש ועל ראשי החיו'<sup data-n=\"3351\">43</sup> רקיע כעין הקרח כו' שהוא בחי' מקיף דבינ' ג\"כ (שמזה נעשה לבוש החשמ\"ל מבחי' חיצוניו' בינה כמשי\"ת) וכמ\"ש במ\"א בביאור",[["3335","27","<b>בתחלה עלה במח'</b>: נסמן לעיל קטז, ב."],["3336","28","<b>במה\"ד. . אלקים</b>: ראה רש\"י בראשית א, א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלז."],["3337","29","<b>ת\"א בראשית בקדמין</b>: בראשית א, א. ראה גם לעיל קטו, א ובהנסמן לשם."],["3338","30","<b>דבראשית נמי מאמר</b>: ר\"ה לב, א."],["3339","31","<b>דאלקים אותיות מי אלה</b>: ראה זהר בהקדמה ב, א. הנסמן במאמרי אדה\"א נ\"ך ע' תעב."],["3340","32","<b>מי ברא אלה</b>: ישעי' מ, כו."],["3341","33","<b>ול\"ב ויאמר אלקי'</b>: נסמן לעיל קלב, א."],["3342","34","<b>ל\"ב שבילין</b>: נסמן לעיל קלא, ב."],["3343","35","<b>בזוהר ע\"פ וקול התור</b>: נסמן לעיל קלז, א."],["3344","36","<b>בבינה. . מ\"ם סתומה. . פתוחה</b>: ראה פרדס (שער האותיות) שכ\"ז פט\"ז."],["3345","37","<b>בזוהר על מ\"ם דלמרבה המשרה</b>: ראה זהר תרומה קכז, א. ישעי' ט, ו. מאמרי אדה\"ז נביאים ע' עד. תו\"ח נח נז, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'רכח."],["3346","38","<b>והאם רובצת על האפרוחי'</b>: תצא כב, ו."],["3347","39","<b>דבינ'. . אם הבנים</b>: נסמן לעיל קי, ב."],["3348","40","<b>אהבה התלוי' בדבר</b>: ראה אבות פ\"ה, מט\"ז. מאמרי אדה\"א דברים ח\"ד ע' א'תצח. עט\"ר שער יוהכ\"פ ע' 68."],["3349","41","<b>בענין מ\"ם דלמרבה</b>: ראה לעיל הערה בזוהר."],["3350","42","<b>כמ\"ש בלק\"א בידיעה שיודע</b>: פמ\"ח."],["3351","43","<b>ועל ראשי החיו'</b>: יחזקאל א, כב [ושם: ודמות על ראשי החי' ? ראה הנסמן במאמרי אדה\"א שמות ח\"ב ע' תערה? לשע\"ת צב, א]."]]],[2800530279,"ענין אור מים רקיע דהשגה דבינה נקרא רקיע<sup data-n=\"3352\">1</sup> לפי שקודם שבא המושכל בבחי' השגה גמורה עדיין הוא למעלה מבחי' הגבלת אותיות כמו הסבר מושכל עמוק שאינו עדיין באופן מוגבל במוח הנק' השגה ותפיסא הוא הנק' מים דניידי<sup data-n=\"3353\">2</sup> לבא בכמה אופנים שונים כו' משא\"כ כשבא המושכל באופן מוגבל הנתפס ומושג בכלי מוחו ממש נמשל לקרח דאגלידי מיא<sup data-n=\"3354\">3</sup> וקיימא כו' מלשון השג יד<sup data-n=\"3355\">4</sup> כו' כמ\"ש במ\"א שזהו הנק' רקיע והוא ענין הקרח<sup data-n=\"3356\">5</sup> שע\"ג המוחין דחיות כו' ואמנם שרש הקרח הזה שבא דוקא בבחי' הגשמה גמורה הוא מלמעל' מבחי' או\"פ דבינה אלא הוא נמשך ונעש' מבחי' המקיף דבינה הנק' מ\"ם סתומה שבלתי מאיר ונמשך בגלוי כלל במדות ע\"כ משם נעשה בחי' רקיע או קרח ע\"ג המוחין דמדות כו' והיינו והאם רובצת כו' וכן ועל גוזליו ירחף<sup data-n=\"3357\">6</sup> כו' שזהו בחי' לבוש החשמ\"ל שמקיף בבחי' שומר למדות (כמשי\"ת בסמוך בענין כתנות עור כו' שמקיף לזו\"נ עד מתחת רגלי זו\"נ<sup data-n=\"3358\">7</sup> שממנו נעשה המסך שבין אצי' לבריאה כו') והוא בחי' מקור דבינה שמזה נמשך הכח העושה לבחי' התחלקות הצירופי' דאותיות המח' הנק' מצרף ולא גוף הצירופי' שהוא דוקא בבחי' מ\"ם פתוחה מאמר פתוח כו' וד\"ל:\n(מה) <b>והנה</b> כתיב ויעש ה' לאדם<sup data-n=\"3359\">9</sup> ולאשתו כתנות עור וילבישם שזהו בחי' החשמ\"ל דנוגה שמקיף לזו\"נ דאצי' שנק' אדם ואשתו עד מתחת רגליהם כו' כידוע ובתורתו של ר\"מ הי' כתוב אור באלף<sup data-n=\"3360\">10</sup> שזהו בחי' זיהרא עילאה<sup data-n=\"3361\">11</sup> כמ\"ש עוטה<sup data-n=\"3362\">12</sup> אור כשלמה<sup data-n=\"3363\">8</sup> שזהו אחר הבירורים דרפ\"ח כו'. ומתחלה יש להבין קצת בביאור ענין השבירה והתיקון בכללותן שהוא בבחי' האותיות שנק' כלים<sup data-n=\"3364\">13</sup> שנשברו ונפלו מצד ריבוי האור שלא הי' ביכולתם להכיל כמ\"ש בע\"ח<sup data-n=\"3365\">14</sup> וכמ\"ש אתה פוררת בעזך ים<sup data-n=\"3366\">15</sup> שזהו בחי' התהו<sup data-n=\"3367\">16</sup> שנתפררו בחי' האותיות שנק' שבירת הכלים כידוע וטעם הדבר ידוע עד\"מ עומק אור שכל שלמעל' מכלי הגבל' המוח אז ודאי יתבלבלו אותיות השכל שבמח' מצד מיעוט כחם להכיל האור כי רב הוא מהם משא\"כ כלי המוח שמכיל לאור השכל העמוק אדרבא מוגבל ומתיישב ונעלם באותיות הללו (בל\"א פאר נעמט כו') וכאשר לא יכילו אזי בהכרח שיתפרדו האותיות וכמו שמבואר במ\"א באריכות<sup data-n=\"3368\">17</sup> שזהו כמו בתיבה א' שתקצר להכיל האור הרב שבה יתפרדו האותיו' שבה אנה ואנה עד שלא יהיה מובן מזה כלום כתיבת ויאמר כשלא יכיל עומק המכוון שבו יתפרדו האותיות וישאר וי\"ו מם שבו מפורדין שלא כסדרן במקומן (כדוגמ' אותיות הרהורי לבו שביום שמתפרדין שלא במקומן ושלא כסדרן בחלומות<sup data-n=\"3369\">18</sup> שבאין רק מצרופים שמהרהר ביום בלתי מסודרין אלא אות מתיבה זו ואות מתיבה אחרת כו' ולכך החלומות שוא ידברו<sup data-n=\"3370\">19</sup> כו' וכמ\"ש במ\"א) וזה הפירור נק' שבירה לחלקים רבים וקטנים כי בבוא זה האות שנתפרר לעצמו במ\"א אין בו רק חלק מצומצם מאד מן השכל שהיה מקובץ בהיות התיבה בצירופה בשלימות כו' וגם הוא מתפרר פירור אחר פירור עד שנעשה מזה ענין זר לגמרי (כדוגמת ענין החלומות מהרהורי לבו שביום רק אעפ\"כ לא יחלום פילא<sup data-n=\"3371\">20</sup> בקופא דמחטא רק מעין",[["3352","1","<b>דבינה נקרא רקיע</b>: ראה סידור שחרית ע, א. מאמרי אדה\"א ויקרא ח\"ב ע' תנא וע' תעב."],["3353","2","<b>מים דניידי</b>: ראה עירובין מו, א."],["3354","3","<b>דאגלידי מיא</b>: ראה זהר לך עז, א."],["3355","4","<b>השג יד</b>: ערכין יז, א (במשנה)."],["3356","5","<b>רקיע. . הקרח</b>: ראה מאמרי אדה\"א נ\"ך ע' רפה ובהנסמן לשם."],["3357","6","<b>ועל גוזליו ירחף</b>: האזינו לב, יא [ושם: על ? וכ\"ה באג]."],["3358","7","<b>החשמ\"ל. . רגלי זו\"נ</b>: ראה ע\"ח (שער כללות דרושי אבי\"ע) שמ\"ב פי\"ג. הנסמן בתו\"ח נח נח, א. וראה גם לקמן (קמ, ב) הערה חיצוניות בינה. . החשמל."],["3359","9","<b>ויעש ה' לאדם</b>: בראשית ג, כא [ושם: ה\"א ? ראה סידור שחרית ס, ד. שער בהמ\"ז קטו, ב. ביאוה\"ז בלק קמט, ד. סה\"מ תקס\"ה ח\"ב ע' תתיד. מאמרי אדה\"א ויקרא ח\"ב ע' תצג]. ראה סידור שער המילה קמז, א. קמח, ד. תו\"א לך יב, ג."],["3360","10","<b>ובתורתו. . אור באלף</b>: ראה ב\"ר פ\"כ, יב. לעיל מג, א. מאמרי אדה\"א בראשית ע' תנ. במדבר ח\"ב ע' תקס. ע' תשנז. וש\"נ. דברים ח\"א ע' קטו. דרושי חתונה ח\"א ע' סו. ח\"ב ע' תקמח. הנחות תקע\"ז ע' רנג. וש\"נ."],["3361","11","<b>זיהרא עילאה</b>: ראה זהר בראשית לו, ב. לקמן קמא, ב."],["3362","12","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["3363","8","<b>(מה)</b>: אגוזיביד: מד. ז: לא נסמן אות."],["3364","13","<b>האותיות שנק' כלים</b>: נסמן לעיל קלה, ב."],["3365","14","<b>כלים שנשברו. . ריבוי האור. . בע\"ח</b>: ראה ע\"ח (שער התיקון) ש\"י פ\"ה. מאמרי אדה\"א דברים ח\"ד ע' א'תעו. וש\"נ."],["3366","15","<b>אתה פוררת בעזך ים</b>: תהלים עד, יג. ראה מאמרי אדה\"א נ\"ך ע' ה. וש\"נ."],["3367","16","<b>ים שזהו בחי' התהו</b>: ראה מאמרי אדה\"א נ\"ך שם. וש\"נ. תו\"ח וישב רו, ג."],["3368","17","<b>שמבואר במ\"א באריכות</b>: ראה מאמרי אדה\"ז נביאים ע' ה ואילך. מאמרי אדה\"א שם ע' ד ואילך."],["3369","18","<b>הרהורי לבו. . בחלומות</b>: נסמן לעיל קלז, ב."],["3370","19","<b>החלומות שוא ידברו</b>: זכרי' י, ב [ושם: וחלמות השוא ? ראה תו\"ח ויחי רמה, ד ובהערה 31]."],["3371","20","<b>לא יחלום פילא</b>: ברכות נה, ב. ראה גם תו\"ח ויצא קסט, סע\"ד. מקץ רטז, א. סה\"מ מלוקט ח\"ב ע' רסו והערה 22. אג\"ק מכ\"ק אדמו\"ר שליט\"א ח\"ג ע' רלד."]]],[2800530280,"הרהורי לבו דוקא וכמ\"ש במ\"א בענין פותר חלומו' דיוסף<sup data-n=\"3372\">21</sup> וכמשי\"ת) וכך יובן למעלה בענין שבה\"כ דאורות דתהו שזהו בחי' פירור ופיזור האותיות שלהם כמ\"ש אתה פוררת כו' והיינו שנפלו למטה מטה עד שנעש' בבחי' לבוש זר שזהו שרש ענין התהוות בחי' לבוש דחשמל כו' הנק' כתנות עור וידוע דעור זה הן בחי' ג' מיני אותיות דמחדו\"מ<sup data-n=\"3373\">22</sup> ששרשם הוא מאותיות דכלים דתהו שנתפררו וירדו למטה ונעשה בחי' לבוש ומקיף להלביש לבחי' המדו' דאדם כו' וגם שהוא נעשה בבחי' לבוש נפרד שרשו מלמעלה ממקור המוחין דבינה שבמדות וזהו ג\"כ בחי' חיצוניו' בינה שעל גוזליו ירחף לשמירה כו' שהוא מבחי' המקיף דבינה בבחי' מ\"ם סתומה הנ\"ל וד\"ל. ולהבין זה בתוס' ביאור הנה ידוע שזהו ג\"כ שרש ענין המשלים כמו ג' מאות משלים דר\"מ<sup data-n=\"3374\">23</sup> כו' ששרש המשל למעלה מן הנמשל<sup data-n=\"3375\">24</sup> כמו משלי שלמה שהן חכמות עמוקו' ביותר שאין להם בחי' כלים באותיות כ\"א בהתלבשותם בענינים זרים נבדלים הרבה מן עצם החכמה שם דוקא יושג עומק החכמה כמו שיוכלו להשיג עומק השכל רק ע\"י המשל דוקא שלא יושג גם ברבוי הסבר דברים כו' והמשל שנעשה לפי אופן הנמשל דוקא הרי בהכרח שישיג לעומק ומקור מוצא הנמשל וא\"ל לא יכוון המשל לנמשל כלל כידוע א\"כ שרש המשל במקור שכל הנמשל ולמעלה הימנו ולזה א' דברי חכמי' וחידותם<sup data-n=\"3376\">25</sup> שלפ\"ע עומק<sup data-n=\"3377\">26</sup> ומקור החכמ' כך ערך החידו' ומשלים כמו משלי' דר\"מ ומשלי שלמה וכמ\"ש במ\"א בענין וידבר ג' אלפי' משל<sup data-n=\"3378\">27</sup> דהיינו משל למשל כמ\"ש בזהר שנמצא במשל האחרון יותר שם הוא העומק והמקור היותר ראשון של הנמשל כו' וכ\"ז הוא ג\"כ בשרש בחי' האותיות שע\"י דוקא יושג היטב אור השכל כו' (וכמ\"כ יובן בענין ההגשמה של אור השכל כל שבא בהשגה והסבר בהגשמה ביותר למטה מטה שם דוקא בחי'<sup data-n=\"3379\">28</sup> העומק והמקור של גוף פנימית אור השכל כו') והיינו ג\"כ בחי' חיצוניות בינה שמזה נעשה בחי' לבוש החשמל<sup data-n=\"3380\">29</sup> דבינה<sup data-n=\"3381\">30</sup> שעל זה א' ויעש כתנות עור כו' שהוא בחי' שומר למוחין שבמדות שלא יבא לבחי' טעות (שמזה נעשה השליא לולד כו') וכמ\"ש במ\"א באריכות בענין אימא<sup data-n=\"3382\">31</sup> פרישת גדפהא<sup data-n=\"3383\">32</sup> כו' ובענין<sup data-n=\"3384\">33</sup> בשלום<sup data-n=\"3385\">34</sup> אותיות מלבוש<sup data-n=\"3386\">35</sup> כו' ובענין סכך דסוכה<sup data-n=\"3387\">36</sup> וכה\"ג וד\"ל:\n(מו)<sup data-n=\"3388\">37</sup> <b>אך</b> הנה בתורתו של ר\"מ הי' כתוב כתנות אור באלף כו' כנ\"ל להיות ידוע בשרש בחי' התיקון מבחי' שם מ\"ה החדש דא\"ק כו' וכמ\"ש במ\"א שזהו בחי' מלך השמיני<sup data-n=\"3389\">38</sup> שרש התיקון דמ\"ה דחכמה כו' (והוא בחי' יוסף<sup data-n=\"3390\">39</sup> פותר חלומות<sup data-n=\"3391\">40</sup> כי הגלות נמשל לחלום<sup data-n=\"3392\">41</sup> שהוא מעין הרהורי לבא דז\"א שהוא בבחי' שינה הנק' דורמיטא הסתלקות המוחין<sup data-n=\"3393\">42</sup> כו' ומאותיות שבדמיון החלום מצרף בהם צירופי' טובים ומתוקני' עפ\"י מקור עומק החכ' דא\"ק שבמצחא כו' וזהו תופר אותיות פורת<sup data-n=\"3394\">43</sup> ופותר<sup data-n=\"3395\">44</sup> כו' ולכך נק' אברך כמ\"ש במ\"א) והיינו אחר הבירורים דרפ\"ח ניצוצין46 שנפלו ג\"כ עם פירור ופיזור האותיות וכלי' דתהו כנ\"ל בשכל המצומצם באות הנפרד ואז נק' כתנות אור",[["3372","21","<b>פותר חלומו' דיוסף</b>: ראה גם מאמרי אדה\"ז ענינים ע' תלא. תו\"ח ויחי רמה, ג. רמח, ג."],["3373","22","<b>דעור. . אותיות דמחדו\"מ</b>: ראה גם ביאוה\"ז וישב כא, ד. תזריע עג, ב. מאמרי אדה\"א דברים ח\"ג ע' תתקכג. וש\"נ. נ\"ך ע' שיח. וש\"נ. קונטרסים ע' רט."],["3374","23","<b>ג' מאות משלים דר\"מ</b>: סנהדרין לח, ב."],["3375","24","<b>ששרש המשל למעלה מן הנמשל</b>: ראה סה\"מ תקס\"ח ח\"א ע' שצג. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תקכב ואילך. וש\"נ."],["3376","25","<b>דברי חכמי' וחידותם</b>: משלי א, ו."],["3377","26","<b>עומק</b>: אגיאיב: עיקר עומק."],["3378","27","<b>וידבר ג' אלפי' משל</b>: מלכים-א ה, יב. ראה זהר תרומה קמה, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שנ ובהנסמן לשם. תו\"ח לך פא, ד ובהערה 31. לקמן קמה, א."],["3379","28","<b>בחי'</b>: אגוייאיב: הוא בחי'."],["3380","29","<b>חיצוניות בינה. . החשמל</b>: ראה אוה\"ת נח כרך ג' ע' 1338. וראה גם לעיל הערה החשמ\"ל."],["3381","30","<b>דבינה</b>: אגזיא: ניתוסף כאן: בשלום אותיות מלבו\"ש המובא בסמוך בפנים. וראה להלן הערה 35."],["3382","31","<b>אימא פרישת גדפהא</b>: ראה זהר (רע\"מ) פינחס רנו, א. תו\"ח ויצא קע, ג. ביאוה\"ז נח ד, ג ואילך."],["3383","32","<b>גדפהא</b>: אגזייא: ניתוסף: ופרו\"ס ? ברכת השכיבנו. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תצד."],["3384","33","<b>ובענין</b>: אגוזייאיב: ליתא."],["3385","34","<b>בשלום אותיות מלבוש</b>: אגזיא. ליתא. וראה לעיל הערה 30. יב: ליתא כאן ולעיל."],["3386","35","<b>בשלום אותיות מלבוש</b>: ראה סידור האריז\"ל בסיום תפלת העמידה. עמה\"מ (שער שעשועי המלך) ש\"א פנ\"ה (ט, ג). הנסמן בתו\"ח נח נח, א הערה 15."],["3387","36","<b>ובענין סכך דסוכה</b>: ראה סידור שער הסוכות רנז, א ואילך."],["3388","37","<b>(מו)</b>: אגויב: מה. ז: לא נסמן אות."],["3389","38","<b>שם מ\"ה. . מלך השמיני</b>: ראה ע\"ח (שער התיקון) ש\"י פ\"ב. פ\"ג. תו\"א ויחי קג, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תפב."],["3390","39","<b>מלך השמיני. . יוסף</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שפו. וש\"נ. תו\"ח וישלח קפח, ד הערה 49. תורת לוי יצחק תענית ע' יא."],["3391","40","<b>יוסף פותר חלומות</b>: ראה גם תו\"ח ויחי רמג, ד ואילך."],["3392","41","<b>הגלות נמשל לחלום</b>: ראה גם סה\"מ תקס\"ה ח\"א ע' קפד. תו\"א וישב כח, ג. תו\"ח שמות ע' נב."],["3393","42","<b>דורמיטא הסתלקות המוחין</b>: ראה ע\"ח (שער הנסירה) שכ\"ט פ\"א. מבו\"ש ש\"ג ח\"ב פי\"ז. תו\"ח שמות נג, ב."],["3394","43","<b>תופר אותיות פורת</b>: ראה תו\"א וישב כט, רע\"א. לקו\"ת קרח נה, א. תו\"ח ויחי רמב, ד הערה 2."],["3395","44","<b>אותיות פורת ופותר</b>: ראה אגדת בראשית פפ\"ב. תו\"ח שם הערה 3.\n45נק' אברך: מקץ מא, מג. ראה גם סידור שער החנוכה רפ, ג. הנסמן במאמרי אדה\"א דברים ח\"א ע' ל. בראשית ע' תצ.\n46"]]],[2800530281,"באלף. וביאור הדברי' ידוע להיות דכתנות עור המלביש שנק' חשמל הרי הוא בא בבחי' הגשמה דוקא וכמו ענין המשל לנמשל (וכענין הגשמת השכל בבחי' רוב ההסבר עד שתינוק קטן ישיגו כו') והוא בחי' נוגה כמו האור המאיר באפילה שאורו ניכר שם יותר עד שנראה אורו מבהיק ביותר מאור המאיר במקום אורה כמו שאמרו שרגא בטיהרא מאי מהני<sup data-n=\"3398\">1</sup> אבל אור שרגא באישון חושך ואפילה אורו מבהיק ביותר והיינו לפי שהוא מאיר את החושך והאפילה דוקא שא\"א לומר באור הנר<sup data-n=\"3399\">3</sup> מצד עצמו שמבהיק אורו בעצם בחושך לילה יותר מביום רק מצד החושך שהוא<sup data-n=\"3400\">2</sup> היפוכו ע\"כ ניכר בו יותר אור ואין זו הבהקה אמיתית מצד עצמו רק שנראה לעין בהבהקה יותר מפני החושך דוקא שבו בא יתרון האור לעין הרואה לבד וזהו כמו הבהקת ובהירת אור האבן טוב בהיותו מצוייר בגסות החומר שהוא בהיר יותר משהוא מצוייר בחומר זך ובהיר כו' מטעם זה (וכהבנת והשגת לתכלית עומק אור השכל במשל זר שהוא ענין גס וזר דוקא מטעם זה כו') וזהו בחי' נוגה שיש בו ב' פרושי' כידוע הא' מענין נוגה אור<sup data-n=\"3401\">4</sup> או יגיה חשכי<sup data-n=\"3402\">5</sup> וכה\"ג והב' ל' בליטה<sup data-n=\"3403\">6</sup> לחוץ וכמ\"ש כאשר הוגה מן המסילה<sup data-n=\"3404\">7</sup> כו' וכן ההוגה את ה'<sup data-n=\"3405\">8</sup> כו' וכמו הגיון שבמח' כמ\"ש והגית בו<sup data-n=\"3406\">9</sup> כו' וכן והגיון לבי<sup data-n=\"3407\">10</sup> כו' ושניהם עולין לכוונה א'<sup data-n=\"3408\">11</sup> כמ\"ש במ\"א ע\"ד דוגמא מאור השמש<sup data-n=\"3409\">12</sup> המאיר בענן שאורו מוכפל שם וניכר הוא שם ביותר משניכר בגוף השמש עצמו כי מפני הזדככות גשם הענן שבהרכבת חלקי המים שבו יוכר שם האור בכל פרטי חלקיו ביותר כמו ג' גווני קשת שנק' מראה הנוג' כמ\"ש כמראה הקשת כו' כן מראה הנוגה<sup data-n=\"3410\">13</sup> ד כו' וכמו פרטי חלקי גוונין שבאבן טוב לא ניכר יפה כ\"כ כ\"א בהיותו מורכב באיזה חומר אך לא בחומר גס אלא בחומר זך וצלול שיבהיק אורו ביותר וכך הוא ענין הב' בפי' נוגה שהוא בחי' הבליט' בגשם זך שנזדכך קצת שם בולט והוגה האור כמו יגיה חשכי דוקא וכן הגיון שבמח' עיוני' שבא אור השכל בבחי' בליטה לחוץ בגשם האותיות שבהרהור המח' שאז דוקא ניכר ומושג הארת עומק השכל יותר וז\"ש והגית בו כו' והיינו ג\"כ כמו ענין המשלים שבולט ומושג שם אור השכל יותר כנ\"ל והוא בחי' נוגה דע\"ס כו' בכלל שזהו בחי' הישות המורגש ובולט (ע\"ד המבואר במ\"א בענין ראית<sup data-n=\"3411\">14</sup> איש חכם בעיניו<sup data-n=\"3412\">15</sup> כו' וכן ופלגשו ושמה ראומה<sup data-n=\"3413\">16</sup> ראו שאני בטל כו' וכהתלהבות אלקית המורגשת כו') וכ\"ז שרש בחי' החשמל שנעשה מחיצוניות דבינה (שמזה נעשו בחי' הכנפיים<sup data-n=\"3414\">17</sup> כמ\"ש על גוזליו ירחף כו' אימא פריש' גדפהא כו' ונק' כנפי שכינה<sup data-n=\"3415\">18</sup> שמשם שרש נשמות הגרים<sup data-n=\"3416\">19</sup> כו' וזהו ג\"כ ענין מאמר הזהר ע\"פ בקר אערך לך ואצפה<sup data-n=\"3417\">20</sup> דוד אתקין האי חופאה לחפאה בקר דיוסף כו' ועביד נהורא לאתלבשא כו' עד אינון דאקרון כנפין עילאין כו' כמ\"ש ביאורו במ\"א) עד שמזה נשתלשל ויורד עוד להיות בבחי' המסך ממש הנק' פרסא המפסיק ומבדיל בין אצי' לבריאה כו' והמל' בוקע המסך (כמשי\"ת) אך ענין כתנות אור באלף הוא אחר התיקון ובירור דבחי' נוגה דחשמל שהוא ע\"י בחי' ביטול",[["3398","1","<b>שרגא בטיהרא מאי מהני</b>: חולין ס, ב. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רסא. וש\"נ."],["3399","3","<b>שא\"א לומר באור הנר</b>: ראה שו\"ע אדה\"ז הל' פסח סתל\"ג ס\"ו."],["3400","2","<b>אורו. . שהוא</b>: אגיאיב: ליתא. וכנראה שזהו השמטת המעתיק."],["3401","4","<b>נוגה אור</b>: איוב כב, כח."],["3402","5","<b>יגיה חשכי</b>: שמואל-ב כב, כט. תהלים יח, כט."],["3403","6","<b>נוגה. . ל' בליטה</b>: ראה גם שע\"ת סג, א ובהנסמן במ\"מ לשם."],["3404","7","<b>כאשר הוגה מן המסילה</b>: שמואל-ב כ, יג."],["3405","8","<b>ההוגה את ה'</b>: סנהדרין צ, א (במשנה)."],["3406","9","<b>והגית בו</b>: יהושע א, ח."],["3407","10","<b>והגיון לבי</b>: תהלים יט, טו."],["3408","11","<b>ושניהם עולים לכוונה א'</b>: ראה גם אמ\"ב שער התפילין צז, ד."],["3409","12","<b>ע\"ד דוגמא מאור השמש</b>: ראה גם אמ\"ב שם. מאמרי אדה\"ז על מארז\"ל ס\"ע תעט. מאמרי אדה\"א נ\"ך ע' שנ."],["3410","13","<b>כמראה הקשת. . הנוגה</b>: יחזקאל א, כח."],["3411","14","<b>ראית</b>: ג: ראיתי ? וכ\"ה במאמרי אדה\"ז על מארז\"ל שבהערה הבאה. לקו\"ת אחרי לא, ד. חוקת סו, ג. המשך תער\"ב ח\"א ע' קעז וע' רצב."],["3412","15","<b>ראית איש חכם בעיניו</b>: משלי כו, יב. ראה מאמרי אדה\"ז על מארז\"ל ע' רטז. תקס\"ו ס\"ע צא ואילך. דר\"מ ע' 62."],["3413","16","<b>ופלגשו ושמה ראומה</b>: וירא כב, כד. ראה מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. תו\"ח נח נא, א ובהערה 5. אוה\"ת נח כרך ג ע' 1202 בשם מבוא שערים שער הקליפות [ש\"ו ח\"ב פ\"ה]."],["3414","17","<b>החשמל. . הכנפים</b>: ראה הנסמן לקמן הערה בקר."],["3415","18","<b>כנפי שכינה</b>: שבת לא, א."],["3416","19","<b>שרש נשמות הגרים</b>: ראה זהר בהקדמה יג, ריש ע\"ב. מאמרי אדה\"א הנחות תקע\"ז ע' י. וש\"נ."],["3417","20","<b>בקר אערך לך ואצפה</b>: תהלים ה, ד. ראה זהר בלק רד, ב וביאוה\"ז לשם קט, ב ואילך."]]],[2800530282,"העצמי דמ\"ה החדש דא\"ק כו' שרש התיקון הנ\"ל עד שנהפך בחי' היש המורגש דנוגה בבחי' ביטול לאין ממש כו' וכאשר היש הוא בבחי' אין הרי הוא יותר נעלה מבחי' אין דמ\"ה שבחכמה המברר כו' כמ\"ש במ\"א<sup data-n=\"3418\">21</sup> ע\"כ נק' כתנות אור כמו עוטה אור כשלמה כו' שהוא בחי' אור דתורה לאחר הבירור דמ\"ה דח\"ע שמברר לבחי' ב\"ן<sup data-n=\"3419\">22</sup> דנוגה שעולה למעלה מבחי' מ\"ה כו' (כידוע דס\"ג שהוא גס<sup data-n=\"3420\">23</sup> בו הי' השבירה<sup data-n=\"3421\">24</sup> הרי לאחר הבירור דב\"ן שנפל משבה\"כ עולה בשרשו בבחי' ס\"ג<sup data-n=\"3422\">25</sup> כו' שלמעלה משם מ\"ה<sup data-n=\"3423\">26</sup> כו') ונק' זיהרא עילאה עד\"מ אור המזוכך ביותר בלבוש זך ובהיר עד מאד שע\"י דוקא יכולים להסתכל בתוס' הבהירות והבהקה בעין היפך הענין דנגה קודם הבירור שהוא בהסתר החשך רק שמצד יתרון האור בחשך הוא נראה אור מבהיק כו' אבל הבהקת האור מצד עצם האור כאשר הלבוש עצמו עשוי מאור בהיר ומבהיק ביותר כזכוכית הבהירה ומבהיק ביותר שנק' אספקלריא דנהרא<sup data-n=\"3424\">27</sup> כו' וכה\"ג הוא הנק' זיהרא עילאה שהנשמו' מסתכלין ע\"י בזיו השכינה בג\"ע<sup data-n=\"3425\">28</sup> כו' וכמ\"ש במ\"א וד\"ל:\n(מז)<sup data-n=\"3426\">29</sup> <b>ומעתה</b> יש להבין בבחי' המל' דאצי' שנק' עולם הדבור<sup data-n=\"3427\">30</sup> בחי' רחל<sup data-n=\"3428\">31</sup> עלמא דאתגליא אימא תתאה<sup data-n=\"3429\">32</sup> והוא ה\"א אחרונה<sup data-n=\"3430\">33</sup> דשם הוי' (כידוע בענין כאמה בתה<sup data-n=\"3431\">34</sup> דה\"א עילאה דבינה אוזיפת ה\"ג מנצפ\"ך לברתא בחי' ה' מוצאות הפה דדבור כנ\"ל) ונק' מאמר פתוח כמו ויאמר אלקים<sup data-n=\"3432\">35</sup> וכמ\"ש בדבר ה' שמים<sup data-n=\"3433\">36</sup> כו' וע\"ז אמר מלכותו בכל<sup data-n=\"3434\">37</sup> כו' כידוע דהנה ידוע בענין הנסירה שד\"ו פרצופין<sup data-n=\"3435\">38</sup> היו כו' דהיינו שבחי' המל' היתה כלולה בבחי' אחוריים דז\"א כמ\"ש עצם מעצמי כו' כי מאיש לוקחה זאת<sup data-n=\"3436\">39</sup> כו' ואחר הנסיר' נבנית המל' בבנין פרצוף בפ\"ע באו\"כ כמ\"ש ויבן ה' אלקים את הצלע<sup data-n=\"3437\">40</sup> כו'. וביאור הדברים ידוע בזהר וע\"ח בכמה דוכתי דהמל' נק' עשירית<sup data-n=\"3438\">41</sup> כי נלקחה מעשיראה דכל ע\"ס דז\"א דהיינו מבחי' מל' של כל ספי' דז\"א כמו מבחי' מל' דחכמה דז\"א נמשך בחי' חכמ' דמל' ומבחי' מל' דחסד דז\"א נמשך חסד דמל' כו' ועד\"ז נבנו כל עשר ספירות דמלכות וביאור בחי' מלכות דט' ספירות דז\"א ידוע שהוא בחינת ההתגלות<sup data-n=\"3439\">42</sup> של כל מדה וספירה כשבאה בבחי' גלוי ליש ודבר מה במציאת ניכרת כו' כמו מדת אהבה כשבאה בגלוי יש כו' והנה בחי' ההתגלות הזאת העצמיו' נק' צלם וצורה העצמי' כציור העצמי דחותם וכה\"ג וכן ציור הפנים עצמו כו' והיינו בחי' הכלי' דז\"א שע\"ז אמ' איהו וגרמוהי חד<sup data-n=\"3440\">43</sup> שהוא כענין הגבול בכח וכמ\"ש למעלה (באות כ\"ט) אבל בחי' דמות בנוק' דז\"א שנק' דמות כבוד ה'<sup data-n=\"3441\">44</sup> דז\"א כידוע בענין נעשה אדם בצלמינו כדמותינו<sup data-n=\"3442\">45</sup> דצלם בדכורא ודמות בנוק' כו' והיינו ענין אתוון אתגליפו<sup data-n=\"3443\">46</sup> כו' שהוא בחי' התגלות להתגלות כאותיות החותם הנחקק בשעוה וכה\"ג כו' כך בחי' התגלות העצמו' שבמדה שבלב כשבאה בבחי' התגלות יש בדבור בה' מוצאות הפה נעשה בבחי' יש נבדל בפ\"ע שנק' יש דיש כמ\"ש במ\"א באריכות וכמו בחי' חכ' שבחסד שבלב הבא בגלוי באופן מוגבל הרי עדיין אחוז ומתאחד בעצם החכ' והחסד כו' אבל גלוי שלו",[["3418","21","<b>וכאשר היש. . אין. . במ\"א</b>: ראה גם לקו\"ת בחוקותי מז, ג. מאמרי אדה\"א דברים ח\"ב ע' תקעו."],["3419","22","<b>דמ\"ה. . שמברר לבחי' ב\"ן</b>: נסמן לעיל קלג, א."],["3420","23","<b>דס\"ג שהוא גס</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תקסו. וש\"נ. דברים ח\"ב ע' תקעח. וש\"נ. תו\"ח בראשית יג, ריש ע\"ד ובהערה 18."],["3421","24","<b>דס\"ג. . בו הי' השבירה</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח פ\"א. מאמרי אדה\"א דברים ח\"ב ע' שעט. וש\"נ. תו\"ח בראשית ט, א ובהערה 9."],["3422","25","<b>דב\"ן. . עולה. . ס\"ג</b>: ראה לקו\"ת בחוקותי מז, ג. תו\"ח בראשית טז, ג ובהערה 36."],["3423","26","<b>ס\"ג. . שלמעלה משם מ\"ה</b>: ראה ע\"ח (שער טנת\"א) ש\"ה פ\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' ה הערה ד\"ה שם."],["3424","27","<b>אספקלריא דנהרא</b>: ראה זהר נח סה, סע\"ב. סו, א."],["3425","28","<b>שהנשמו' מסתכלין. . בג\"ע</b>: ראה גם שע\"ת נח, ג ובהנסמן לשם."],["3426","29","<b>(מז)</b>: אגוזיב: מו."],["3427","30","<b>המל'. . הדבור</b>: ראה זהר לך פו, ב. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["3428","31","<b>הדיבור בחי' רחל</b>: נסמן לעיל קלג, ב."],["3429","32","<b>המל'. . אימא תתאה</b>: ראה תניא רפנ\"ב. אגה\"ק סכ\"ה (קלט, א). הנסמן במ\"מ ללקו\"ת שה\"ש יח, ב."],["3430","33","<b>המל'. . ה\"א אחרונה</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["3431","34","<b>כאמה בתה</b>: יחזקאל טז, מד. ראה לעיל קלח, ב."],["3432","35","<b>ויאמר אלקים</b>: בראשית א, ג."],["3433","36","<b>בדבר ה' שמים</b>: תהלים לג, ו."],["3434","37","<b>מלכותו בכל</b>: תהלים קג, יט [ושם ומלכותו ? וכ\"ה בא. ראה מאמרי אדה\"א במדבר ח\"ג ע' א'קכה]."],["3435","38","<b>הנסירה שד\"ו פרצופין</b>: ראה פע\"ח (שער ר\"ה) שכ\"ד פ\"א וספ\"ב."],["3436","39","<b>עצם. . לוקחה זאת</b>: בראשית ב, כג."],["3437","40","<b>ויבן. . את הצלע</b>: בראשית ב, כב."],["3438","41","<b>דהמל' נק' עשירית</b>: ראה ע\"ח שער הכללים פ\"ז. שער ההקדמות סוד מצות מעשה (קעט, א). הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תשצה. דברים ח\"ג ע' תתפג. קונטרסים ע' שנב."],["3439","42","<b>מלכות. . ההתגלות</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' תח. מאמרי אדה\"א דברים ח\"א ע' רטו ואילך. קונטרסים ע' שנג. תו\"ח מקץ רטו, ב."],["3440","43","<b>איהו וגרמוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["3441","44","<b>דמות כבוד ה'</b>: יחזקאל א, כח."],["3442","45","<b>נעשה אדם בצלמינו כדמותינו</b>: בראשית א, כו. ראה זהר שמיני לה, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קעג ואילך. תקס\"ג ח\"ב ע' עתר. שע\"ת קו, ד ואילך. מאמרי אדה\"א דברים ח\"ב ע' תקנג."],["3443","46","<b>אתוון אתגליפו</b>: ראה זהר בראשית טו, ב. מאמרי אדה\"א שמות ח\"א ע' קנט. וש\"נ. לקמן קמד, ב. לעיל פה, א."]]],[2800530283,"בדבור שזהו כמו מאמר יהי אור<sup data-n=\"3444\">1</sup> הוא מהות דבר נבדל בפ\"ע והוא בחי' חכ' שבחסד דמל' שנמשך מבחי' מל' דחכמ' דחסד שבז\"א בדרך פרט וכך הוא כל בנין פרטי' דע\"ס דמל' באו\"כ בפרצוף בפ\"ע כו' וקודם הנסירה היו ד\"ו פרצופין שכמו האחוריי' שנגרר אחר הפנים בלתי מהות בפ\"ע כך בבחי' אחוריים דכל ספי' היה נכלל בחי' התגלות דמל' כי יש בכלל מאתיים<sup data-n=\"3445\">2</sup> כו' (וכמ\"ש במ\"א בפרטי' ענין אב\"א ואב\"פ<sup data-n=\"3446\">3</sup> כו' ומ\"ד זנב היה<sup data-n=\"3447\">4</sup> כו') ומתחלה היא נקודה תח\"י ז\"א כו' כמ\"ש ותפול לפני רגליו<sup data-n=\"3448\">5</sup> וכמ\"ש בזהר ע\"פ עושי דברו אזעירת גרמה<sup data-n=\"3449\">6</sup> כנקודה כו' עד ה\"א כמלקדמין שאח\"כ נבנית בפרצוף בבחי' האצי' עד שנעשית בבחי' פב\"פ כו' כדמיון מיעוט הירח ומלוי הירח וזהו עיק' ענין בנין המל' שהוא למעל' מבנין המל' בפרצוף בבי\"ע שנסתר כל פרצופה שבבחי' אצי' עד בחי' מל' דמל' שבוקע המסך ונעשית בבחי' פרצוף בבריאה כמשי\"ת כו' וד\"ל. והנה זהו באמת ענין דלית רבתי דאחד<sup data-n=\"3450\">7</sup> שהוא בחי' גדלות פרצוף נוק' דז\"א בבחי' האצי' דוקא במוחין ומדות או\"כ (כמ\"ש ויבן ה' אלקי' את הצלע שהוא או\"א דאצי'<sup data-n=\"3451\">8</sup> דבנו לה כו' ואמרו לה זילי נטירי ביתך<sup data-n=\"3452\">9</sup> להיות ראש לבי\"ע כו') (כידוע בענין באר חפרוה שרים<sup data-n=\"3453\">10</sup> כו') והענין הוא דבחי' דבור שבמח' הנ\"ל שזהו ד' רבתי נעשה מח' שבדבור העליון דז\"א בבחי' ע\"ס או\"כ שהוא ממל' דט\"ס דז\"א כנ\"ל והיינו א\"ח ד'<sup data-n=\"3454\">11</sup> כמ\"ש במ\"א באריכות וכמ\"ש ויהי האדם לנפש חיה רוח ממללא<sup data-n=\"3455\">12</sup> שהוא דבר מלך שלטון<sup data-n=\"3456\">13</sup> בי' מאמרות ויאמר אלקים כו' כידוע ובחי' כתר דמל' דאצי' הוא בחי' כח הדבור טרם שמתפשט לדבר בבחי' שכל ומדות שבדבור שהוא ט\"ס דמל' והיינו ענין לעולם ה' דברך נצב בשמים<sup data-n=\"3457\">14</sup> בחי' ז\"א דהיינו בחי' כח הדבור שדבוק בחזה דז\"א תמיד כו' וכמ\"ש בע\"ח ומבואר במ\"א והתפשטות המל' מלבשת לתנה\"י דז\"א שהוא בחי' דלי\"ת והמל' נק' דל<sup data-n=\"3458\">15</sup> ושרש בנין המל' מחסדי' דז\"א וכמ\"ש והוכן בחסד כסאו<sup data-n=\"3459\">16</sup> וכתיב אשרי משכיל אל דל<sup data-n=\"3460\">17</sup> וחסד ח\"ס דלי\"ת<sup data-n=\"3461\">18</sup> דהמל' לית לה מגרמ' כלום<sup data-n=\"3462\">19</sup> רק מה שמקבלת מז\"א כנ\"ל בענין התגלות דהתגלו' כו' כמשל הלבנ' שמקבל' מאור השמש וכמ\"ש בזהר דסיהר' לית לה מגרמה<sup data-n=\"3463\">20</sup> כו' משא\"כ כשזו\"ן היו שוין בקומתן<sup data-n=\"3464\">21</sup> כמו שהיו קודם מיעוט הירח שנק' שני מאורות הגדולים<sup data-n=\"3465\">22</sup> וכן לע\"ל דכתיב והי' אור הלבנה<sup data-n=\"3466\">23</sup> כו' אך יש ב' מדריגות גם בבנין הנוק' הא' בבחי' האצי' שהוא ענין הנסירה כו' והב' מה שנעשית ראש לבי\"ע (והוא מ\"ש במ\"א בענין לכי ומעטי א\"ע<sup data-n=\"3467\">24</sup> כו' שזהו בחי' המל' שנעשית ראש לשועלים<sup data-n=\"3468\">25</sup> בבי\"ע כמ\"ש ואת המאור הקטן<sup data-n=\"3469\">26</sup> לממשלת הלילה ובכלל כל בחי' האצי' נק' יום<sup data-n=\"3470\">27</sup> ומדת לילה הוא בחי' המל' כשמסתתרת בראש הבריאה כמשי\"ת בסמוך בענין בשכמל\"ו כו' אחר בקיעת המסך כו' וד\"ל):\n(מח)<sup data-n=\"3471\">28</sup> <b>והנה</b> בחי' פרטו' הבנין דמל' הנק' כלה<sup data-n=\"3472\">29</sup> שכלולה מהכל<sup data-n=\"3473\">30</sup> כו' היינו מה שבבחי' הדבור מתגלה הכל בבחי' יש ודבר נבדל כאותיות הדבור שמגלה הכל והוא גם מבחי' התענוג ורצון העצמי שבעצמו' אא\"ס ממש בבחי' חפץ חסד ההיולי הנז' (באות הי') כשבא בהשתלשלות רבות עד רצון",[["3444","1","<b>מאמר יהי אור</b>: בראשית א, ג."],["3445","2","<b>יש בכלל מאתיים מנה</b>: ב\"ק עד, א."],["3446","3","<b>אב\"א ואב\"פ</b>: [ א: אחור באחור. ג: ואחור בפנים]. ראה סה\"מ תקס\"ג ח\"א ע' רכג ואילך."],["3447","4","<b>ומ\"ד זנב הי'</b>: ברכות סא, א."],["3448","5","<b>ותפול לפני רגליו</b>: אסתר ח, ג. ראה מאמרי אדה\"ז על ענינים ע' ריג ובהנסמן לשם."],["3449","6","<b>עושי דברו אזעירת גרמה</b>: תהלים קג, כ. ראה זהר בלק קצא, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תמז."],["3450","7","<b>דלית רבתי דאחד</b>: ראה גם לעיל כד, ב."],["3451","8","<b>ויבן. . או\"א דאצי'</b>: בראשית ב, כב. ראה זהר בראשית מח, ב. מט, א."],["3452","9","<b>זילי נטירי ביתך</b>: זהר בלק קפז, א."],["3453","10","<b>באר חפרוה שרים</b>: חוקת כא, יח. ראה סה\"מ תקס\"ד ע' קעג ואילך."],["3454","11","<b>א\"ח ד'</b>: נסמן לעיל קלט, א."],["3455","12","<b>ויהי האדם. . ממללא</b>: בראשית ב, ז ובתרגום אונקלוס שם."],["3456","13","<b>דבר מלך שלטון</b>: קהלת ח, ד."],["3457","14","<b>לעולם ה' דברך נצב בשמים</b>: ראה לעיל קלה, א ובהנסמן לשם."],["3458","15","<b>והמל' נק' דל</b>: נסמן בסמוך בהערה אשרי."],["3459","16","<b>והוכן בחסד כסאו</b>: ישעי' טז, ה [ושם: כסא וכ\"ה בג. ? ראה הנסמן במאמרי אדה\"א שמות ח\"ב ע' תרמג? תו\"ח ויצא קעו, א הערה 1]."],["3460","17","<b>אשרי משכיל אל דל</b>: תהלים מא, ב. ראה פע\"ח (שער הלולב) שכ\"ט פ\"ג לר\"י מערבי ד\"ה וזה פירוש. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקסט? דברים ח\"ג ע' תתעב."],["3461","18","<b>וחסד ח\"ס דלי\"ת</b>: ראה ת\"ז תכ\"ב (סז, ריש ע\"ב). מאמרי אדה\"א שמות ח\"ב ע' תרמג. וש\"נ. לעיל עד, א. ק, ב."],["3462","19","<b>דהמל' לית לה מגרמ' כלום</b>: ע\"ח (שער העקודים) ש\"ו פ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקיא."],["3463","20","<b>דסיהר' לית לה מגרמה</b>: ראה זהר תולדות קלה, סע\"ב. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' כד."],["3464","21","<b>כשזו\"ן. . שוין בקומתן</b>: ראה אוה\"ת בראשית ע' 80. וש\"נ."],["3465","22","<b>שני מאורות הגדולים</b>: בראשית א, טז. ראה סה\"מ תקס\"ה ח\"ב ע' תקצג."],["3466","23","<b>והי' אור הלבנה</b>: ישעי' ל, כו. ראה סה\"מ תקס\"ה שם. לעיל לה, א."],["3467","24","<b>לכי ומעטי א\"ע</b>: חולין ס, ב. ראה ביאוה\"ז אחרי עז, ב ואילך. מאמרי אדה\"ז על מארז\"ל ע' רכא. תקס\"ה ח\"ב ע' תקצד ואילך."],["3468","25","<b>המל' שנעשית ראש לשועלים</b>: ראה ז\"ח (מדהנ\"ע) שה\"ש עא, א. ע\"ח (שער סדר אצי') ש\"ג פ\"א. (שער סדר אבי\"ע) שמ\"ז פ\"ד. פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' קעט."],["3469","26","<b>ואת המאור הקטן</b>: בראשית א, טז."],["3470","27","<b>יום</b>: תוקן ע\"פ אגדזייא. ובמהדורת טשערנאוויץ ובכ\"י ו: מדת יום."],["3471","28","<b>(מח)</b>: אגוזיב: מז. יא: לא נסמן אות."],["3472","29","<b>דמל' הנק' כלה</b>: ראה פרדס (שער ערכי הכנויים) שכ\"ג מערכת כל כלה. ע\"ח (שער שבירת הכלים) ש\"ט פ\"א."],["3473","30","<b>כלה שכלולה מהכל</b>: ראה פירוש [קדמון ? פז] למערכת אלקות פ\"ד (ע, א). תו\"ח ויצא קעד, ב ובהערה 22. שע\"ת טז, ג."]]],[2800530284,"וחכמה ומדות דא\"ק וא\"א עד בחי' רצון וחכמה ומדות חיצוניו' הכלי' דז\"א הכל בא בבחי' המל' בחי' הדבור העליון בהתגלות יש בבחי' האצי' שע\"ז א' אני ראשון ואני אחרון<sup data-n=\"3474\">31</sup> וכן ראו כי אני אני הוא<sup data-n=\"3475\">32</sup> בחי' מל' דא\"ס במל' דאצי' סופא דכל דרגין<sup data-n=\"3476\">33</sup> כו' ותחלה יש להבין דרך פרט בפרצוף המל' מבחי' כתר שבה עד בחי' המל' שבה שבוקע המסך להיות כתר לבריאה כו' דהנה בר\"ה הוא בנין כתר הנוק' כו' והוא מה שאו' י' פסוקים מלכיות<sup data-n=\"3477\">34</sup> כו' דהיינו להמשיך בחי' התענוג והרצון למלוכה מחדש שהוא לעורר מחדש בחי' התענוג והרצון הפשוט שבעצמו' להיות אנא אמלוך<sup data-n=\"3478\">35</sup> כו' (והיינו ענין גבורי כח עושי דברו<sup data-n=\"3479\">36</sup> כו' הנז' בזהר כמ\"ש במ\"א בענין ויתנו לך כתר מלוכה<sup data-n=\"3480\">37</sup> כו') בהיות ידוע שבחי' ההתגלות בדבור הנ\"ל הוא הנק' דבר מלך והוא בחי' מדות ההתנשאו' כמ\"ש ה' מלך גאות כו' וכן מלכותך מל'<sup data-n=\"3481\">38</sup> כו' וכמו עד\"מ מדת ההתנשאות באדם שהוא בחי' מדה נבדלת מן העצמות להיות מתנשא על זולתו דוקא כו' משא\"כ שאר המדות שהן חלק ממש מן העצמו' כמו אור מדת החסד שהנפש עצמה נמשכת ומתפעלת מהחסד כי עיק' מדה זו המשכה מן העצמו' הוא כמ\"כ החכמ' נמשכת מן העצם כו' אבל מדת ההתנשאו' הגם שהנפש מתפעלת ממנה אבל העיקר שלה הוא המתהווה מן הדבר הנבדל מן העצם שהוא על זולתו ואם אין דבר זולתו לא תתעורר מדה זו כלל והגם שבחי' החסד ג\"כ להטיב חסדו לזולתו דוקא אבל מ\"מ תחלת התהוותה הוא בעצמו' גם שאין איש להטיב עמו משא\"כ בהתנשאו' שלא תתהווה בעצם מציאותה בלתי מי שיש להתנשאו' עליו וראי' לזה ממה שכל עיקר בנינה בהתפשטו' אורך ורוחב תלוי רק בביטול האנשים כשירוממוהו יעוררו לתכלית ההתנשאות ובמיעוט הביטול ימעיטו אור מדה זו כו' אבל החסד כמו שהוא בעצם כך יתפשט וגם שיהי' בו ריבוי ומיעוט עפ\"י אופן התעוררו' המקבל אם הוא מבקש ברחמנות ביותר כו' מ\"מ לא מזה יבא עיקר בנינה כו' וד\"ל. והנמשל מזה יש להבין למעלה כי כמו מלכותא דארעא כך מלכותא דרקיע<sup data-n=\"3482\">39</sup> שאין מלך בלא עם<sup data-n=\"3483\">40</sup> דוקא והגם שההתנשאות דבחי' מדת מל' למעלה הוא כשאר המדות העליונות אבל אינה המשכה ממש מבחי' העצמו' (רק מ\"מ ישנה בכח ובהעלם גדול כי בבחי' אדם גם בתינוק קטן יש בחי' ההתנשאות להתנשא על הכל גם על הבהמה שזהו בטבע תולדתו מיד כמ\"ש ורדו<sup data-n=\"3484\">41</sup> כו' כנראה בטבע התינוק שתשוקתו למשול ולרדות על חיה ובהמה ועוף כו' כמ\"ש במ\"א שזהו דוקא מבחי' אדם משא\"כ מדת החסד והרחמים שישנה בבהמה ג\"כ כנשר שהוא רחמני<sup data-n=\"3485\">42</sup> כו') הגם שנק' מדת ההתנשאות אבל עיקר בנינה הוא להתנשאות ע\"ד<sup data-n=\"3486\">43</sup> זולתו ואז נמשך תענוג ורצון גדול בהתנשאות זו ולפ\"ז יש להבין איך יתכן למעלה באלקות שאין לך דבר חוץ ממנו על מי יתנשא כו' וא\"כ בחי' בנין המל' ברצון ותענוג ומדות בבחי' פרצוף שלם בבחי' האצילות א\"א להיות כ\"א כאשר עלה ברצונו שיהיה יש נפרד לעצמו שיהיה על מי להתנשאות כו' אזי נתעורר אור מדה זו מן המאציל כו' ולזאת אמר ה'",[["3474","31","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו. ראה גם לעיל יב, א. מאמרי אדה\"א במדבר ח\"ג ע' א'קמא."],["3475","32","<b>ראו. . אני הוא</b>: האזינו לב, לט [בדילוג]."],["3476","33","<b>במל'. . סופא דכל דרגין</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."],["3477","34","<b>י' פסוקים מלכיות</b>: ראה ר\"ה לב, א. סידור תפלת ר\"ה רלח, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שס? נ\"ך ע' תקב."],["3478","35","<b>אנא אמלוך</b>: נסמן לעיל קטו, א."],["3479","36","<b>גבורי כח עושי דברו</b>: נסמן לעיל (קמב, א) הערה עושי דברו."],["3480","37","<b>ויתנו לך כתר מלוכה</b>: פיוט ויאתיו כל לעבדך (מוסף לימים נוראים אחר ובכן צדיקים). ראה גם שע\"ת קו, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתה וע' תתח."],["3481","38","<b>ה' מלך. . מלכותך מל'</b>: תהלים צג, א. קמה, יג."],["3482","39","<b>מלכותא דארעא. . דרקיע</b>: ברכות נח, א."],["3483","40","<b>שאין מלך בלא עם</b>: בחיי וישב לח, ל. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["3484","41","<b>ורדו</b>: בראשית א, כח. ראה לקו\"ת אמור לח, ב. סה\"מ תקס\"ח ח\"א ע' רנט וע' שנו. עט\"ר מא, ב. מאמרי אדה\"א קונטרסים ע' שיד. וש\"נ. הנחות תקע\"ז ע' שמג."],["3485","42","<b>כנשר שהוא רחמני</b>: ראה ירושלמי פאה פ\"א ה\"א. מאמרי אדה\"א דברים ח\"ג ע' תתעט. וש\"נ."],["3486","43","<b>ע\"ד</b>: אג: על דבר."]]],[2800530285,"מלך גאות לבש שנתלבש במדה זו להיות מלך על עם וע\"כ צריך דוקא למדה זאת לחדש אות' ממקו'<sup data-n=\"3487\">1</sup> חוצבה בכל ר\"ה דהיינו עד בחי' מח' בעצמות אא\"ס אנא אמלוך כו' בבחי' ההתנשאות שעלה בבחי' עצמותו עדיין קודם שהיה הצמצום כו' ולזה היה הצמצום הראשון הנק' מק\"פ<sup data-n=\"3488\">2</sup> כו' כדי שיהיה דבר חוץ מן העצמות שיתכן ע\"ז בחי' אור ההתנשאות דבחי' מל' דא\"ס (וכמ\"ש במ\"א בענין גמלתהו טוב<sup data-n=\"3489\">3</sup> כו' בשרש העכו\"ם<sup data-n=\"3490\">4</sup> שהפרידן מאחדותו<sup data-n=\"3491\">5</sup> בבחי' החושך והצמצום כו' כדי שיהי' בחי' מדת התפארת שמדת הת\"ת ג\"כ אינו אלא בפני איש נכרי ומרוחק דוקא כו' וד\"ל) וכך יובן בבחי' מל' דאצי' סופא דכל דרגין שבאצי' שהוא רצון ותענוג כו' של מדת ההתנשאו' להיות מלך על בי\"ע שלזה הוצרך להיות הצמצום דמסך שבין אצי' לבריאה להיות ראש לשועלים כו' כידוע והיינו אני ראשון בבחי' מל' דא\"ס ואני אחרון במל' דאצילות כי נעוץ תחלתן בסופן<sup data-n=\"3492\">6</sup> וזהו בכל ר\"ה ור\"ה כידוע וד\"ל:\n(מט)<sup data-n=\"3493\">7</sup> <b>ומעתה</b> יש להבין בפרטו' ע\"ס דמל' דאצי' שהוא בחי' התענוג והרצון הפשוט שיצא לידי גלוי באור מדה זו הוא בחי' הכתר שבה בכלל כנ\"ל ואח\"כ מתצמצם אור התענוג והרצון שלמעלה מן השכל וטעם בבחי' חו\"ב לרצון זה והוא בחי' החכמה שבמדת המל' שנק' חכמה תתאה (חכמת שלמה) חכמה בסוף ששרשה בחכמה בראש<sup data-n=\"3494\">8</sup> בבחי' חכמה העצמית שמשם נמשך חכמה לרצון זה שבמדת המל' וזהו בראשית נמי מאמר הוא<sup data-n=\"3495\">9</sup> שהוא בחי' חכמה שבדבור די' מאמרות דאלקים כידוע והוא הנק' בחי' מוחין דנוק' דז\"א כידוע ואח\"כ נמשכו בחי' המדות דמל' חג\"ת נה\"י כמו מלך במשפט יעמיד<sup data-n=\"3496\">10</sup> כו' (וכמאז\"ל י\"ב שעות הוי היום<sup data-n=\"3497\">11</sup> ג' שעות יושב ועוסק בתורה בבחי' המוחין דמדות וג\"ש יושב ודן עפ\"י המוחין כו' וג\"ש יושב וזן בחי' נה\"י כו' וכמ\"ש במ\"א באורך) וז\"ש כולם בחכמה עשית<sup data-n=\"3498\">12</sup> שהוא הכולל לכל המאמרו' דמדות פרטיות שבדבר מלך כו' וכת\"י בראשי' בחוכמת'<sup data-n=\"3499\">13</sup> כידוע ומחדש בכל יום מע\"ב עפ\"י המוחין שבמדות דמל' דאצי' שיורד' בבי\"ע בכל יום בחדושי אופנים שונים כמו שמקבלת המל' מנה\"י דז\"א כו' שמאו\"א דאצי' נמשכו מוחין חדשים לזו\"נ בכל יום כו' עד שבכל עת ושעה מתחדש אור ושפע ממקור הראשון שהוא התענוג ורצון הפשוט שבמל' דא\"ס כמ\"ש מלכותך כו' כידוע ובחי' ע\"ס דמל' לפעמים הם בבחי' הקטנות ולפעמים הם בבחי' הגדלות ע\"ד הנ\"ל בע\"ס דז\"א שיש מוחין דגדלות וקטנות במדות מאו\"א כו' עד תכלית הקטנות בנה\"י בחיצוניות הכלים כו' כך בבחי' התגלות דמל' שנבנה בפרצוף בפ\"ע לפעמי' יש בחי' גדלות המוחין במדו' מבחי' חו\"ב שבמל' עד\"מ השכל המתפשט בהרחבה במדות המתגלים בדבור ולפעמים מאיר בבחי' קטנות עד שלפעמים המדות דמל' בתכלית הקטנות (כמ\"ש בזהר ע\"פ שחורה אני<sup data-n=\"3500\">14</sup> וכו' דאזעירת גרמה ואתעבידת כנקודה כו' שזהו נקודה תח\"י וכמ\"ש ותפול לפני רגליו כנ\"ל) (וכמו ההפרש בין ימות החול לשבת דבשבת מקבלת מחג\"ת דז\"א",[["3487","1","<b>ממקו'</b>: כ\"ה בד. אג: ממקור. במהדורת טשערנאוויץ: ממקום."],["3488","2","<b>הצמצום הראשון הנק' מק\"פ</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["3489","3","<b>גמלתהו טוב</b>: משלי לא, יב. ראה ד\"ה זה לאדה\"ז לא נדפס לע\"ע ונמצא בבוך 269 יא, ב."],["3490","4","<b>העכו\"ם</b>: אג: אוה\"ע."],["3491","5","<b>שהפרידן מאחדותו</b>: ראה זהר יתרו פז, א. מאמרי אדה\"א שמות ח\"ב ע' תרלה. וש\"נ. תו\"ח נח עה, ג ובהערה 23."],["3492","6","<b>נעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א מ\"ז."],["3493","7","<b>(מט)</b>: אגוזיב: מח. יא: לא נסמן אות."],["3494","8","<b>חכמה בסוף. . בראש</b>: ראה זהר בראשית כו, ב. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תצה ואילך. וש\"נ. קונטרסים ע' ריב. וש\"נ. תו\"ח וישב רא, ג."],["3495","9","<b>בראשית נמי מאמר הוא</b>: ר\"ה לב, א."],["3496","10","<b>מלך במשפט יעמיד</b>: משלי כט, ד."],["3497","11","<b>י\"ב שעות הוי היום</b>: ראה ע\"ז ג, ב. ראה גם אמ\"ב שער הק\"ש סז, ב."],["3498","12","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["3499","13","<b>וכת\"י בראשי' בחוכמת'</b>: ראה תרגום ירושלמי לבראשית א, א."],["3500","14","<b>שחורה אני</b>: שה\"ש א, ה. ראה זהר בלק קצא, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תמז."]]],[2800530286,"כמו ימינא ושמאלא ובינייהו כלה<sup data-n=\"3501\">15</sup> כו' ולפעמים מקבלת בבחי' פב\"פ עד שביוה\"כ עולה המל' עד בחי' פנימיות ע\"י<sup data-n=\"3502\">16</sup> כו') והנה בחי' הכלים דע\"ס דמל' דאצי' הוא בחי' אותיות הדבור די' מאמרות ויש בזה ג' מדריגות ע\"ד הנ\"ל במח' והוא מח' שבדבור בחי' כלי חב\"ד דנוק' ודבור שבדבור בחי' כלי הבל הדבור למדות דדבור ומעשה שבדבור בחי' כלי נה\"י דמל' עד בחי' מל' דמל' דאצי' שבוקע המסך כו'. וביאור הדברים ידוע דמח' שבדבור היינו עד\"מ מח' שמלובש' בדבור כשאדם מדבר איזה דבר מה שבודאי בכל דבור פרטי מלובש מחשבה פרטי' שבפרטיות דבור זה כי כאופני הצרופי אותיות דמחשבה כך ממש מתנהגים אופני צרופים דדבור (וכנ\"ל דעקבי לאה נכנסים תוך ראש רחל<sup data-n=\"3503\">17</sup> דמבחי' דבור שבמח' נעשה מח' לדבור ונכלל בזה גם המח' איך לדבר בכלל ובפרט כו') וכמו בפרט דמאמר יהי אור מלובש מח' דמאמר זה ונק' מאמר סתום ג\"כ כי לא בא בגלוי רק הדבור דיהי אור ומח' זו בחי' כלי חב\"ד דמאמר זה יהי אור שהוא בחי' החסד דמל' כו' לאלף שנה הראשונים<sup data-n=\"3504\">18</sup> (כמשי\"ת) ומח' הב' דמאמר יהי רקיע במדה\"ד דמל' הוא בחי' כלי מוחין למדה זו כו' וכך בכל ו' המדות דמל' בחי' המח' שבהם הוא בחי' כלי המוחין שלהם ובחי' כלים דחג\"ת נה\"י כו' הוא בחי' דבור שבדבור שזהו עד\"מ אותיות דבר החסד או הדין שבדבור עצמו שבדבר וגזירת מלך יש בו מג' אלה חסד דין ורחמים בחי' חג\"ת והוא דבר מלך בדבור באותיות ממש והחכמה והמדות שמתגלה בו הוא בחי' הצורה שבדבור שנק' רוח ממללא נפש המדברת<sup data-n=\"3505\">19</sup> כו' כידוע ובחי' המעשה שבדבור שהוא כלי נה\"י כו' היינו מה שבא בדבור ציווי אל המעשה בפו\"מ כמו ויאמר אלקים יהי כן בפו\"מ כמו שהמלך מצוה לעשות דבר בפו\"מ שתחלה גוזר אומר בדבר המשפט שנק' דבר וגזרת המלך שכלול מחג\"ת ואח\"כ בא הפסק דין אל הציווי במעשה שנק' בחי' נה\"י ובחי' כלי דנה\"י זה הוא אותיות הדבור שמצוה רק לעשות (וכן עקימת שפתיו דהוי מעשה<sup data-n=\"3506\">20</sup> שנק' עשי' שבדבור ג\"כ הענין הוא מה שנחתך הדבור לבוא לידי פו\"מ שהפה גומר לפי שיש דבור שאינו למעשה עדיין כו') וז\"ש ויאמר אלקים יהי אור ורקיע במעשה דוקא ובחי' המעשה שנפעל מזה הדבור כמ\"ש ויהי אור וכה\"ג כדבר מלך שנעשה מזה הפועל ממש הוא ענין מל' דמל' דאצי' שאין זה רק בבוא שפע אור בבחי' מקור התהוות יש מאין ממש כו' והיינו בחי' מל' דמל' דאצי' שבוקע המסך להיות מקור לבריאה כמשי\"ת וד\"ל (וגם הוא עדיין בבחי' אצי' ונק' בחי' עשי' שבמל' דאצי' עד\"מ כח הפעולה הנבדלת מכח הפועל דגם שכח הפועל בחי' כח המעשה הוא אבל מה שיוצא מכחו בנפעל בחי' מל' דמל' הוא כמ\"ש במ\"א):\n(נ)<sup data-n=\"3507\">21</sup> <b>והנה</b> ידוע בפרטות ענין ה\"ג מנצפ\"ך<sup data-n=\"3508\">22</sup> שבדבור די' מאמרות דאימא אוזיפת<sup data-n=\"3509\">23</sup> כו' שהן ה' מוצאות הפה אחה\"ע מהגרון<sup data-n=\"3510\">24</sup> וגיכ\"ק מהחיך כו' הרי יש אותיות מיוחדי' לכל מוצא בפ\"ע והצירופים נמצאים בחיבור",[["3501","15","<b>ימינא ושמאלא ובינייהו כלה</b>: פיוט אזמר בשבחין (ליל שבת)."],["3502","16","<b>שביוה\"כ. . פנימיות ע\"י</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'קה. וש\"נ. לעיל כד, ב. נה, ב. ק, א. קה, א."],["3503","17","<b>דעקבי לאה. . ראש רחל</b>: נסמן לעיל קלה, ב."],["3504","18","<b>החסד. . לאלף שנה הראשונים</b>: נסמן לקמן קמד, א."],["3505","19","<b>נפש המדברת</b>: נסמן לעיל קלה, ב."],["3506","20","<b>עקימת שפתיו דהוי מעשה</b>: ראה ב\"מ צ, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקי."],["3507","21","<b>(נ)</b>: אגוזיב: מט. יא: לא נסמן אות."],["3508","22","<b>ה\"ג מצנפ\"ך</b>: ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רלז."],["3509","23","<b>דאימא אוזיפת</b>: ראה זהר בהקדמה ב, א."],["3510","24","<b>אחה\"ע מה גרון</b>: ראה ס\"י (מנטובה שכ\"ב) פ\"ב מ\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קה."]]],[2800530287,"והתכללות מזה לזה בכמה אופנים שונים וכמ\"ש בס\"י וקבען בפה<sup data-n=\"3511\">1</sup> כו' המליך אות<sup data-n=\"3512\">2</sup> כו' עד צא וחשוב כי מה' אותיות<sup data-n=\"3513\">3</sup> נעשה ק\"ך צירופי' כו' והן ע\"י בחי' ה\"ג המפרידות הבל הדבור כי יש בדבור חומר וצורה הבל קול הדבור חומר המורכב מאמ\"ר<sup data-n=\"3514\">4</sup> והקול מתחלק בצירופים שונים ואמנם קול א' הוא המחבר לכללות כל הצירופים יחד (כמ\"ש במ\"א בענין צווארך בחרוזים<sup data-n=\"3515\">5</sup> כמו חוט שבחרוזים של כמה אבנים שמחברם יחד וכך הוא בבחי' אותיות מח' שבדבור שיש מח' כללית המקפת ומחברת כל פרטי אותיות המח' שבכל פרטי הדבורים וכך הוא בקול שבמח' עצמה מה\"ג דאימא כו') והנה ידוע דאבא יסד ברתא<sup data-n=\"3516\">6</sup> כמ\"ש מצרף לחכמה<sup data-n=\"3517\">7</sup> כו' והיינו ע\"ד הנ\"ל במח' שגוף הצירופים בדבור הוא רק ע\"י בחי' ה\"ג המצמצם אופן השכל שבדבור שעפי\"ז דווקא יומשכו אופן הצירופים וע\"כ כפי הוראת המכוון במח' שבדבור כך יהיה דוקא אופני הצירופים משתנים בכל עת כו' והיינו מאמר דאימא דוקא אוזיפת כו' שהוא בחי' בינה אימא עילאה שנמשך באימא תתאה בחי' בינה שמלובש במח' שבדבור שהוא בפרט אופן כל צירוף שבדבור כו' אך מ\"ש מצרף לחכמה היינו שרש כח המצרף לצרופים הללו שע\"פ השכל דבינה שהרי אנו רואים שמיד שירצה לדבר בדרך אופן צירופים פרטי' איננו צריך לעיין בשכל והשגה דבינה איך לצרף שהרי התינוק שמדבר יודע מיד לצרף הדבור בלתי צריך הכנה לזה כלל כי שרש כח המצרף הזה ממילא בא מצד הארת כח מ\"ה דחכמה שלמעלה מהשגה דבינה והיינו מבחינת כח המשכיל עצמו מקור החכמה כו' (וכמ\"ש במקום אחר בענין ויהי האדם לנפש חיה<sup data-n=\"3518\">8</sup> שהוא פנימי' קדמות החכמה אז יוכל לדבר ונק' רוחא ממללא כו') והיינו המאמר דאבא יסד ברתא כידוע (ומה שאמר בראשי' נמי מאמר הוא קאי על חכמה ושכל שבמאמרו' ולא על כח המצרף שזהו בכללות כל מדבר שנק' נפש המדברת כו') והוא עיקר בחי' אדם שנק' מדבר דהיינו כח ומקור הצירוף של הדבור כמו שנק' נפש המדברת דוקא כו' (והיינו כאשר מבחי' שרש ומקור האותיות שבנפש עצמה שבאין לידי גלוי בבחי' דבור שבנפש עצמו כשנק' נפש המדברת רוח ממללא כו') ולפ\"ז הרי יובן בענין שנויי הצרופים בו' ימי המעשה דמדות דמל' דאצי' כמו מצרופי' דיום א' יהי אור בחי' חסד<sup data-n=\"3519\">9</sup> מקור אלף שנים הראשונים דבי\"ע כידוע בענין ששת ימי' עשה כו' ו' יומין עילאין<sup data-n=\"3520\">10</sup> דזו\"נ דאצי' כו' שנק' ימי עולם וימות עולם<sup data-n=\"3521\">11</sup> כו' וצירופי' דיום ב' יהי רקיע<sup data-n=\"3522\">12</sup> בחי' דין דמל' מקור דאלף שנה הב' וכידוע בפי' כי אלף שנה<sup data-n=\"3523\">13</sup> כיום אתמול כו' דהיינו ו' אלפי שנין דהוי עלמא<sup data-n=\"3524\">14</sup> שנמשכו מו' מדות דמל' כו' הרי הצרופי' משתנים ברוח ממללא דמל' שנק' נפש המדברת כמו ויאמר אלקי' כו' והייינו מפני בחי' שינוי אופן המשכת המוחין דחו\"ב במדות ובאמצעות זה משתנה ממילא אופני הצרופי' מחסד לדין בכלל ובפרט והכל ע\"י בחי' אור הארת אבא דיסד ברתא מקור המצרף כו' כנ\"ל שלמעלה מגופו של אור המוחין דחכמה שבדבור כנ\"ל עד שבפרט כמו שאמר רחב\"ד מי<sup data-n=\"3525\">15</sup>",[["3511","1","<b>וקבען בפה</b>: ראה ס\"י פ\"ב מ\"ג."],["3512","2","<b>המליך אות</b>: ראה שם פ\"ד מ\"ה ואילך."],["3513","3","<b>צא וחשוב כי מה' אותיות</b>: ראה ס\"י פ\"ד מי\"ב."],["3514","4","<b>הדבור. . מאמ\"ר</b>: נסמן לעיל קלד, ב."],["3515","5","<b>צווארך בחרוזים</b>: שה\"ש א, י. ראה מאמרי אדה\"ז תקס\"ד ע' ט. כתובים ח\"ב ע' פט. לקו\"ת שה\"ש יג, סע\"א."],["3516","6","<b>דאבא יסד ברתא</b>: נסמן לעיל קי, ב."],["3517","7","<b>מצרף לחכמה</b>: נסמן לעיל קלח, א."],["3518","8","<b>ויהי האדם לנפש חיה</b>: בראשית ב, ז. ראה תו\"א מקץ מב, רע\"ב. דר\"מ ע' עה. לעיל טז, א ואילך. לז, א."],["3519","9","<b>יהי אור בחי' חסד</b>: בראשית א, ג. ראה אוה\"ח לזהר בראשית מו, א. סידור שער הק\"ש עו, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תמו. וש\"נ. הנחות תקע\"ז ע' י. תו\"ח בראשית ח, ג."],["3520","10","<b>ששת. . ו' יומין עילאין</b>: תשא לא, יז. זהר ויחי רמז, א. אמור צד, ריש ע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ. לעיל ס, ב."],["3521","11","<b>ימי עולם וימות עולם</b>: ישעי' סג, יא. האזינו לב, ז. ראה זהר ויקרא טו, א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רכה. במדבר ח\"ב ע' שסו."],["3522","12","<b>יהי רקיע</b>: בראשית א, ו."],["3523","13","<b>כי אלף שנה</b>: תהלים צ, ד [ושם: שנים בעיניך (וכ\"ה בא) ? ראה לעיל ס, ב. מאמרי אדה\"א נ\"ך ע' שצח. וש\"נ]. ראה מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ. ח\"ג ע' תתה. וש\"נ."],["3524","14","<b>ו' אלפי שנין דהוי עלמא</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["3525","15","<b>מי שאמר לשמן וידליק</b>: תענית כה, א (כגי' הע\"י). ראה לעיל כט, ב. מאמרי אדה\"א שמות ח\"ב ע' שלב. וש\"נ. הנחות תקע\"ז ע' רכח. וש\"נ."]]],[2800530288,"שאמר לשמן וידליק כו' היינו מי שמצרף בי' מאמרו' דשם אלקי' לשמן הטבעה זו הוא יאמר צירוף אופן הטבעה זו לחומץ וידליק כו' וכמ\"ש צדיק מושל ביראת אלקים<sup data-n=\"3526\">16</sup> בק\"ך צירופים דאלקים<sup data-n=\"3527\">17</sup> כידוע והעיקר של הממשלה הזאת הוא בשינוי אופן המוחין דנוק' שזהו בחו\"ב שבי' מאמרו' ממקור החכ' ומקור הרצון וכמ\"ש כל אשר חפץ ה' עשה<sup data-n=\"3528\">18</sup> בי' מאמרו' שבדבור העליון דאצי' בבחי' עשי' דמל' דאצי' הנ\"ל ומכ\"ז יובן ג\"כ בחי' כללות ההתבוננות ברבוי פרטי' דהיינו ממקור הרצון שבמל' דא\"ס עד מל' דמל' דאצי' עד סוף מעשה ממש להיות כל אשר חפץ ה' עשה בפו\"מ כמו שהחומץ ידליק בפו\"מ וכה\"ג וד\"ל:\n(נא)<sup data-n=\"3529\">19</sup> <b>ומעתה</b> יש להבין בענין המסך שבין אצי' לבריאה<sup data-n=\"3530\">20</sup> והמל' בוקע המסך<sup data-n=\"3531\">21</sup> כו' כנ\"ל להיות ידוע בענין כי עמך מקור חיים<sup data-n=\"3532\">22</sup> באורך נראה אור שהוא הנק' אור של תולדה כמו אור הנראה מתוך המסך שעיקר האור העצמי נשאר למעלה מן המסך ואין ההארה רק מהעלם אור העצמי שנתעלם בתוך<sup data-n=\"3533\">23</sup> עובי המסך שבוקע ומאיר שנק' הארה דהארה והוא ענין אתוון אתגליפו<sup data-n=\"3534\">24</sup> כו' כצורת אות הנחקק בשעוה שנשאר בשעוה רק רושם העלם האות העצמי שבחותם כו' כך רק בחי' הארה דהארה דבחי' המל' דמל' דהיינו הבוקע ומאיר ממנה מתוך המסך כו' ונעשה כתר לבריא' כו' וזהו באורך נרא' אור כו'. וע\"ז אמרו כברייתו של עולם<sup data-n=\"3535\">25</sup> ברישא חשוכא והדר נהורא כו' וכמ\"ש ישת חשך סתרו<sup data-n=\"3536\">26</sup> כו' והוא ג\"כ בחי' הצמצו' דשם אלקים כמ\"ש שמש ומגן הוי' אלקים<sup data-n=\"3537\">27</sup> כנרתק השמש כו' (כידוע בענין ומשה נגש אל הערפל<sup data-n=\"3538\">28</sup> אשר שם האלקים כו' וכן מ\"ש יושב בסתר עליון<sup data-n=\"3539\">29</sup> בצל שדי שאמ' לעולמו די<sup data-n=\"3540\">30</sup> כו') ושרש ענין המסך הזה הוא נעשה מבחי' לבוש החשמ\"ל דחיצונית בינה שמקיף עד מתחת רגלי דזו\"נ<sup data-n=\"3541\">31</sup> כו' כנ\"ל וכמ\"ש במ\"א בענין עד הגל הזה<sup data-n=\"3542\">32</sup> כו' שזהו כדמיון גל אבנים המפסיק כו' להיות שגופו של מסך ופרגוד זה נעשה מצרופי אותיו' שנק' אבני' בס\"י<sup data-n=\"3543\">33</sup> והאותיו' שהמה בלתי מסודרי' כמו גל אבני' זע\"ז הן כמו בחי' מסך הארוג מחוטין המבדיל ומפסיק וכדוגמא שאנו רואים באותיות הדבור שכאשר הן מסודרים עפ\"י שכל מאיר בהן אור השכל להדיא שיוכל המקבל להבין כמו שמשיגו המשפיע ממש משא\"כ כשאין מסודרים לא ישיגנו המקבל כלל (וכמו אור שכל וחכמה הגנוז בהעלם במשל וחידה בענין זר לגמרי רק שמ\"מ עומד מתוכו על אותו אור השכל נק' גם זה בשם בקיעת מסך כאור השמש הנראה בבקיעת אור השחר דרך עובי הרקיע כו' וכמ\"ש במ\"א) ולהיות כי אין ערך בין אצי' לבריאה ע\"כ הוצרך להיות בחי' צמצום דמסך הזה (כמו שהוצרך להיות בחי' צמצום הראשון הנק' מק\"פ וחלל ריקן בין העצמו' דאא\"ס להיות מקור להמשכת הקו כו' כמ\"ש למעלה רק שם היה בחי' העלם והתכללו' האור בעצמו' הנק' מק\"פ ולא בחי' מסך ממש כמו דוגמ' התעלמו' הידיע' באריכות בשעה ששונה בקיצור כו' כנ\"ל לפי שהכל בבחי' עצמותו",[["3526","16","<b>צדיק מושל ביראת אלקים</b>: שמואל-ב כג, ג [ושם: יראת ? ראה מוע\"ק טז, ב ובר\"ח שם. מאמרי אדה\"א שמות ח\"א ע' קע. וש\"נ. ח\"ב ע' שלב]."],["3527","17","<b>בק\"ך צירופים דאלקים</b>: נסמן לעיל קלט, א."],["3528","18","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["3529","19","<b>(נא)</b>: אגוזיאיב: (נ)."],["3530","20","<b>המסך שבין אצי' לבריאה</b>: נסמן לעיל קטז, א."],["3531","21","<b>והמל' בוקע המסך</b>: נסמן לעיל שם."],["3532","22","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה מאמרי אדה\"א בראשית ע' קפה. דברים ח\"א ע' קעח. וש\"נ. תו\"ח וישב רה, א ובהערה 16 [וכן צ\"ל במאמרי אדה\"א הנחות תקע\"ז ע' רכז]."],["3533","23","<b>בתוך</b>: כ\"ה בגד. במהדורת טשערנאוויץ: בחוץ."],["3534","24","<b>אתוון אתגליפו</b>: ראה גם לעיל קמא, ב ובהנסמן לשם."],["3535","25","<b>כברייתו של עולם</b>: שבת עז, ב (כגי' רש\"י)."],["3536","26","<b>ישת חשך סתרו</b>: תהלים יח, יב. ראה מאמרי אדה\"א דברים ח\"ג ע' א'נז."],["3537","27","<b>שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שעהיחוה\"א פ\"ד. מאמרי אדה\"א דברים ח\"ב ע' ת. וש\"נ. נ\"ך ע' שצה. וש\"נ."],["3538","28","<b>ומשה נגש אל הערפל</b>: יתרו כ, יח. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שמב. מאמרי אדה\"א דברים ח\"ד ע' א'שעא. וש\"נ. תו\"ח בראשית לו, ג."],["3539","29","<b>יושב בסתר עליון</b>: תהלים צא, א."],["3540","30","<b>שאמ' לעולמו די</b>: ראה חגיגה יב, א (עה\"פ וישלח לה, יא). ראה גם לקו\"ת שה\"ש ד, ד (עיי\"ש)."],["3541","31","<b>החשמ\"ל. . רגלי דזו\"נ</b>: נסמן לעיל קמ, א."],["3542","32","<b>עד הגל הזה</b>: ויצא לא, נב. ראה מאמרי אדה\"ז על ענינים ס\"ע שיג ואילך. תקס\"ז ס\"ע רנ. מובא גם בספר המאמרים תר\"ן ע' שח ושם מציין גם לד\"ה להבין ע' משמח חו\"כ בס' אלה תולדות [ולע\"ע לא נתברר לאיזה ס' הכוונה]. וראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקה וע' תקלז. תו\"ח ויצא קעח, א."],["3543","33","<b>אותיו' שנק' אבני' בס\"י</b>: פ\"ד, מי\"ב. וראה גם הנסמן בתו\"ח בראשית כא, ד הערה 43."]]],[2800530289,"עדיין משא\"כ מאצי' לבריא' מבחי' בב\"ג<sup data-n=\"3544\">1</sup> להיות מקור לבע\"ג ממש הוצרך להיות מסך בהפסק גמור אבל יש בו יתרון מעל' במה שהמסך עצמו נעש' מבעל הצמצום כמו מי שעשה את המשל לנמשל או מי שעושה הצירופים דאותיות בלתי מסודרי' וכה\"ג שאין הפסק המסך הזה ענין הפסק והבדל אמיתי לעצמו רק לגבי המקבלים בלבד וכהדין קמצא דלבושי' מיניה ובי'<sup data-n=\"3545\">2</sup> כו' וכמ\"ש בלק\"א<sup data-n=\"3546\">3</sup> ) (והיינו אני ראשון בצמצום הראשון דמק\"פ ואני אחרון<sup data-n=\"3547\">4</sup> בצמצום האחרון מאצי' לבי\"ע כו' משום דסוף מעשה זו דאצי' עלה בתחלת המחשבה ורצון דמל' דא\"ס כו' וד\"ל) והנה ידוע דזהו שרש ענין בשכמל\"ו בחי' יח\"ת<sup data-n=\"3548\">5</sup> דמל' דהיינו בחי' הארת ע\"ס דמל' דאצי' בבריאה כו' בבחי' הארה דהארה הנ\"ל כמ\"ש באורך נראה אור כו' וז\"ש כי הוי' הוא האלקי'<sup data-n=\"3549\">6</sup> וכו' וכידוע בענין המאמר דכגוונא דאינון מתייחדין<sup data-n=\"3550\">7</sup> לעילא שהוא בחי' יחוד דזו\"נ בבחי' אצי' אוף הכי איהי המל' אתייחדת לתתא בכורסייא דבריאה כו' והיינו שאמרו השבטים ששרשם בו\"ק דבריא' ליעקב בעל עולם האצי' כשם שאין בלבך<sup data-n=\"3551\">8</sup> אלא אחד בבחי' יחודא עילאה דאצי' דאיהו וחיוהי וגרמוהי חד<sup data-n=\"3552\">9</sup> כו' כך אין בלבנו בבחי' מל' דאצי' בבריאה אלא אחד יחודא תתאה כו' והיינו הוי' אחד ושמו אחד<sup data-n=\"3553\">10</sup> כידוע ודרך כלל נקרא הוי' ואדני<sup data-n=\"3554\">11</sup> הוי' ואלקים<sup data-n=\"3555\">12</sup> סובב כל עלמין וממלא כל עלמין והוא הנק' ג\"כ בשמות דמ\"ה וב\"ן שם מ\"ה בז\"א<sup data-n=\"3556\">13</sup> ושם ב\"ן במלכות<sup data-n=\"3557\">14</sup> הבא בבחי' מילוי ומילוי דמילוי כו' (וענין המלוי ידוע ע\"ד דוגמא כשהאות יו\"ד בא במבטא במלוי ו\"ד זהו פי' וביאור לאות נקודה דיו\"ד הכתוב וכאשר יצטרך לפרש גם את המלוי דו\"ד יתוסף אותיו' בוא\"ו דלי\"ת וכן מילוי דוא\"ו דלי\"ת עד כמה פעמי' מלוי דמלוי כו' שכ\"ז אינו רק הילוך והשתלשלו' הארת אור השפע הבא דרך פרט דפרט יותר מן ההעלם לגלוי דגלוי עד גלוי פרט דפרט היותר אחרון ע\"ד שמבואר במ\"א בענין וידבר ג' אלפים משל שהן כמו רבוי צירופי' הבאים בהשתלשלות זא\"ז<sup data-n=\"3558\">16</sup> זה פנימי לזה כמשל לנמשל שמשתלשל ויורד כי משל של הנמשל זה צריך אליו משל כמ\"ש בזהר<sup data-n=\"3559\">15</sup> וכך הוא ענין המילוי<sup data-n=\"3560\">17</sup> הבאין בגלוי מן ההעלם כפרט היוצא מן הכלל כו' ויש בחי' מילוי בהיפך שנתעלם בהעלם תוך העלם כו' וכמ\"ש במ\"א שזהו ענין לבוש המסך כו' וד\"ל<sup data-n=\"3561\">18</sup> :\n(נב)<sup data-n=\"3562\">19</sup> <b>והנה</b> בבחי' פרטו' דע\"ס דמל' דאצי' בבריאה אחר בקיעת המסך הרי ידוע שבחי' כתר מל' דבריאה הנק' עתיק דבריאה הוא שנמשך מבחי' מל' דמל' דאצי' כו' היינו בחי' הרצון והתענוג לבחי' מקור לבריאה יש מאין ממש כמאמר כד סליק ברעותא<sup data-n=\"3563\">20</sup> למיברי עלמא דכמו שעלה ברצונו להאציל כו' כך ירד הרצון לברוא יש מאין כו' והוא הנק' כתר מל' דבריאה (כמו שמבואר במ\"א בענין ישמעאל בני ברכני<sup data-n=\"3564\">21</sup> א\"ל יהי רצון מלפניך כו' פי' ר\"י כה\"ג הי' בהיכל ק\"ק",[["3544","1","<b>בב\"ג</b>: אג: בלתי בעל גבול."],["3545","2","<b>וכהדין קמצא דלבושי' מיניה ובי'</b>: ראה ב\"ר פכ\"א, ה. הערה במאמרי אדה\"א ויקרא ח\"ב ע' תשכא."],["3546","3","<b>בלק\"א</b>: פכ\"א."],["3547","4","<b>אני ראשון. . ואני אחרון</b>: ישעי' מד, ו."],["3548","5","<b>בשכמל\"ו בחי' יח\"ת</b>: פסחים נו, א. זהר בראשית יח, ב."],["3549","6","<b>כי הוי' הוא האלקי'</b>: ואתחנן ד, לה. לט."],["3550","7","<b>דכגוונא דאינון מתייחדין</b>: ראה זהר תרומה קלה, סע\"א."],["3551","8","<b>כשם שאין בלבך</b>: פסחים נו, א. ראה מאמרי אדה\"א דברים ח\"ג ע' א'סג. וש\"נ. שע\"ת ס, ד ובהנסמן לשם."],["3552","9","<b>דאיהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה (ג, ב). הערה במאמרי אדה\"א ויקרא ח\"ב ע' תנג."],["3553","10","<b>הוי' אחד ושמו אחד</b>: זכרי' יד, ט. ראה גם לעיל ל, א. מאמרי אדה\"א בראשית ע' תקלז. וש\"נ."],["3554","11","<b>דזו\"נ. . הוי' ואדני</b>: ראה זהר (אד\"ר) נשא קכט, א. ויקרא יא, א. ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקכד. תו\"ח נח סד, ג הערה 44."],["3555","12","<b>דזו\"נ. . הוי' ואלקים</b>: ראה זהר נשא שם. בראשית כב, א. אחרי סה, א. מאמרי אדה\"א ויקרא ח\"א ע' שז."],["3556","13","<b>שם מ\"ה בז\"א</b>: ראה ע\"ח (שער ז\"א) שי\"ז, פ\"ד."],["3557","14","<b>ושם ב\"ן במלכות</b>: ראה ע\"ח (שער רפ\"ח) שי\"ח, פ\"ג. (שער הנסירה) שכ\"ט, פ\"ב. (שער תיקון הנוקבא) של\"ד, פ\"ב כלל י\"ג. (שער מ\"ן ומ\"ד) של\"ט, דרוש ז."],["3558","16","<b>זא\"ז</b>: ג: זה אחר זה."],["3559","15","<b>וידבר ג' אלפים משל. . בזהר</b>: נסמן לעיל קמ, ב."],["3560","17","<b>ענין המילוי</b>: ראה גם סידור שחרית נא, א. ביאוה\"ז תשא נג, סע\"א ואילך. ספר הערכים ח\"ב מערכת אותיות ע' ט ואילך. וש\"נ."],["3561","18","<b>וד\"ל</b>: כנצ\"ל: וד\"ל)."],["3562","19","<b>(נב)</b>: אגוזיאיב: (נא)."],["3563","20","<b>כד סליק ברעותא</b>: ראה זהר לך פו, סע\"ב."],["3564","21","<b>ישמעאל בני ברכני</b>: ברכות ז, א. ראה גם בענין ישמעאל בני ברכני מאמרי אדה\"ז אתהלך לאזניא ע' ע. ענינים ע' שפב. מאמרי אדה\"א בראשית ע' כה. נ\"ך ע' תקצט. דרושי חתונה ח\"א ע' רסא ואילך."]]],[2800530290,"דבריאה ששם יורד אור מל' דמל' דאצי' להיות כתר לבריאה ע\"כ אמר לו בני ברכני וא\"ל י\"ר מלפניך כו') ומבחי' התענוג והרצון הזה להיות הבריאה כו' נמשך בחו\"ב דרצון ותענוג הזה ונק' או\"א דבריא' ומאו\"א שהוא בחי' חו\"ב של זה הרצון והתענוג נמשכו בחי' המדות שנק' ז\"א דבריאה ומז\"א למל' דבריאה שהוא מקור המהוה עולם הבריאה נשמות ומלאכי' מאין ליש ממש כו' ויש בע\"ס דבריאה ג\"כ בחי' או\"כ ולבושי' והיכלות וכידוע בענין ז'<sup data-n=\"3565\">22</sup> היכלות<sup data-n=\"3566\">23</sup> דבריאה ובהיכל ק\"ק שהוא היכל הז'<sup data-n=\"3567\">24</sup> שם יחוד דזו\"נ כו' ומבחי' מל' דבריאה נעשה בחי' כתר וע\"י דעולם היצי'<sup data-n=\"3568\">25</sup> ג\"כ ע\"י בקיעת מסך שבין בריאה ליצי' ע\"ד הנ\"ל במסך שבין אצי' לבריאה דכמו שעלה ברצונו לברוא כך עלה ברצונו ליצי' ועשי' רק שצריך להיו' הפסק פרסא בין סוף מעשה דרצון דבריא' לתחל' הרצון דיצי' כו' וכמ\"ש לכבודי בראתיו<sup data-n=\"3569\">26</sup> יצרתיו אף עשיתיו וידוע דבי\"ע הנק' ג' עולמות הנפרדי' מאין ליש ממש היינו כדוגמת התהוות אותיות המח' ודו\"מ<sup data-n=\"3570\">27</sup> שבאי' בבחי' יש נפרד לעצמו ממש כך מבחי' אותיות המח' דמדו' האלקי' דבריאה הנק' ז\"א דבריאה כנ\"ל נבראו מזה בחי' עלמין סתימין דלא אתגליין שהן נשמות ומלאכי' דעולם הבריא' מאין ליש ממש כמו נשמת אברהם אוהבי<sup data-n=\"3571\">29</sup> מבחי' פנימי' הכלי' דחסד דז\"א שבמל' דבריאה<sup data-n=\"3572\">28</sup> ומיכאל דעולם הבריא' מבחי' חיצוניות הכלים ואותיות דחסד דז\"א דבריאה כו' וכן ג\"ע העליון דבריאה היינו מבחי' אור הכתר דבריאה שהוא התענוג העליון שנק' עתיק דבריאה שמתצמצם בבינה שבמל' דבריא' שהנשמו' דבריא' נהנין מזיו כו' (וכידוע דאימא עילאה מקננא בכורסייא<sup data-n=\"3573\">30</sup> שהוא אור בינה דאצי' ע\"י השתלשלו' רבות עד בינה דמל' דאצי' בבינה שבמל' דבריאה כו' ועד\"ז ז\"א דאצי' מקנן ביצירה<sup data-n=\"3574\">31</sup> ומל' בעשיה<sup data-n=\"3575\">32</sup> כו') וכך הוא ענין השרפים שהם בעולם הבריאה<sup data-n=\"3576\">33</sup> כו' והן בני האלקים שמתייצבים על הוי'<sup data-n=\"3577\">34</sup> שהוא בחי' ז\"א דבריאה ובחי' כלים דז\"א דבריאה הוא בחי' מט\"ט שרו של עולם<sup data-n=\"3578\">35</sup> הבריאה<sup data-n=\"3579\">36</sup> שנא' בו כי שמי בקרבו<sup data-n=\"3580\">37</sup> שהוא הוי' דז\"א דאצי' כו' (ונק' נער<sup data-n=\"3581\">38</sup> אנפי זוטרי לגבי בחי' אנפי רברבי<sup data-n=\"3582\">39</sup> בחי' ז\"א דאצי' כידוע) ובכלל נק' עולם הבריא' עולם המחשבה בחי' עלמין סתימין כו' (כמו ביו\"ד נברא העוה\"ב<sup data-n=\"3583\">40</sup> שהוא יו\"ד דמח' דבינ' דמל' דבריא' כו' ובה' נברא העוה\"ז בחי' היצירה והעשיה) ועולם היצי' עולם הדבור עלמין דאתגליין כו' (וכמו נבואות ישעי' בשרפים דבריאה שאומ' קדוש ויחזקאל<sup data-n=\"3584\">41</sup><sup data-n=\"3585\">43</sup> בחיות ואופני' שאומרים ברוך<sup data-n=\"3586\">42</sup> כו') וע\"ד הנ\"ל בע\"ס דבריאה כך הוא בע\"ס דיצי' וע\"ס דעשי' דרך פרטי פרטיות באו\"כ ולבושי' והיכלות כו' והתהוות המלאכים ונשמות דיצי' הוא כמו סנד\"ל<sup data-n=\"3587\">44</sup> כו' שכל<sup data-n=\"3588\">45</sup> נבואת הנביאים מבחי' נו\"ה דז\"א דיצי'<sup data-n=\"3589\">46</sup> כידוע ועד\"ז יש מסך מפסיק בין יצי' לעשי'<sup data-n=\"3590\">47</sup> ובחי' מל' דמל' דיצי' נעשה כתר וע\"י לעשי'<sup data-n=\"3591\">48</sup> שזהו מ\"ש כל אשר חפץ ה' עשה והן נשמות ומלאכים דעשי' ובחי' ג\"ע התחתון דעשי' עד האופנים",[["3565","22","<b>ז' היכלות דבריאה</b>: ראה ע\"ח (שער פנימיות וחיצוניות) ש\"מ, דרוש יג."],["3566","23","<b>היכלות</b>: ראה סה\"מ תקס\"ה ח\"ב ע' תתה. מאמרי אדה\"א במדבר ח\"ג ע' תתקצה ואילך."],["3567","24","<b>ובהיכל ק\"ק שהוא היכל הז'</b>: ראה זהר (היכלות) פקודי רנח, סע\"ב ואילך. ע\"ח (שער כסא הכבוד) שמ\"ו, פ\"א. פ\"ה."],["3568","25","<b>מל' דבריאה. . כתר. . היצי'</b>: ראה ע\"ח שם פ\"ב. פ\"ה ופ\"ו."],["3569","26","<b>לכבודי בראתיו</b>: נסמן לעיל קלב, ב."],["3570","27","<b>בראתיו. . דבי\"ע. . המח' ודו\"מ</b>: ראה גם לעיל קלט, א ובהנסמן לשם."],["3571","29","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["3572","28","<b>נשמת אברהם. . דבריאה</b>: ראה אגה\"ק סט\"ו. סה\"מ תקס\"ה ח\"ב ע' רעו (נוסחא שני')."],["3573","30","<b>דאימא עילאה מקננא בכורסייא</b>: נסמן לעיל קיב, ב."],["3574","31","<b>ז\"א. . מקנן ביצירה</b>: ראה ת\"ז ת\"ו (כג, א). מאמרי אדה\"ז הקצרים ע' תקנב. הנסמן במאמרי אדה\"א נ\"ך ע' יד."],["3575","32","<b>ומל' בעשי'</b>: ראה ת\"ז שם."],["3576","33","<b>השרפים שהם בעולם הבריאה</b>: ראה ע\"ח (שער פנימיות וחיצונית) ש\"מ, דרוש יג. לעיל קה, ב. הנסמן במ\"מ לשע\"ת ח\"א סב, א."],["3577","34","<b>בני האלקים שמתייצבים על הוי'</b>: ראה גם אוה\"ת אחרי כרך ב ע' תקמ (ס\"ג)."],["3578","35","<b>מט\"ט שרו על עולם</b>: ראה תוס' יבמות טז, ב. הנסמן לשע\"ת כט, ב."],["3579","36","<b>מט\"ט. . הבריאה</b>: ראה זהר פינחס ריז, סע\"א וריש ע\"ב ובהגהות מהרח\"ו שם. מאמרי אדה\"א נ\"ך ע' שלד. וש\"נ. הנסמן לשע\"ת שם."],["3580","37","<b>כי שמי בקרבו</b>: משפטים כג, כא. סנהדרין לח, ב."],["3581","38","<b>מט\"ט. . נער</b>: ראה תוס' יבמות שם."],["3582","39","<b>אנפי זוטרי. . רברבי</b>: נסמן לעיל קלב, ב."],["3583","40","<b>ביו\"ד נברא העוה\"ב</b>: מנחות כט, ב. ראה גם מאמרי אדה\"א במדבר ח\"ג ע' א'רנה."],["3584","41","<b>נבואות ישעי'. . ויחזקאל</b>: ראה גם לעיל לד, א. פו, א. מאמרי אדה\"א הנחות תקע\"ז ע' כב. וש\"נ."],["3585","43","<b>ויחזקאל</b>: אגוזיאיב: ניתוסף: ביצי'."],["3586","42","<b>בשרפים. . קדוש. . ברוך</b>: ראה חולין צב, רע\"א ובתוד\"ה ברוך."],["3587","44","<b>דיצי'. . סנד\"ל</b>: ראה גם ע\"ח (שער סדר אבי\"ע) שמ\"ז, פ\"ו. תו\"ח וירא צט, ג ובהערה 20."],["3588","45","<b>שכל</b>: אגויאיב: אבל."],["3589","46","<b>נבואת נו\"ה דז\"א דיצי'</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קצב. וש\"נ."],["3590","47","<b>מסך. . יצי' לעשי'</b>: נסמן לעיל קטז, א."],["3591","48","<b>מל'. . דיצי'. . לעשי'</b>: נסמן לעיל הערה מל' דבריאה."]]]]});
